/* 平成28年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h28.committeeSessions.push(...[{"id":"h28-20161005-4","meetingId":"h28-c-settlement","date":"2016年10月5日","dateIso":"2016-10-05","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時４４分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を149件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 ただいまより、決算特別委員会を開きます。 それでは、平成２７年度品川区一般会計歳入歳出決算","agenda":"○午前１０時００分開会 ただいまより、決算特別委員会を開きます。 それでは、平成２７年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"１０７ページの広報広聴費、それから１１８ページの防災対策費で幾つか聞こうと思っています。それから１１９ページのしながわ防災体験館改修費で聞きます。それから夏休みには、「親子防災体験」ということで東京都の防災ノートを活用したということでやられていましたけれども、こういった活用によって子どもたちも来たと思うのですけれども、そのような状況や現状について教えてください。","respondent":"古巻防災課長","answer":"７月・８月の利用は総計で２,５００人を超えておりますので、特にお子さんたちや子どもの団体等、いっぱいいらっしゃっていただいて、今後ともしながわ防災体験館を活用いたしまして、地域、それから区民の防災意識の向上に努めてまいりたいと思います。","voiceIndex":4,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"いろいろと区の広報でもアピールされていましたけれども、町会や、それからまた商店街等、各団体にも積極的に、こういった施設があるということもアピールしていただきたいと思っているのですけれども、そのあたりのお考えと、それから学校でも利用されているかと思うのですが、学校でどういった形で利用されているのかお聞かせください。","respondent":"古巻防災課長","answer":"それから周知につきましては、ホームページ、それから広報しながわ等で行っておりますけれども、まだご存じない方、そしてまだご利用いただいていない方、多々いらっしゃるかと思いますので、今後も周知に十分努めてまいりたいと考えております。","voiceIndex":6,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"それから学校も来ていると思いますけれども、子どもたちにもしっかり初期消火の重要性を教えるためにも、この施設をこれからもっと活用していっていただきたいと思います。次に、防災対策費の中で井戸の活用について聞きたいと思います。民間の各家庭というか、家にも井戸というのは結構あると思うのですけれども、今その現状をどういうふうに把握されているのかお聞かせください。","respondent":"古巻防災課長、井浦生活衛生課長、三ツ橋環境課長","answer":"ですので、民間の井戸に関しましては、今のところ、防災面での活用というのは特に計画には入っていないというところが現状です。区として、区内全域での井戸の数ということでは、生活衛生課では１８件把握しています。こちらにつきましては３００ワット以上の揚水規制となっておりまして、手押しのポンプなどは把握できないのですけれども。","voiceIndex":8,"id":"exchange-003"},{"speaker":"沢田委員","kind":"意見","question":"２０件ということはないと思って、届出等していないのかもしれないですけれども、そういった井戸の把握を防災の観点からもしていったほうがいいのではないかと思います。そういったことも、品川区として井戸に対する補助等も考えてもいいのではないかと思うのですけれども、行政としての考え方をお聞かせください。","respondent":"古巻防災課長","answer":"井戸に関してですけれども、区として把握している災害用の井戸については、生活用水で３カ所ほど考えてはありますけれども、また民間の井戸の活用につきましては、まだ基本的には計画上、想定していない部分がありますし、水質的に安定しない部分もありますので。","voiceIndex":12,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"水質は先ほども、飲用に使わなければ多分使えると思いますので、ぜひ水質等も調べながら、しっかりと防災の井戸として活用できるような体制をぜひ整えていっていただきたい、研究していっていただきたいと思います。続きまして１０７ページの広報広聴費のところで、広報紙の件で聞きたいと思います。区の広報紙なのですけれども、現状、発行が年々減ってきているという傾向があると思います。","respondent":"中元広報広聴課長","answer":"個別配送の手段の一つとして、集合住宅、マンション等の管理組合等のご相談があれば、管理組合にまとめてお送りするなど、様々な手法で今後とも検討してまいりたいと思っているところです。","voiceIndex":14,"id":"exchange-005"},{"speaker":"沢田委員","kind":"質問・要望","question":"毎回、毎号毎号というのは難しいと思うのですけれども、今現在では、届けてほしいという要請をしないと各家には届かないという形だと思うのですけれども、各戸配布を、集合住宅というだけではなくて、もっとほかにも、もう少し広げていただいて、できる限りの家庭に届くような体制を整えていただきたいと思うのですけれど、もうちょっと方法をお聞かせください。","respondent":"中元広報広聴課長","answer":"全戸配布につきましては、さまざま募集のタイミングとか、そういう記事もありますので、そういうことも、こちらの編集の際の工夫等も必要ですので、またコストとも見合いながら引き続き研究・検討を重ねてまいりたいと思っているところです。","voiceIndex":16,"id":"exchange-006"},{"speaker":"つる委員","kind":"提案","question":"１１９ページ、防災活動拠点管理運営費、１０９ページ、固定資産台帳整備費、同じページの新公会計制度導入検討経費、そして１０５ページ、非核平和都市品川宣言事業について伺っていきたいと思います。３回繰り返すと記念品が贈呈されるというふうになっていると思いますが、記念品を贈呈した人数とか、どういうものを差し上げているかとか、その辺も教えてください。","respondent":"古巻防災課長","answer":"今後、１０月以降も、幾つかコースを考えまして進めてまいりたいと考えているところです。","voiceIndex":19,"id":"exchange-007"},{"speaker":"つる委員","kind":"提案","question":"この間の一般質問で、しながわ防災体験館を活用した子どもの事故予防教室も開催したらどうか、設置してはどうかということで提案させていただいて、「施設・機材の活用方法について工夫してまいります」というご答弁をいただいておりますが、防災課として、命を救うという視点では同じ趣旨があると思いますし、そこに置いてある機材を活用するという部分では、いろいろな活用がまさにできるかと思うのですが。","respondent":"古巻防災課長","answer":"それから子どもの救命救急ですけれども、防災課といたしまして、先日、防災カフェで「ママの立場で考える防災・減災」ということで、お子さんを持つお母さんたちを対象に、防災の知識の普及・啓発という視点で事業を行わせていただきましたけれども。","voiceIndex":21,"id":"exchange-008"},{"speaker":"つる委員","kind":"質問・要望","question":"次の質問にいく前に改めて言います。次に固定資産台帳と新公会計制度なのですが、平成２５年の第３回定例会で、東京都方式の導入のことを訴えさせていただいて、品川区としても、２３区の中で半分ぐらいが東京都方式ということで採択して進められております。それと、今年度から主査を設置されて取り組まれているということですが、そのあたりの取組み状況について教えてください。","respondent":"立川経理課長、福島会計管理者","answer":"固定資産台帳の整備状況ですが、こちらにつきましては、平成２８年３月に、平成２７年度期首の固定資産台帳として整備が完了したところです。新公会計の導入ですけれども、昨年度から検討を始めまして、検討委員会を設けました。一定程度、基本方針を今年の４月に決めまして、今年の４月からはさらに検討委員会のほうで内容を詰めているところです。","voiceIndex":23,"id":"exchange-009"},{"speaker":"つる委員","kind":"質問","question":"今現在、まさに品川区も、東京都方式、企業会計方式を取り入れていただいて準備いただいているのですが、細かい部分で、仕訳の部分なのですけれども、今、品川区は東京都方式になっていますから日々仕訳という形になると思うのですが、庁内の様々なそういう事務的な、これからも今後ずっと続いていく、そうした作業の中で、予算仕訳という部分があると思うのですが。","respondent":"福島会計管理者","answer":"仕訳につきましては、今ありましたように、日々仕訳を行っていく予定ということで、今、システムのほうを検討しています。実際の執行段階におきましては、約８割は自動的に仕訳ができるのではないかと考えています。","voiceIndex":26,"id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"予算仕訳のところについて抜けていたと思うのですが、実はこれはいろいろな取組み方があると思うのですが、和光市も今、一生懸命取り組んでいるそうなのですが、和光市は仕訳の部分については、予算仕訳といって、日々仕訳ではなくて予算の段階で、いわゆる各所管の段階で仕訳を行うという流れの作業の中で、これは立ち上げのときは結構、体力が要るそうなのですが、ただ、その後。","respondent":"福島会計管理者","answer":"品川区の財政がどうなっているのか、品川区の予算執行がどうなっているのか、そういったことを十分周知するためには、様々な手法を用いて行っていきたいと考えておりますので、それについても今後検討していきたいと考えております。","voiceIndex":28,"id":"exchange-011"},{"speaker":"つる委員","kind":"確認","question":"ぜひよろしくお願いしたいと思います。非核平和都市品川宣言事業については総務委員会で、今月、委員会視察で広島市のほうに行かせていただきます。その後、この平和事業についても委員会の中で質疑があると思いますので、そちらのほうでしっかりと確認していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"私からは、成果報告書１０７ページの奨学金貸付事業にかかわって、給付型奨学金について、区の考えを伺いたいと思います。あわせて、私は来年４月に進学する生徒や学生が対象になるように、何とか間に合うようにと思うのですが、区は実施時期についてどう見ているのか、いつと期待しているのかも伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"国で実施しようとしております給付型の奨学金につきましては、まだ検討チームで整理された内容までしかいただいていない状況にあります。","voiceIndex":32,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"対象や規模を広げて、高校生や大学生や専門学校生も安心して進学できるような制度にしていただきたいと思いますが、少なくとも来年４月の進学時期に間に合うようにしてほしいということと、対象を高校・大学・専門学校にすること、ここをぜひ国に求めていただきたいと思うのですけれども、この点を伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"給付型が必要な対象につきましては、児童養護施設、生活保護であるとか非課税世帯であるとか、進学の強い意思があるにもかかわらず経済的な理由をもとに断念しなければならない人をなくすという方向で、何らかの形の支援の一つと認識しています。","voiceIndex":34,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"国が大学で東京都が高校ということですけれども、ぜひ来年４月に間に合うように働きかけていただきたいと思いますので、その点、改めて伺いたいと思います。改めて、親の病気や失業や、お金が払えず進学を諦める、学業が続けられない、こうした事態は、教育の機会均等に反する事態だと、社会が克服しなければならない問題だと区はお考えになっているのか、その点も改めて伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"区といたしましては、貧困の連鎖を断つということにつきましては、現在、庁内の連絡会議で「子どもの未来応援プロジェクト」というものを立ち上げまして、奨学金に限らず、子どもたちが均等に教育の機会を受けられたりでありますとか。","voiceIndex":36,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、状況を見守るだけではなくて、来年の４月の進学に間に合うように、国や都に強く求めていただきたいと要望したいと思います。ですので、有利子の奨学金も無利子の奨学金も、現在、区は高校が対象ということですけれども、それについて問題がある、課題があると考えているのかどうかも伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"有利子・無利子の貸付けに対する考え方ですが、現在、課題として認識していますのは、様々な国や都の高校の授業料に関しての軽減制度であるとか、そういった制度の認知度が６割を切っているという状況が最近のアンケートでわかりましたので、制度をよく知っていただいて。","voiceIndex":38,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"それについてどう考えているのか伺いたいのと、それといわゆる有利子・無利子、将来借金になる、この返済の重さを考えると申請をためらってしまうという家庭の気持ちを区はどうお考えなのか。私は結局そこで、例えば行きたい学校があるけれども、そこが私立だ。ぜひとも制度の充実を願うのですが、いかがでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"様々な課題があろうかと思いますけれども、今、国・都で拡充が図られているところですので、そちらの動向を注視しながら、区として何をすべきかというのを考えてまいりたいと思ってあります。","voiceIndex":40,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に、給付型奨学金の導入に向けてようやく動き出したというところですけれども、その対象の拡大や規模の拡大や、また進学を諦める生徒が生まれないよう、区としても状況を見て、上乗せも含めてぜひ検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-018"},{"speaker":"木村委員","kind":"質問","question":"私からは、１０６ページの１行目ですけれども、人権啓発費、２,４０７万円余からお聞きいたします。本区にも、小学５年生以上向けの人権啓発冊子というものがあると思いますけれども、区別と差別、男女、そして高齢者、障害者など、様々な人権問題を４コマ漫画を使いながらわかりやすく解説しているようですけれども、お聞きしますが、子どもたちの心に人権問題はどのように映っていると思われるか。","respondent":"島袋人権啓発課長","answer":"この中では、やはりいろいろな差別のこと、どのぐらいの年代の方が知っておられるか、そういったことも書いてあります。地道ではありますが、区報、年２回の特集号があります。そちらの特集号を使いながら、地道に啓発活動等を進めてまいりたいと考えております。","voiceIndex":44,"id":"exchange-019"},{"speaker":"木村委員","kind":"質問・要望","question":"平成２８年４月に施行された障害者差別解消法は、国や自治体、事業者に対し、障害を理由とする差別を禁止するとともに、障害者への合理的な配慮を求めています。本区で始めた取組みというものはどれに当たるのでしょうか。なぜそれを取り組み始めたのでしょうか、お聞かせいただきたいと思います。","respondent":"中山障害者福祉課長","answer":"障害者差別解消法施行に伴う区の対応ということのご質問です。品川区におきましては、３月にまず推進本部を立ち上げました。その中で、４月からの職員対応要領の策定、それから地域の差別の解消のところは自立支援協議会が担うというような役割分担も決定したところです。","voiceIndex":46,"id":"exchange-020"},{"speaker":"木村委員","kind":"意見","question":"いろいろな取組みを今やろうとしているところでありますけれども、大体、今お話を聞いたところですけれども、人権を守り、差別をなくすには、大変な努力というか、いろいろなことが必要だろうと思いますけれども、どのような活動が、また教えが、そして指導が必要なのかということもお聞かせ願えればと思います。","respondent":"中山障害者福祉課長","answer":"障害の理解をした上で、きちっと職員が対応して、お客様として来庁された区民の方が手続きを終えるですとか、あるいは様々な事業に参加できるといったところを、まず職員の気持ちを変えることでやっていく必要があるかと考えています。","voiceIndex":48,"id":"exchange-021"},{"speaker":"木村委員","kind":"意見","question":"区のホームページに「生徒一人ひとりが一人ひとりを人として大切にすること、そのことが人権を尊重することにつながる」とあるとおり、区民全体で配慮できればと思っていますが、本当にそういう意味では、人とのトラブル、いろいろなことのトラブルというのがなくなることと思いますけれども、本区としてのお考えをお聞かせ願えればと思います。","respondent":"村尾教育総合支援センター長","answer":"例えば子どもたちに対しての合理的配慮、一部では、例えば見えづらい子については席を前にするとか、さまざま、小さなものからスタートし、また大きな部分でいきますと、障害に対する理解についても、各学校で十分周知、また研修等を進めながら。","voiceIndex":50,"id":"exchange-022"},{"speaker":"木村委員","kind":"質問","question":"学校には、私たちも道徳という時間がありましたけれども、そういう中で、この合理的配慮ということを教わったのかどうかということはあまりはっきり覚えていないのですけれども、学校でのこれからの教育、子どもたちには本当に大変大事なことではないかと思いますので、どうぞよろしくお願いしたいと思います。この「わ！それでお聞きしますけれども、一言で表現するキャッチコピー「わ！","respondent":"中島企画部副参事","answer":"なかなか一つに絞るというのは難しいところなのですが、やはり新しい魅力、交通の利便性があるまち、なおかつ懐かしさのある、暮らしが感じられるまちということで、キャッチコピーの宣言文では一番最初に「わ！あたらしい、わ！","voiceIndex":52,"id":"exchange-023"},{"speaker":"木村委員","kind":"質問・要望","question":"ホームページには、「『オール品川区』で取り組むためのキャッチコピーと、品川区の魅力発信につながる事業を募集します」とありますけれども、「わ！しながわ」以外に他のキャッチコピーを募集するということになるのでしょうか。しながわ」一つでいいのではないかと思うのですけれども、そこのところも教えていただきたいと思います。","respondent":"中島企画部副参事","answer":"先ほどのホームページにつきましては、昨年度「わ！しながわ」を募集するときに全国公募をさせていただきました。そこを記録として残しておりまして、新しく募集するというものではございません。「わ！しながわ」１本でキャッチコピーとして活用してまいりたいと考えています。","voiceIndex":54,"id":"exchange-024"},{"speaker":"木村委員","kind":"意見","question":"この「わ！次に１０８ページの下から４行目、イメージアップ運動経費、５０８万円余からですけれども、ホームページには、「区民サービス向上の運動で、平成３年より『お役所の体質改善』と『職員の意識改革』を掲げて全庁をあげて取り組んでいます。「区民と区政の架け橋としての自覚」、この活動効果がどのようなことで区政から出てきているのか、これもお聞かせ願えればと思います。","respondent":"中元広報広聴課長","answer":"こちらの活動は平成２１年度から、イメージアップ運動ということで、より品川区民で良かったと言っていただける区役所を目指しているところですが、活動の効果といたしましては、一口で言うのはなかなか難しいところですが、日々のカウンターで職員がお客様と対応する中で。","voiceIndex":56,"id":"exchange-025"},{"speaker":"木村委員","kind":"意見","question":"これは本当に、先ほども言いましたけれども、当然といえば当然のことであろうかと思いますけれども、対人でありますから、いろいろと感情的なものも出てくるかと思いますけれども、その点はまたお願いしたいと思います。広報ボランティアの活動というのもありますけれども、これは大変大きな役目をするのかと思いますけれども、どのようなことをするのかお聞かせ願えればと思います。","respondent":"中元広報広聴課長","answer":"広報ボランティアといたしましては、大きく２種類ございまして、広報紙の編集に関しまして子育て支援特集号のときに区民の方に参加していただいて、編集や写真等で記事に参加していただいたりという部分と。","voiceIndex":58,"id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"私からは、１０７ページの広報紙発行経費、１０９ページ、シティプロモーション推進経費、１０６ページ、人権啓発費をお伺いいたします。広報紙発行経費、広報しながわについての質問をします。「え、何でですか」とまた聞き返したところ、「いや、新聞はとっていない。希望があれば個別配送に応じるという対応を今後とられてはどうかと考えますが、いかがでしょうか。","respondent":"中元広報広聴課長","answer":"広報紙につきましては、あとスマートフォン等での、区のホームページ等での閲覧もできるようにしています。ただ、そこのところにつきましても、今後新しい技術が出てきておりますので、見る方が見やすいようにさまざま工夫してまいりたいと考えているところです。","voiceIndex":61,"id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"ポスティングをやられても、どうしても要らないよと断る人もいらっしゃると思いますし、また事業の応募の締め切りという課題もありますけれども、そのあたりはうまく工夫を凝らして、最終的には広報しながわのポスティングという方法も考えられるかと思いますけれども、その点についていかがお考えでしょうか。","respondent":"中元広報広聴課長","answer":"ですので、毎号ということではなくやっている自治体もあるようですので、今後どのような形で、費用対効果等、見極めながら検討してまいりたいと思います。","voiceIndex":63,"id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"経費が２倍かかる。大変な経費だと思いますけれども、これは情報発信ということで、そのぐらいの経費がかかってもやむを得ないところがあると思いますので、そのあたりをしっかりと検討していただきたいと考えております。次にシティプロモーションについてお伺いいたします。「わ！しながわ」、シティプロモーションの効果の分析・検証は、区としてはどのように行っているでしょうか、伺いたいと思います。","respondent":"中島企画部副参事","answer":"将来的には、やはり定住人口ということですので、経済効果を含めて様々な指標を検討してまいりたいと思っています。","voiceIndex":65,"id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"ですから、私はやはり東京都区部のシティプロモーション、都会のシティプロモーションとしての目的もしっかりとあるということを打ち出していったほうがよいと考えております。やはり地方のまちではない、そうした都会のシティプロモーション、こうした目的を改めてはっきりさせるべきだと考えておりますけれども、その点についていかがお考えでしょうか。","respondent":"中島企画部副参事","answer":"シティプロモーションの目的につきましては、確かに地方などの自治体では観光をメインにシティプロモーションをしているところもありますが、やはり品川区といたしましては、都市部のといいますか、品川区のプロモーションは将来の人口減少社会を長期的にも見据えまして。","voiceIndex":67,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"統一イメージに欠ける」というような、ちょっと残念な記述がありますので、私としては逆に、個性がいろいろあるということがワンパッケージになっているのが品川区のよさなのだということを売り込んでいったらいいのかなと考えておりますけれども、こうした出版がされるという、他人のというか出版社の方の客観的評価に対して、区は今後どうやって挽回していくのか、対処していくのか。","respondent":"中島企画部副参事","answer":"なかなか統一イメージに欠けるという話もありましたので、やはり「何とかのまち」というのは、品川区は多彩な魅力がありますので、そういうのは難しいので、「わ！しながわ」を合い言葉に統一的に発信してまいりたいと考えています。","voiceIndex":69,"id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"続いて人権啓発費、ＬＧＢＴについてお伺いいたします。しかし、このＬＧＢＴの方たちのそうしたことをなくしていきたいという運動が高まっておりまして、渋谷区では条例ができた。世田谷区では要綱ができている。こうした自治体がありますけれども、区はＬＧＢＴの方たちに対してどのように取り組んでいくか、今後の方向性はどうなのかということをお聞きしたいと思います。","respondent":"島袋人権啓発課長","answer":"こちらの中にはハラスメント、セクシャル、パワー、モラル、セクシャルマイノリティーなどの方々の相談を受けておりますが、そちらのほうでも対応してまいりたいと考えています。","voiceIndex":71,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問","question":"１１９ページの２項４目、防災対策費と、１０６ページ、１項１目、一般管理費、庁舎等維持管理費について伺います。本庁舎屋上防水リニューアル等工事費について２点伺います。そして、花壇もとてもきれいに手入れがされていましたが、壁の緑化もされていて、水やりが大変なのではと思いますが、現在はどのように花壇の水やりが行われているのでしょうか。","respondent":"立川経理課長","answer":"今後とも、そういったＰＲ紙であるとか、広報であるとか、ホームページを活用して周知に努めてまいりたいと思います。近隣の保育園のお子さんが定期的に使っていただいているということで、利用率はかなり高いと認識しています。","voiceIndex":74,"id":"exchange-033"},{"speaker":"田中委員","kind":"質問","question":"すてきだと思います。２０１４年に雨水の利用の推進に関する法律が成立し、２０１６年４月１日から施行されています。区として、雨水タンクや雨水ますの助成も行っていますし、今後、改修工事を区の施設にもどんどんつけていく方向と伺っているのですけれども、どうなのでしょうか。","respondent":"小林施設整備課長","answer":"おっしゃるとおり、建設する際、できる限り、それを考慮して計画を進めているところです。","voiceIndex":80,"id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"防災対策費の防災ラジオについて伺います。４点伺います。避難所および関係機関、４００台の配布先には、特別養護老人ホームや高齢者デイサービス、障害者施設等、要支援者の方がいる施設に届いているのか伺います。防災ラジオの頒布を拡大しない理由を伺います。委員会では、発注ロットが５,０００台という単位にあるかのような説明にもとれましたが、拡大をちゅうちょされている要因を伺います。","respondent":"古巻防災課長","answer":"建ててから大分、老朽化しておるというところと、あと法制度上、電波法の改正によりまして、現在の電波の規格ですと、まだ数年先ですけれども、継続して使うことができないところがありますので、こちらを見据えながら、防災ラジオ。","voiceIndex":82,"id":"exchange-035"},{"speaker":"田中委員","kind":"質問","question":"台風１０号では、東北地方のグループホームで洪水により尊い命が失われました。避難勧告の避難準備情報という防災用語が十分理解されていなかったという大きな問題も明るみに出ました。避難準備情報とは、要配慮者は立ち退き避難するということの説明も徹底し、実践できるような体制整備も必要です。今後の展開について区の見解を伺います。","respondent":"古巻防災課長","answer":"防災ラジオの今後の展開ですけれども、先ほどもお話しいたしましたとおり、今後の防災行政無線の更新とあわせまして、どういった形で今後十分な情報が行き渡るような手段をとれるのかということを踏まえて、十分検討してまいりたいと考えております。","voiceIndex":84,"id":"exchange-036"},{"speaker":"田中委員","kind":"質問","question":"避難所運営に関連して伺います。そこで伺います。２０１２年度修正の品川区地域防災計画第３章「避難所の設置および運営」の項目があります。構成員が同じなのですから、平常時から名称を一本化するほうが有効かと考えますが、いかがでしょうか。端的にお願いします。","respondent":"古巻防災課長","answer":"名称に関しましては、いろいろ考え方もあるかと思いますので、どういった形でできるかということはありますけれども、明確にわかるような形で周知していきたいと考えております。","voiceIndex":86,"id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"防災用語がわかりにくく混乱を招いてしまったら本末転倒だと思いますので、検討を要望します。品川区では、このような取組みが検討され、実施が進められているのか伺います。そして、様々なマイノリティーの方が利用できる「だれでもトイレ」の設置が必要だと考えますが、現在の避難所運営の中で、そのような場所の確保は考えられているのでしょうか。","respondent":"古巻防災課長","answer":"そういった、別の面といいましょうか、先ほども少し話題に出ました防災学校のほうの、例えば女性のコースでありますとか、そういったことも企画していきながら、避難所に関しまして様々な方への対応を進めてまいりたいと考えているところです。","voiceIndex":88,"id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"要望なのですけれど、今後、建替えの施設において、「だれでもトイレ」には、大人用おむつ替えベッドで十分幼児も対応できると思いますので、大人用のおむつ替えベッドを設置するという視点を改築時には取り入れてほしいと要望いたします。もう一点は確認です。その改善はされたのでしょうか。ほかにも同じようなところがあるのかも確認したいと思っています。","respondent":"古巻防災課長","answer":"品川学園の校庭の件につきましては、ちょっと現状で把握していないところですが、点検いたしまして、対応がきちんとできるようにはしていきたいと考えております。ほかの学校につきましても、同様にきちんと対応ができるような設備を整えてまいりたいと思います。","voiceIndex":90,"id":"exchange-039"},{"speaker":"田中委員","kind":"確認","question":"ぜひ、確認等よろしくお願いいたします。先ほどから話に上がっていました防災カフェ、防災学校のカリキュラムの一つで防災カフェが行われていたということでした。このような学習会は各地域で必要だと考えています。非常時に母乳がとまってしまって困ったという話は、私の周りでも多く声がありました。液体ミルクについての評価や検討は品川区ではされているのでしょうか、お聞かせください。","respondent":"古巻防災課長","answer":"液体ミルクに関するご質問です。液体ミルクにつきましては、そういった製品があることにつきましては把握しておりますけれども、まだ具体的な検討には至っていない状況です。今後、情報収集をしてまいりたいと考えております。","voiceIndex":92,"id":"exchange-040"},{"speaker":"渡部委員","kind":"確認","question":"３点伺っていきたいと思います。庁舎管理の観点で１つ、ページ数で言うと１０７ページになるのでしょうか。ケーブルテレビが同行されていたのですね。一般質問だったか委員会質問、総括質問、何かの中で、やはり区がこれから補助していく事業ということで、確認の意味も込めて、行政の方々もどなたか一緒に参加されてという中では、実は子ども未来部長も参加されて、さまざま確認されたということです。","respondent":"齋藤子ども未来部長","answer":"あわせて私も義援金を託されましたので、市長には、子どもたちとお渡しするシーンを集合写真を撮らせてくださいという話をしましたら、市長、両副市長、教育長、部長級、全ての幹部職員に歓待していただきまして、市長からは、品川区に対する厚い期待、感謝の気持ちと。","voiceIndex":96,"id":"exchange-041"},{"speaker":"渡部委員","kind":"質問","question":"例えばこれが今後、宮古市から子どもたちをまた招いて、それは宮古市のお金なのかというところなのですけれども、様々な交流が生まれればいいなと思う反面、また例えば一歩、この交流事業というものが市町村交流に発展すればなどという思いもありましたので、伺わせていただきましたが、これからもこのような活動を通して子どもたちの健全育成に寄与していけると思っていてよろしいのでしょうか。","respondent":"齋藤子ども未来部長","answer":"今年で重ねて４回目になりました。来年度以降も引き続き、宮古市との草の根の交流をしていきたいと考えています。それが健全育成につながるものだと考えております。","voiceIndex":98,"id":"exchange-042"},{"speaker":"渡部委員","kind":"確認","question":"確認できましたので次に進みます。庁舎管理のところは、会議室のことを聞きたいのですけれど、総合庁舎があって、第二庁舎、第三庁舎と、会議室というのはさまざまありまして、様々な会議体があると思います。会議室等が幾つぐらいあって、稼働率はどれぐらいなのかというところを教えていただけますでしょうか。","respondent":"立川経理課長","answer":"会議体の数ですが、条例や要綱で設置が義務づけられているものについては５０程度なのですけれども、そのほか事業上必要のある会議などが、概算ですが、大体３００から４００ぐらいはあるかです。","voiceIndex":100,"id":"exchange-043"},{"speaker":"渡部委員","kind":"質問","question":"しかしながら、必要な研修や会議というのを重ねていただいて、縦の会議だけでなく横の会議なども当然必要となって、これから区民サービスのために区政を進めていただくのですけれど、例えば今ある中での話ですので、では会議室が増やせるかといったらそんな話ではないと思うのですけれども、これだけの稼働率があると、要は会議体の時間をずらさなければならないですとか、もしくはここに会議室がなくて。","respondent":"立川経理課長","answer":"それでもやはり足りないという場合には、区議会にご協力いただいて、委員会室等を使わせていただいているというのが現状です。","voiceIndex":102,"id":"exchange-044"},{"speaker":"渡部委員","kind":"質問・要望","question":"会議体が多いのだというところの確認をさせていただきました。効率的な運営にこれからも努めていただきたい反面、やはりその中で生まれたいい施策というのを進めていただきたいと思いますので、ちょっと会議室が気になったのでお伺いさせていただきました。これは、どなたかわかれば教えてください。僕も、３月から走っているのは見ていました。品川区はこれを知っていましたでしょうか。","respondent":"鈴木文化観光課長","answer":"ご質問の東急電鉄の車内広告ですが、東急電鉄から区のほうに情報が欲しいという協力依頼がありまして、区から情報提供した内容を広告として掲載していただいているというものです。","voiceIndex":104,"id":"exchange-045"},{"speaker":"渡部委員","kind":"質問","question":"シティプロモーションの観点で聞こうと思ったので見ていたのですけれど、今、お話を課長からいただきました。情報提供だけで、これは費用的なものの発生というのは一切なかったのでしょうか。","respondent":"鈴木文化観光課長","answer":"こちらは東急電鉄の自主企画で、復刻電車の中で、池上線と東急多摩川線の沿線の魅力を発信する事業だということで、経費等については、独自事業ですので、区のほうは情報提供のみであって、経費等はかかっておりません。","voiceIndex":106,"id":"exchange-046"},{"speaker":"渡部委員","kind":"質問","question":"僕も調べさせていただいて、お金のどうこうというのはわからないのですけれども、３月から動き出しています。大田区の広告というかお知らせもあるのですけれど、そのほかに神社の例大祭で、ちょうど１０月開催、雉子神社、これは五反田です。この電車は逆にいつまで走るというようなのがあって、例えば次のタイミングだとこういう広告が出るみたいな、その辺のやりとりがあるのかどうか教えてください。","respondent":"鈴木文化観光課長","answer":"この企画の内容の提供する情報ですが、今ご指摘のあったイベント関係については９月から１１月の予定の内容だとお聞きしております。","voiceIndex":108,"id":"exchange-047"},{"speaker":"渡部委員","kind":"質問","question":"２９分の１に当たる。どんどん区に来てほしい。もしくは電車というもの、日々皆さんが活動するわけですから、その中で様々な仕掛けをつくっていくというのはすごく有効的なのかと思うのですが、いかがか。今後これにどういうふうに絡んでいくかという部分と、シティプロモーションという観点で、電車という乗り物をどういうふうに活用するかというところ、何かありましたら教えてください。","respondent":"中島企画部副参事","answer":"今年度、シティプロモーションとしてつくるコマーシャル動画をトレインチャンネルで流して、またそういう形の車内の媒体のメディアを活用して、積極的に情報発信をしてまいりたいと考えています。","voiceIndex":110,"id":"exchange-048"},{"speaker":"渡部委員","kind":"質問","question":"例えば多分、電車、乗り物ですから、せめて１日前ぐらいには、この電車は何時何分発、何時何分着で、どういうふうに走るという情報ぐらいはあると思うので、例えばそういう情報を毎日もらって、品川区も逆にこの池上線のレトロ電車というのをどんどんアピールすることによって、それに乗れたら品川区の情報があるよではないですけれども、何か東急電鉄も品川区もウイン・ウインになるような。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-049"},{"speaker":"新妻委員","kind":"質問・要望","question":"私からは１１３ページ、八潮公園多目的広場、１１９ページ、しながわ中央公園防災備蓄倉庫整備、同じく商店街放送設備接続工事、そして１０７ページ、奨学金貸付事業についてお伺いいたします。この八潮公園多目的広場の主な利用の用途と利用者の世代を教えてください。あわせて、この多目的広場の利用目的に規制があるのかどうかを確認させていただきたいと思います。","respondent":"池田スポーツ推進課長","answer":"ここ最近の利用人数ですけれども、委員がお話しされたように、年々増加しているという段階でございまして、日曜日・祝日の使用につきましては、貸出しの日については全て利用されているというふうな状況です。","voiceIndex":114,"id":"exchange-050"},{"speaker":"新妻委員","kind":"質問","question":"当然ながら、避難所、避難・防災のときにも使われるところでありますが、実はここは大きな広場なのですけれども、看板が１つあって、ここからこっちは団体利用、ここからこっちは個人利用というふうに分かれているのです。これは、少年サッカーや団体に貸し出しているときに、個人利用ができないというような規制はあるのでしょうか。","respondent":"池田スポーツ推進課長","answer":"八潮公園多目的広場の利用についてですけれども、貸切りにつきましては、３分の２の面積については貸切りということで、３分の１については一般利用、オープンということで利用していただいてあります。","voiceIndex":116,"id":"exchange-051"},{"speaker":"新妻委員","kind":"質問・要望","question":"これは品川区ではないので、なかなかできないこともよくわかりますが、であればこそ、ここの多目的広場に隣接されている公園にあるところ、ちょっと空間があって、遊具がありますけれども、ここをさらに整備を進めて、小さいお子さんでも遊べるような公園づくりを、ここもあわせて進めていただきたいと思いますが、２点ご答弁をお願いいたします。","respondent":"池田スポーツ推進課長、溝口公園課長","answer":"今後、何かそういったものについては、私どもと、それから管轄する公園課、そして教育委員会等、いろいろとまたちょっと、何かできないかということについては考えさせていただきたいと考えています。改修する際には、委員お話しのように、地域の方のご意見といったものを踏まえながら、より皆さんに親しまれる公園、利用してもらえる公園になるように整備していきたいと考えています。","voiceIndex":118,"id":"exchange-052"},{"speaker":"新妻委員","kind":"質問・要望","question":"わかりました。しかし、安全対策は大事だと思います。団体利用される方にも、こっちは個人で利用されるから気をつけてねというような、しっかりと注意喚起を促すようなこともしっかりと進めていただきたいと思います。この公園ですが、今、現状、１２月オープン、完成予定というふうになっているのですけれども、予定どおり、この１２月にこれが完成するのかというところを、１つ先に確認したいと思います。","respondent":"溝口公園課長","answer":"しながわ中央公園の拡張部分の工事につきましては、今現在、順調に工事が進んでいるものです。工事期間といたしましては年内を予定しております。開園につきましては年明けの１月を予定しているものです。工事等については順調に進んでいるものです。","voiceIndex":121,"id":"exchange-053"},{"speaker":"新妻委員","kind":"質問","question":"この公園ですが、防災拠点となるというところが大きな意味だと思うのです。震災にはやはり、怖い思いがしますから目を背けたい。だけれども、日々からの備えが大事であって、区民の皆様により意識を高めてもらわないといけないというところもありますので、ここの公園が普通の公園とは違って防災拠点なのだという、その看板、意識づけが必要かと思いますが、いかがでしょうか。","respondent":"溝口公園課長","answer":"そういった観点からいたしまして、開園時に、ここの公園につきましては防災機能をしっかり有した公園であるということはアピールしていきたいと考えていますし、それがわかるようなサインというものを設置していきたいと考えているものです。","voiceIndex":123,"id":"exchange-054"},{"speaker":"新妻委員","kind":"質問・要望","question":"そのような整備、整えていただきたいと思います。続きまして、同じく防災の強化というところで、商店街放送設備工事につきましてお伺いいたします。これまでに接続工事は何カ所の商店街で完了したのか。何カ所で設置可能なのかというところを教えていただきたいと思います。","respondent":"古巻防災課長","answer":"今後なのですけれども、今のところ、これから先、ちょっと具体的にどこの商店街とということでは計画がございません。平成２４年度から計画しておりまして、接続する予定だったところにつきましては、平成２７年度末で接続が完了しているといった状況です。","voiceIndex":125,"id":"exchange-055"},{"speaker":"新妻委員","kind":"質問","question":"設置できるのに設置できないという状況なのか、もともと接続ができないという理由があるのか、そこら辺をもう少し詳しく教えていただけますか。","respondent":"古巻防災課長","answer":"設置できる・できないに関するご質問ですけれども、そもそも放送設備を有している商店街というのが、当初の調査によりますと２０カ所程度ということで、呼びかけをして近隣との関係等を含めまして設置が可能になったところが、先ほどお答えいたしました１１カ所です。","voiceIndex":127,"id":"exchange-056"},{"speaker":"新妻委員","kind":"質問","question":"やはりこれは防災の強化というところでは大事だと思うのです。設置できないところは、なぜ設置ができないのか、そこを区がちゃんと支援していくというところが必要なのではないかと思うのですけれども、いかがでしょうか。","respondent":"古巻防災課長","answer":"働きかけにつきまして、これで最後ということで考えているわけではございませんので、お申し出があれば接続については検討してまいりたいと思いますし、そのあたり、今後、防災行政無線更新もありますので、あわせて検討してまいりたいと考えております。","voiceIndex":129,"id":"exchange-057"},{"speaker":"新妻委員","kind":"質問・要望","question":"先ほど詳しく区の意向もお伺いさせていただきましたけれども、いよいよ満を持して国が給付型奨学金を推進いたしました。今、品川区奨学金制度がありますけれども、なかなか利用されていない現状もある中で、今、「子どもの未来応援プロジェクト」を立ち上げて、現状、確認されていると思います。こことあわせて必要な方向性をしっかりと見出していただきたいと思いますが、いかがでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"プロジェクトの中で、経済的な支援も金銭的な支援も含めまして、その他、学習支援等、総合的に検討していく方向で、今、進めているところです。","voiceIndex":131,"id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、１１２ページ、文化スポーツ振興費で、区民スポーツ、障害者スポーツに絡んでお聞きしたいと思います。２０２０年東京オリンピック・パラリンピックに向けて、各地でイベントや、住民がスポーツに親しむ、触れ合う取組みが行われているかと思います。学校教育の中にもこういったことが含まれてきているかと思います。そのような中、区の区民スポーツへの認識をまず伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"その１７地区のスポ・レク推進委員会が中心となりまして、地域の方のスポーツについていろいろな教室を開いたり、もしくは大会を開いたりというようなことで、皆様にスポーツをより親しんでいただこうということで取り組んでいるところでございまして。","voiceIndex":135,"id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問","question":"まだ多くの区民がスポーツに触れられないというか親しめない、できない状況があると思うのですけれども、ここの区の認識はいかがでしょうか。そして、区が現在把握している、区民がスポーツに取り組んでいる割合というのはわかるでしょうか。そして、区民のスポーツ要求を把握されているのか。多くの区民がスポーツがなかなかできていない状況というのは、理由はつかまれているのか伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"スポーツをできない方の環境ですけれども、確かに健常の方、それから障害のある方ということで、区民の皆様にはいろいろな方がいらっしゃると思いますけれども、まず私どものほうで、障害をお持ちの方についてはどのようなことをやっているかといいますと。","voiceIndex":137,"id":"exchange-060"},{"speaker":"石田（ち）委員","kind":"質問","question":"まだ多くの区民がスポーツをしようという状況にないのではないかと。それが、スポーツができる環境にないということの理由をつかまれているかということを伺ったので、そこをもう一度お願いします。","respondent":"池田スポーツ推進課長","answer":"スポーツができない理由として、やりたくてもですけれども、そちらにつきましては、私ども、各スポ・レク推進委員会での、まず教室等を行った場合のアンケートを実施することもあります。","voiceIndex":139,"id":"exchange-061"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私のほうから言わせていただくと、体力・スポーツに関する世論調査というのを文部科学省が取り組みまして、平成２５年のものなのですけれども、ここでは、運動やスポーツを行わなかった理由として、仕事が忙しくて時間がないからというのが断トツなんです。リオのパラリンピックでも多くの方が感動したと思うのですけれども、障害者のスポーツ要求は障害者のスポーツ要求として把握はされているのでしょうか。","respondent":"池田スポーツ推進課長","answer":"そういった場合にはルールというものを変えさせていただいて、例えば本来ですと１０ｍ先のものに的を当てるというものについては、障害のある方によっては、例えば３ｍ手前にするとか、そういったようにルールを変更しながら。","voiceIndex":141,"id":"exchange-062"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そのようにルールを工夫しながらというのはあると思うのですけれども、やはり大きく障害を持たれた皆さんが不安に思っている、また障壁となることは、バリアフリーが整っていない施設が多いということなのではないでしょうか。宿泊できるかは別にして、障害者が１人で行ってもスポーツに触れることのできる障害者スポーツセンターを、品川区にもぜひつくっていただきたいと思いますけれどもいかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"それが実現されれば、またいろいろと変わってくるかと考えています。","voiceIndex":143,"id":"exchange-063"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして広めてほしい」と。ですので、ぜひそういった環境整備も進めていっていただきたいと思います。多くの区民が、障害のある・なしにかかわらずスポーツに親しめるよう、これから状況把握といいますか、ぜひ区民のスポーツ要求、そして障害者のスポーツ要求をしっかりつかんでいただいて、そして、その課題を整理して進めていっていただきたいと思いますけれども、いかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"委員のご意見のように、これからも東京都等に対しまして、城南地区、できれば品川区にということで要望するようにいたします。","voiceIndex":145,"id":"exchange-064"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ要求をつかんでいただいて、そして区民のスポーツ推進につながるように、レガシーになるように努めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-065"},{"speaker":"西本委員","kind":"質問・要望","question":"非常に丁寧に対応されているということで非常に感心したのですけれども、そういう他の国の方々に対する対応についての職員の研修、それから他部署との間の連携がどういうふうになっているのでしょうかということです。これをご存じですか。これは大井町。今、第２弾が出ているのですかね。日本郵政ですから全国展開もあり得るかと思っているのですが、これの協力した経緯をお知らせいただきたいと思います。","respondent":"仁平情報推進課長、鈴木文化観光課長、米田人事課長、中島企画部副参事","answer":"そういう方向けに携帯電話のほかにＷｉ－Ｆｉ環境が整備できていることは。大井町周辺の切手シートの作成の経過ですが、それはＮＰＯ法人まちづくり大井が郵便局と連携して作成・販売したシートです。それから窓口対応の中で、外国語で対応している職員もいたかと思いますけれども、例えば職員の自己啓発の中で。こちらも日本郵政株式会社の協力による発行でございまして、品川区といたしましては、品川区の魅力を伝えるしながわ百景をテーマにしたもので。","voiceIndex":149,"id":"exchange-066"},{"speaker":"西本委員","kind":"提案","question":"款が違いますので、あまり突っ込んで言いませんけれども、第２回定例会で提案させていただきました、商店街等々の観光を含めた形でのＷｉ－Ｆｉの活用というのは、これから２０２０年の東京オリンピック・パラリンピックに絡めて非常に大切な契機になるのではないかと考えていますので、そのリンクを、中心は少し違うところになるかもしれませんけれども、Ｗｉ－Ｆｉの対応、考え方というのを。","respondent":"仁平情報推進課長、米田人事課長、中元広報広聴課長","answer":"今現在は、接続の手続をしていただきますと区のホームページに誘導という仕組みにしていますけれども、我々のほう、今後、これのトップページといいますか。私も先ほど申し上げましたように部署間、職員間の連携ということでは全庁的に進めているところです。フレーム切手の枠組みですが、あちらの会社の仕組みの中でやっているところがございまして、ただ。","voiceIndex":154,"id":"exchange-067"},{"speaker":"渡辺委員","kind":"質問","question":"１１４ページ、オリンピック・パラリンピック開催周知事業で伺ってまいります。先ほど来ありました、まず最初に項目にある中で、ブラインドサッカー体験会・講演会開催の点から伺います。そういう意味で、この出前体験、ちょうどこの年からだったと思うのですが、どれぐらいの実績があって、どのような効果が見られたのかをまず１点伺います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"実績ですが、全部で１０回、実施いたしました。","voiceIndex":159,"id":"exchange-068"},{"speaker":"渡辺委員","kind":"質問","question":"これは本当に機会を広めるべきだと思うので、そんな思いを一つ伺いたいと思います。文字どおり、それを見たら、やはり僕らで感じるのですから、子どもなどは感受性が高い中で、障害者スポーツというものの認識が非常に上がるような気がしました。この映像を通じた教育といいますか、学びというか、啓発の活用を、現状と今後の方向性みたいなものを教えていただければと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"こちらは東京都のホームページで自由に見られるようなことにはなってありますが、今後、教育委員会と連携し、こちらの映像の活用等も検討してまいりたいと思います。","voiceIndex":161,"id":"exchange-069"},{"speaker":"渡辺委員","kind":"質問","question":"２０２０年に向けて、いろいろな段階があると思います。ただ、そこの中で節目は、国際化の中で来訪者の方にも区民の方にも、まず２０２０年を、いい経験をしたとか楽しかったと思ってもらえることだと思うんです。もう残り、プレオリンピックまで３年と考えたら、そろそろ仕掛けてもいい頃合いではないかという思いがあるので、フェスタの一斉開催を軸に今後どう展開していくのかを伺えればと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"来年の１０月２８日がちょうど１,０００日前という区切りの年に当たりますので、そうした意味で１,０００日前のイベントを何かしら仕掛けていきたいと考えています。委員ご指摘のとおり、これまでのフェスタでも文化的な要素は少しずつ取り入れてあります。","voiceIndex":163,"id":"exchange-070"},{"speaker":"渡辺委員","kind":"質問","question":"そして項目も多岐にわたりますが、取り急ぎという点で２点ほど、質問で伺いたいと思います。こんな誘致交渉は簡単なことではないと思いますが、ぜひとも誘致・招致に力を入れるべき喫緊のテーマだと思います。品川区のメリットのために、文化的な要素からホスピタリティハウスの誘致などを、早目に、あるいはもっと、現状もやっている中で力を入れるべき点ということで一つ伺いたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"委員ご指摘のとおり、例えばどこかの国を誘致するという方法もありますし、あるいは品川ハウスということで、品川区自らを発信するという方法もあろうかと思います。今後、積極的に検討してまいりたいと思っています。","voiceIndex":165,"id":"exchange-071"},{"speaker":"渡辺委員","kind":"質問","question":"その中には、まさしく自治体がリードしている部分もあるし、企業力が全面に活かされていたり、そういう意味では、２０２０年に向けたときに、ああ、これぞオール品川で取り組むべきことだと。具体的なものはまだこれからだとしても、今の意気込み的なもの、この文化プログラムにどうタッチしていくか。東京都や文化庁の取組みに、どう品川区がかかわれるか、ちょっとその点を教えてください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ただ、基本的には区民の方を主役ということで考えてあります。これまでも、区独自だけでなく、例えば文化振興事業団、スポーツ協会、観光協会、国際友好協会の４法人が一体となって様々なことを、昨年度あたりから実施を始めました。例えば体育の日記念事業もその一つです。","voiceIndex":167,"id":"exchange-072"},{"speaker":"渡辺委員","kind":"質問","question":"大きな方向性はそれで間違いないし、ぜひともという思いがあります。もう一度、精査し、あるいは今までの行政仕事だけではなく、様々な世代の発想と、あと企業力も活かして、大変質の高い、東京や日本を代表する文化プログラムを品川区が発信していくべきだと。そこにはいろいろな労力や、予算も含めて投資すべきだと思いますが、最後にその決意を伺って終わります。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"文化プログラムにつきましては、品川区もまさにリード的に、品川区民芸術祭をはじめ、やってきていたところで、自負はしています。ただ、２０２０年を契機として、さらにそちらを充実させ、いろいろな関係団体と連携しながら努めていきたいと考えています。","voiceIndex":169,"id":"exchange-073"},{"speaker":"藤原委員","kind":"質問","question":"１０６ページの、まず人権啓発費ですけれども、一般質問でも伺いましたけれど、ヘイトスピーチの問題なのですが、今年の５月にヘイトスピーチ解消法が成立しまして、私が今年質問したときにはまだ「国の動向を見ます」ということを部長から答弁をいただいたのですけれども、それでこの法律が成立しました。管理職が足りるようになれば６０歳を切っていくのか、お伺いします。","respondent":"島袋人権啓発課長、米田人事課長、伊崎地域活動課長、小川オリンピック・パラリンピック準備課長、池田スポーツ推進課長、鈴木文化観光課長、立川経理課長","answer":"区においては、引き続き様々な人権課題の一つとして、知識の普及と啓発活動を推進し。これは年金の支給開始年齢が延びていることによって、段階的に６５歳までフルタイムを基本とするということで。現在、早川町と山北町との交流をしておるところですけれども、こちらは品川区の中では普段体験ができない自然との触れ合いができまして。そのような中で、今後の展開ですが、できれば組織としては強化してまいりたいと考えているところです。","voiceIndex":172,"id":"exchange-074"},{"speaker":"藤原委員","kind":"質問","question":"何とも言えない酸味がかったにおいがするじゃないですか。これだけフェスタが人数が増えて、やることが増えて、都と国との交渉が増えて、３人の体制で本当に大丈夫でしょうか。水と緑の市町村との交流事業なのですけれども、すばらしい施策なのですけれど、私はもう、一部の方がご利用などという施策というのは、発展的に終わっていってもいいと思うのですけれども、改めてその辺はいかがでしょうか。","respondent":"米田人事課長、鈴木文化観光課長、小川オリンピック・パラリンピック準備課長、伊崎地域活動課長、立川経理課長","answer":"ちなみに、一般の職員の場合は様々な号給がありますが、再任用職員の給料はその枠の中には収まっているということで。品川区につきましては、施設の性質、それから事業の実施状況等に鑑みまして、現在の時点では非常勤の方にシフトで。所属長といたしましては、限られた人材の中でできるだけ職員が楽しくモチベーションを上げて仕事に取り組めるように配慮しています。そういった意味合いで、これからもますますいろいろな多くの方に使っていただけるように頑張っていきたいと考えております。","voiceIndex":180,"id":"exchange-075"},{"speaker":"藤原委員","kind":"質問","question":"人事課長、オリンピックはスポーツですよね。歴史館は歴史と文化ですよね。ここに人を充てないということは、区の行政が品川区の歴史・文化、そしてスポーツを軽視しているということではないですか。いかがでしょうか。","respondent":"米田人事課長","answer":"今後も、職場の運営の状況等を見据えつつ、またオリンピック・パラリンピックに関しては大会組織委員会への職員派遣ということも今年度から行っておりますので、中から外から、それから他部署との連携も含めて、こちらについての機運を盛り上げていきたいと考えています。","voiceIndex":186,"id":"exchange-076"},{"speaker":"藤原委員","kind":"質問","question":"最後に区民スポーツ大会なのですけれども、私の個人的意見かもしれませんけれども、射撃だったらスケートボードだと思うのですけれども、これに関してはいかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"射撃というものは大人のスポーツですけれども、最近特にスケートボードというものが大変はやっておりまして、オリンピック種目にもなっております。私としましても、ぜひそういった、スケートボードのような新しい競技は応援していきたいと考えておるところです。","voiceIndex":188,"id":"exchange-077"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１０４ページのＷｉ－Ｆｉスポット整備について、１１９ページ、災害時応急物資確保費、防災活動拠点管理運営費、そして１１４ページ、オリンピック・パラリンピック開催周知事業、１０６ページの庁舎等維持管理費、１０５ページの危機管理室経費についてお伺いします。危機管理についてですが、皆さん、今、もう既に流行っているのかどうかわからないですけれど、ポケモンＧＯはご存じでしょうか。","respondent":"立川経理課長、小川オリンピック・パラリンピック準備課長、古巻防災課長、久保田危機管理室長","answer":"今後につきましては、ただいまご指摘いただきましたように、検討してまいりたいと考えております。区内開催予定競技等のＰＲをしてくださるという団体への支援ですが、このところ、いろいろなところから。本年度につきましては、先ほども少しお話をいたしましたけれども、スタンプカードを発行いたしまして、３回ご来場いただくと記念品を差し上げている。そうした場合には、まずは庁内にあります危機管理室、生活安全担当、また交通安全担当等と連携しながら、外部の警察や消防等。","voiceIndex":191,"id":"exchange-078"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"危機管理ですが、これはポケモンＧＯに限らず、今後も、観光に力を入れている品川区ですから、多くの方が、訪日外国人を含めて多くの外国人や観光の方たちが来る中で、危機管理と観光と、しっかり連携をとっていただいて、万全に様々な方々をお迎えできるような仕組みをぜひとっていただきたいと思いますので、縦割りではなくて、しっかりよろしくお願いいたします。それでＷｉ－Ｆｉスポットにいきます。","respondent":"古巻防災課長、仁平情報推進課長","answer":"私からは、備蓄物資の配布に関しましてお答えいたします。それと、外に整備するのはかなり難しいのですけれども、今後、公共施設等も考えていかなければいけないと考えていますので、この辺も進めていきたいと考えています。","voiceIndex":196,"id":"exchange-079"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"例えば画像アップをするときに、なかなか画像がアップされないことがあるとお聞きいたしました。この点について、改善の余地があるのかどうか教えていただきたいと思います。国が自治体の公衆無線ＬＡＮについては利用登録を義務づけるというような方針を示しています。そういった中で、品川区としては今後どのように考えているのかお知らせください。","respondent":"仁平情報推進課長","answer":"そういう状況を見まして、区としましては、特に直接的な連携という話は今のところ考えておりませんけれども、そういう整備状況等見ながら、区として必要だと思われるようなところ、行政しかできないようなところを中心に、今、整備を考えているところです。","voiceIndex":199,"id":"exchange-080"},{"speaker":"南委員","kind":"質問・要望","question":"２つ質問したいと思います。１つは、１０６ページの人権啓発費。それで、今年度からというふうに思っていて、後で確認したいのですが、「男女共同参画センター運営費」というふうに項目がつけられて、「ＤＶ相談等」となっているのですけれども、そこのところで、先ほど申し上げた部分の問題以外も対応・対策しているという理解でいいのかどうか、ちょっとそれを教えていただきたいと思います。","respondent":"島袋人権啓発課長","answer":"平成２７年度におきましては、女性活躍講座ということで、きゅりあんの会議室を使いまして、人数は少ないのですけれども、そちらの支援の講座を行っているところです。","voiceIndex":203,"id":"exchange-081"},{"speaker":"南委員","kind":"質問・要望","question":"私が先ほど紹介した高齢者に関するもの以外に、ほかの分野での虐待等々についての対策あるいは支援策は、法制化されていない状況があるということでいいのですか。ちょっと、その辺をさっき伺ったので、教えていただきたいと思います。","respondent":"島袋人権啓発課長","answer":"今のご質問です。すみません。手間取りました。こちら子ども育成課と障害者福祉課・高齢者福祉課と連携会議を事務局として持っております。","voiceIndex":205,"id":"exchange-082"},{"speaker":"南委員","kind":"質問・要望","question":"事務局として持っているということは、法律があって対策がとられて、十分かは別ですけれども、あるという確認でいいのですかということを、ちょっと教えていただきたい。それで、その次にいきますけれども、ぜひそれは後で答弁してください。そういう点で、ぜひその点での品川区としてのアプローチを、どういうふうにしようとしているのかを、また一つ伺いたいと思います。","respondent":"島袋人権啓発課長","answer":"ほかの課との相談におきましては、やはり他部署との連携が重要だと考えています。庁舎内における、隣の声が聞こえてしまう、相談が十分にできないということに関しましては、やはりきちんと関係部署とも詰めていき、然るべき対応をしていきたいと考えているところです。","voiceIndex":207,"id":"exchange-083"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、そういう不用額というふうな形で残すのではなく、先ほど申し上げたような相談スペースの改修も含めて、あるいはいろいろなＤＶあるいは虐待等々がある中で、生活困窮者、貧困、そういう世帯に対する相談体制の充実も含めて、掲げられた予算をしっかりとフルに活用して、全ての人権が侵されることのないような対策をとっていただきたい、このことも強く求めたいと思っていますが。","respondent":"島袋人権啓発課長、伊崎地域活動課長","answer":"は執行率のほうからお答えいたします。執行率につきましては、一度、都の査定を受けますので、受けられるものは全て都のほうに査定を出します。その後、返ってくるものがございまして、査定のつくもの、つかないものがあります。そのほか、さまざま、子育て支援の団体とか地域の活動の団体とか、個別の団体につきましては、詳細なものはお話しできないのですけれども、本当に様々な団体がご登録いただいているところです。","voiceIndex":209,"id":"exchange-084"},{"speaker":"南委員","kind":"質問","question":"ちょっと時間がなくなってしまったので、主張だけしたいと思います。地域センターのほうですけれども、ある団体が集会所系団体として登録している。そして、いろいろな相談活動等々もしているけれども、不特定多数の人が来るので貸せないと言われたというのです。その理由は何なのかをちょっと簡単に教えてください。","respondent":"伊崎地域活動課長","answer":"団体として、団体の登録者の方を名簿でご登録いただいて、その方たちに貸すような仕組みとなっております。","voiceIndex":212,"id":"exchange-085"},{"speaker":"あくつ委員","kind":"質問","question":"１０５ページ、成人式経費、１１２ページ、文化スポーツ振興費、時間があれば税務関係と、１０９ページのシティプロモーション推進経費について伺います。本年１月１１日の成人式で、障害をお持ちの成人女性が幾つかの要因で成人式に出席できなかったことについて、本年３月の予算特別委員会総務費の款で質問させていただきました。来年の成人式の対象者は何人で、いつご案内状を発送するのか教えてください。","respondent":"久保田総務課長","answer":"来年の成人式ですけれども、現在、２,６１５人の方が対象です。内訳としましては、男性が１,３３９人、女性が１,２７６人です。案内状の発送は、１２月上旬から中旬のうちにやる予定です。","voiceIndex":215,"id":"exchange-086"},{"speaker":"あくつ委員","kind":"確認","question":"案内状の発送も間もなくということで、予算特別委員会の質疑の最後に総務部長からは、「一生に一度の大切な機会に今回のような形で対応してしまったことについて大変申し訳ないと考えています。確認しないわけにはまいりませんので伺わせていただきます。幾つか問題があったと思いますけれども、何が問題だったとお考えなのか、またそれに対してどのような改善策を講じられたのか、具体的に教えてください。","respondent":"久保田総務課長","answer":"平成２８年１月に行われた成人式の際での対応の不手際に関しまして、いろいろと意見交換等をさせていただいた中で、またあくつ委員からも予算特別委員会の中でご指摘いただいた点について、私どもが現在考えている改善策について、述べさせていただきたいと思います。１点目です。","voiceIndex":217,"id":"exchange-087"},{"speaker":"あくつ委員","kind":"提案","question":"本当に真摯なご検討をいただいている様子がよくわかりました。区立ではないのですが、例えば港特別支援学校等でご卒業された方はたくさんいらっしゃいますので、そういうご提案があったのですけれども、そのことについては何かご検討いただけましたでしょうか。","respondent":"久保田総務課長","answer":"特別支援学校のブース等につきましては、教育委員会のほうにも相談しまして、また、実際に品川特別支援学校等もありますので、これからそういった方、専門の方等の意見を聞きながら、設置の可否、またそういうことの対応についてご相談する予定です。","voiceIndex":219,"id":"exchange-088"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ちょっと難しい言葉で言うと、「双方の建設的対話による相互理解を通じて、必要かつ合理的な範囲で柔軟な対応がなされ、過重な負担にならない範囲で社会的障壁の除去を行うための変更・調整」、これが合理的配慮と伺っています。悲しい言葉ですけれども。個別のケースでは、今のようなご対応、今回の成人式が本当にそういうモデルケースになればいいと私は思っていますが、ご決意をお伺いしたいと思います。","respondent":"田村総務部長","answer":"今ご質問があったとおり、予算特別委員会の中で成人式の件をきっかけに、今回、障害者差別解消法ということで、先ほど総務課長が言ったように、さまざま考えられる手だてはとって対応しております。","voiceIndex":221,"id":"exchange-089"},{"speaker":"あくつ委員","kind":"質問","question":"続きまして１１２ページ、文化スポーツ振興費から文化プログラムについてお伺いします。２０２０年東京オリンピック文化プログラム、今日、ホームページを拝見しましたら、品川区のホームページのトップバナーに大きく、新しいカウントダウンの表示が出ておりました。は本当に、現地視察、まことにお疲れさまでございました。ここでどのようなことが報告されて話し合いをされたのか教えてください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"それから最後に、東京文化ビジョンを実際に行うに当たっては、東京都、国、地元自治体、企業、芸術系団体等がパートナーシップのもとでしっかりやっていきましょうというようなことが説明されたものです。","voiceIndex":223,"id":"exchange-090"},{"speaker":"あくつ委員","kind":"質問","question":"もし主体でないならば、誰が文化プログラムに取り組むのでしょうか。東京都や組織委員会の職員が、品川区でダンスを踊ったり芸術活動をしてくれるのでしょうか。そんなわけがないでしょう。２０２０年品川区で、オリンピック・パラリンピックが開催されて、日本国中、品川区中が盛り上がっているときに、私はそういうことを言う方がどういう行動をとっているか、これはしっかり見届けたいと考えています。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"リオでの文化プログラムの実施状況ですが、リオの大会組織委員会では、セレブラという文化プログラムを早くから企画はしてございました。","voiceIndex":225,"id":"exchange-091"},{"speaker":"あくつ委員","kind":"質問","question":"私も報告書を読ませていただきました。「早期の着手が必要だ」、これも共通の認識ですけれども、先ほど今後の見通しということで渡辺委員の質問にお答えしていただいたのですが、文化プログラムのスケジュールについて、見えるものがあれば教えてください。区民の参加できる仕組みづくり、これからなのかもしれませんが、どういうふうにやっていくのか教えていただければと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"報告書に書かせていただきましたコンセプトですが、現在、区長をトップといたしました、オリンピック・パラリンピックに関する推進本部が庁内で立ち上がってあります。そうした推進本部の中で基本的には検討し、決定して明確にしていきたいと考えています。","voiceIndex":227,"id":"exchange-092"},{"speaker":"あくつ委員","kind":"意見","question":"ぜひよろしくお願いします。最後に、例えばその中で区内の文化芸術団体、芸術家の状況をまず把握するということが必要だと思います。別に区内で全部やるということではないのですけれども、そういった一元的な情報収集は必要だと思うのですけれども、その点についてご意見をお聞かせください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"文化プログラムを推進するに当たりましては、そうした区内のいわゆる資産と言うべき芸術家ですとか、そういったことの把握も当然必要だと考えていますので、文化振興事業団等と連携しながら取り組んでまいります。","voiceIndex":229,"id":"exchange-093"},{"speaker":"本多委員","kind":"質問","question":"成果報告書１０５ページの国際友好都市交流事業について伺います。初めに、平成２７年度の成果をどのように捉えているのか教えてください。","respondent":"河内協働・国際担当課長","answer":"地域国際交流懇談会というものを催しまして、こちらは９カ国、１２名の方、大使、総領事を中心としてお集まりいただきまして、２０２０年の東京オリンピック・パラリンピックや今後の国際交流のあり方、また区の防災対策など。","voiceIndex":232,"id":"exchange-094"},{"speaker":"本多委員","kind":"質問","question":"例えばポートランド市にあるレッドソックスの傘下、シードッグスのホームグラウンドのハドロックフィールド、品川区の子どもたちが向こうに行くとスポーツ交流をやっているグラウンド、野球場ですけれども、そういった野球場の品川版を品川区につくるとか、誰もが交流を実感できるような工夫が何か必要だと思うのですけれども、その点についてはいかがお考えでしょうか。","respondent":"河内協働・国際担当課長","answer":"三都市交流につきましては、国際友好だよりや諸般のホームページ、また常設展なども展示室で開催しています。こういった交流の経緯につきまして歴史館への展示なども検討しています。","voiceIndex":234,"id":"exchange-095"},{"speaker":"本多委員","kind":"質問・要望","question":"幅広くいろいろな国と交流を進めていただきたいと思いますが、三都市交流について継続するということは、区民にメリットがなければいけないと思います。先日、不安がよぎったのですが、もしも、一方的に旅費などを出せなどという申し入れを先方にしたり、そんな声が先方に届いたら、友好にひびが入らないか、その点についてどうお考えでしょうか。","respondent":"河内協働・国際担当課長","answer":"いずれにいたしましても、適正な役割分担の中で国際儀礼を重んじながらしっかりと進めてまいりたいという考えです。","voiceIndex":236,"id":"exchange-096"},{"speaker":"本多委員","kind":"質問・要望","question":"青少年のホームステイですとかスポーツ交流ですとか、たくさんの取組みがありますので、区民のメリットを最大限活かせるように友好をしっかり結んでいっていただきたいと思います。親日指標の伸びというのがどうなっているのか、これは品川区や品川区関係者の国際交流の取組みが貢献していると私は思います。今ちょっと答弁は難しいかもしれませんが、現時点でのお考えをお聞かせください。","respondent":"河内協働・国際担当課長","answer":"そのような事実から、非常に親日というよりは親品川ですが、そういった情報収集には努めているところです。今後、そういった親日度のベンチマークにつきましては把握に努めてまいりたいと考えているところです。","voiceIndex":238,"id":"exchange-097"},{"speaker":"本多委員","kind":"意見","question":"そのジュネーヴ訪問は、私も区議会を代表して行ってまいりました。その桜の木は友好関係者が手植えをしましたが、天皇陛下もそれに携わったということで、その場所で品川寺のご住職から、ジュネーヴ関係者の皆様の前で、濱野区長と区議会代表者５人がその話を聞いて、これを後世にしっかり伝えてくださいと言われました。最後に一言お願いいたします。","respondent":"河内協働・国際担当課長","answer":"経費を最低限という旨、また国際友好につきまして、あらゆる努力をしながら、私ども品川区と世界各国と手を携えながら、区民福祉の向上に向けて努力してまいりたいと考えております。","voiceIndex":240,"id":"exchange-098"},{"speaker":"須貝委員","kind":"質問","question":"今、そういう話が、ジュネーヴの話がありました。でも実際、区長は前々から、外交と防衛は国でやることではないかと。市民と区民の交流ならわかります。その中で、こういうことをやはりやっていていいのでしょうか。儀礼的に区長が行って「ああ、どうも、おめでとうあります。２５周年記念です」と、それをやって何が価値があるのですか。私はそう思うのですが、いかがですか。","respondent":"河内協働・国際担当課長","answer":"そのために、様々な国と連携しながらお付き合いしていますが、今回の訪問に関して言えば、２０年ぶりの訪問ということもあります。１０年に１回のチャンスということでもあります。その間、子どもたちがホームステイという形で国と国のきずなをつないでまいりました。","voiceIndex":243,"id":"exchange-099"},{"speaker":"須貝委員","kind":"質問","question":"それはなぜですか。お互いに大変だから、お互い予算をかけてまでやるべきことではないのではないか。それしか交流はできないですか。それでなぜ国内が大変なのに、区内に大変な人がいっぱいいるのに、ますます高齢化が進むのに、お金をかけるべきところが私は違うと思うんです。やはり皆さんの税金であり、皆さんのために我々は働かなければいけないのです、お金をかけなければいけないのではないのですか。","respondent":"河内協働・国際担当課長","answer":"先ほどから申し上げましたとおり、先方との国際儀礼を失しない範囲で最小限あるいは最低限の日数など調整を重ねてまいりまして、効率的な事業の執行に努めてきたところです。その上で、国際交流と申しますのは、お互いの国と国とが理解し合うことです。","voiceIndex":245,"id":"exchange-100"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１０９ページの財政管理費と、あと１１０ページの企画調整費について伺います。そして、今年の８月には地方税源の充実強化ということで、「地域間の税収格差の是正は国の責任において地方交付税制度で行われるべきものであり、地方税の原則をゆがめ、地方分権に逆行する」と、「法人住民税の一部国税化を早期に見直すことを要望する」ということで主張されています。","respondent":"秋山財政課長","answer":"ですので、東京が一方的にやられているのだという主張ももちろんありますけれども、そうではなくて、地方とともに地方自治を盛り上げていくのだというところから主張していきたいと考えております。","voiceIndex":249,"id":"exchange-101"},{"speaker":"高橋（し）委員","kind":"確認","question":"１１０ページの企画調整費ですが、全部の款にわたる指定管理者のモニタリングについてお尋ねしたいので、こちらでお尋ねいたします。指定管理している施設の数と指定管理者、事業者の数を教えていただき、モニタリングをしているのですが、このモニタリングの項目というのでしょうか、各課共通でやられていますが、いつ頃どちらが、このモニタリングの仕組みをおつくりになったのかということを確認します。","respondent":"柏原企画調整課長","answer":"それからモニタリングの部分ですけれども、こちらにつきましては、この制度が始まりまして、その後、平成１８年にこの制度の運用について大きく検討したときがございまして、そのときにモニタリングという考え方を内部で検討いたしました。","voiceIndex":251,"id":"exchange-102"},{"speaker":"高橋（し）委員","kind":"質問","question":"企画部門のほうでやられたということで理解してよろしいのでしょうか。それで、今、品川区独自の部分があるとおっしゃったのですが、この１０年経った段階で、指定管理者の決定からモニタリングまで、特にこのモニタリングについてどこか見直しをしようかというようなお考えはいかがでしょうか。外部のチェックについてどのような形で、現行、取り入れていれば、その例をお話しいただければと思います。","respondent":"柏原企画調整課長","answer":"モニタリングの進め方といったところです。指定管理者に事業報告書をいただく中で、事業者がまず自分たちでのチェックをするというものがあります。それから、それが区に報告が上がりまして、区の中で、所管部門、それから企画部門が、両方の目で確認します。","voiceIndex":253,"id":"exchange-103"},{"speaker":"高橋（し）委員","kind":"意見","question":"１０年経ったというところで、様々な課題も出てきていると思います。それで、国のひな形があると思うのですが、品川区独自の部分をぜひ項目の中に入れて、今、指定管理の施設も１０３ということで大変多いのですけれども、指定管理の重要性に鑑みて、そのチェック機能の強化も進めていっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":255,"id":"exchange-104"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今委員会の中でモニタリング、いろいろ検討されたのですが、私は文教委員会でした。そういった中で、職員の配置とか処遇が、よい仕事をしていただく上でとても重要であるということで、職員の配置などもぜひシートに盛り込んでほしいという要求を出しましたところ、これは企画担当の所管なので、伝えてくださいますという話があったのですが、ぜひ検討していただきたいのですが、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"労働の部分に関しましては、先ほど申し上げました社会保険労務士のチェックをいただいているという部分がありますので、今後この形をどういうふうに、ルーチン化といいますか、していくかというのは、検討課題でありますけれども。","voiceIndex":257,"id":"exchange-105"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひトータル、広い目で見て検討していただきたいと思います。それで、実際的に質問をすると、一定線は出てくるのです。答えられる部分は既に載せていくべきであると考えていますので、ぜひそういったところで検討をお願いしたいのですが、もうちょっと具体的にお答えをいただきたいと思います。","respondent":"柏原企画調整課長","answer":"人員の話のところにつきましては、先ほど申しました社会保険労務士のチェックというのを、試行ですが、今、入れ始めましたので、そういった視点も見ながら、トータルでこのモニタリングの資料は考えたいと、先ほど申し上げたものです。","voiceIndex":259,"id":"exchange-106"},{"speaker":"飯沼委員","kind":"質問・要望","question":"社会保険労務士が入ってチェックを行うということですけれども、そういった意味では、公のところでやっている、全てやはり合法的であって当たり前ですし、そういうのをチェックされるべきであると思っているのですが、チェックが入るということですけれども、私は区の直営と同等の中身を知りたい。この要求にぜひ応えていただきたいのですが、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"ですので、そういったところも含みながら、トータルで考えさせていただきたいと申し上げたものです。","voiceIndex":261,"id":"exchange-107"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"公共施設等総合計画なのですけれども、これは平成２４年につくられた公共施設有効活用プランを発展的に引き継いでいくということですけれども、この計画を策定するに当たり、その前提をどう捉えるのかということで、そのものの中身も変わってくるのではないかと思っているのですけれども、その前提についてまずお伺いしたいと思います。１つは、この有効活用プランの前提が、こう書いてあるのです。","respondent":"柏原企画調整課長","answer":"施設の総合計画の前に当たる公共施設の有効活用プランの前提のお話であろうかと思います。有効活用プランを発表させていただいたのは、平成２４年７月ということでございまして、その以前、２年ほどかけて検討を行ってきたです。","voiceIndex":264,"id":"exchange-108"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これが、平成３１年のところでは１.４５まで持っていくということが総合戦略の中で目標として挙げられているわけですけれども、この５年間で１.４５まで出生率を上げていくために具体的にどういうことの取組みを行っていくのか、その具体的な中身をお聞かせいただきたいのと、あと平成２７年のときの出生率はもう既に上がっているのかということをお聞かせいただきたいと思います。","respondent":"柏原企画調整課長","answer":"それからアンケートの目標のところで、３８.１％との数字をお話しいただきましたけれども、これは世論調査で複数回答のうち選んでいただいた中で、このパーセンテージですので、そのほかにもいろいろな項目がある中で選んでいただいたということで。","voiceIndex":266,"id":"exchange-109"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは５年間の１.４５というのが目標ですから、最終的には２を超える目標をぜひ持っていただきたいと思いますし、これは自治体だけではなく、自公政権ですけれども、国とあわせて取り組んでいくということがとても大事だと思います。この姿勢こそぜひ改めていただきたいというのが１つです。そういうところでは、区としてこの公共施設の役割をどう捉えているのかということを改めてお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"その中には、ここまでやらなくてはいけない、それから優先順位であったり、そういったものをいろいろ精査しながら事業を進めているといったものですので、全ての事業においてそういった形で進めさせていただいているというところは、お話し申し上げたいと思います。","voiceIndex":268,"id":"exchange-110"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区民には切実なニーズがたくさんありますので、ぜひそういうニーズに応えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":270,"id":"exchange-111"},{"speaker":"伊藤委員","kind":"質問","question":"私は、成果報告書１０９ページ、シティプロモーション推進経費、それから１１０ページの町会ホームページ運営支援等について質問します。だから、結果として非常に縮小されてしまって、町会のいい活動がなかなかＰＲできないという意見が出ているし、まして動画など上げられるほどの容量でもないので、これは少しアップしていただければすぐに問題が解決すると思うのですが、いかがでしょうかという質問です。","respondent":"伊崎地域活動課長","answer":"そちらは、区の支援は２２の町会にしていますが、こちらの支援につきまして、明治大学との共同研究という形で進めております関係で、大もとが明治大学のサーバーの容量に規定されるということになっておりますので、なかなか容量のアップということは、現状では難しいところです。","voiceIndex":272,"id":"exchange-112"},{"speaker":"伊藤委員","kind":"質問","question":"それはそれですばらしいことだと思うのです。しながわ」はどうなのかという思いがあるのです。例えば、くまモンの成功例、それから、ひこにゃんとか、全国のキャラクターがいろいろあるじゃないですか。それで、結果としてそれが品川区を全国に発信することになるわけだから、そういうふうにシティプロモーションも、ある意味ステップアップしていったほうがいいと思うのですが、いかがでしょうか。","respondent":"中島企画部副参事","answer":"しながわ」のロゴマークのパネルを持っていろいろなところで活用していただくとか、そういうところも検討してまいりたいと考えています。","voiceIndex":276,"id":"exchange-113"},{"speaker":"伊藤委員","kind":"提案","question":"「わ！しながわ」自体を否定するものではないのです。だから、「わ！だから、「わ！しながわ」はすばらしいしやってほしい。だけれども、私たちの思いとしては、さらにそれを進めていくためには、観光振興協議会をつくっていただいたわけだから、その戦略としてやっていってみてはいかがですかと提案していますので、改めて答弁をお願いいたします。","respondent":"中山企画部長","answer":"既にあるような区の中でのキャラクターもあります。こういうものとのコラボレーションであるとか、そういうものを少し幅広く、関係所管との連携もとりながら展開を考えていきたいと思っています。","voiceIndex":278,"id":"exchange-114"},{"speaker":"伊藤委員","kind":"質問・要望","question":"結構、シティプロモーションの勉強をしていくと、話が深いのです。なので、せっかく観光振興協議会が今度できて、その中で戦略として品川区が一つの方向性を持って、そこに品川区の行政の力と民間の方の力が加わっていけば、それこそ新しいものができてくる可能性があると思われるので、ぜひ進めていっていただきたいと思うのですが、一言最後に答弁をお願いいたします。","respondent":"中山企画部長","answer":"当然ながら、区の中で考えていくこと、それから地域の部分、それから今ご提案もあったような民間の力と、様々な力を活用しながら発展的展開を心がけていきたいと考えております。","voiceIndex":280,"id":"exchange-115"},{"speaker":"塚本委員","kind":"質問","question":"初めに情報システム運営費のところなのですけれども、この中で、ネットワーク・セキュリティ経費というのがございまして、決算額は２億３,５４５万７,６０２円となっていますけれども、これが今年度の当初予算、現予算等の執行率で見ると６３.４％ということで、当初よりはかなり低い決算額となっておりますけれども、この減となった理由を最初にお伺いしたいと思います。","respondent":"仁平情報推進課長","answer":"最終的な３月補正の分が、これは繰越明許ということになってしまいましたので、全体の予算と合算すると、かなり執行率、決算の額が小さくなっているというのが実態です。","voiceIndex":283,"id":"exchange-116"},{"speaker":"塚本委員","kind":"質問","question":"もうちょっと詳しく聞くと、繰越明許になったということは、そういうこともあったのかもしれませんけれども、何かシステムを合理化したみたいな作業ですかね、そういったところは何かございましたでしょうか。","respondent":"仁平情報推進課長","answer":"当初に予定しておりました、この事業関係は全て執行しておりまして、それ以外の補正予算で、昨年ですか、６月に、日本年金機構の情報流出事件がありましたので、それの対策で補正を組みまして、インターネット環境の接続の安全性を強化したというのが結果になっております。","voiceIndex":285,"id":"exchange-117"},{"speaker":"塚本委員","kind":"質問","question":"何を聞きたいかというと、実は、いわゆるシステムの、要するに共同化というのですか、自治体間で共同化して、例えばそれで財源とか人材とかというもの、システム経費に今までかけていたものを合理化して、そういったところから新たに捻出できた財源や人材を、より地域の課題に充てていくみたいな考え方が、今、政府のほうでもされていて、自治体クラウドというような言い方をして。","respondent":"秋山財政課長、仁平情報推進課長","answer":"平成２７年度当初の予算につけたものは全て使っておりまして、年度末近くになりまして、国から、ネットワーク・セキュリティに関して補助がつくということで、予算がつきまして、補正予算でご議決いただきましたが。自治体クラウドへの考え方というご質問ですけれども、国の考えている自治体クラウドは、各自治体間で共同して、例えばデータセンターを共同利用すれば、確かに運用上の効率性が上がるのですけれども、国のモデルが示しているものは。","voiceIndex":287,"id":"exchange-118"},{"speaker":"塚本委員","kind":"質問・要望","question":"今、自治体クラウドについては、ちょっと大規模な都市では、品川区にはあまり向かないというお話でしたけれども、それはそれとして、やはり２３区で１つのというのは何かできないのかと非常に思うのです。そういった区内におけるシステムの合理化、共同化ということについても、何か進められることはないのか、お考えをお聞きしたいと思います。","respondent":"仁平情報推進課長","answer":"それと２点目の、部のほう、品川区の組織の中としての共同利用といいますか、今現在、個別に過去、いろいろとサーバーを分散して管理しておりましたけれども、これの効率的運用ということで、現在は我々のほうが管理しておりますサーバー室で、仮想的な処理ということで。","voiceIndex":290,"id":"exchange-119"},{"speaker":"塚本委員","kind":"意見","question":"品川区としても庁内のシステムのそういった努力をされているということで、こういったことを一つ、一定の目標や計画を立ててやっていただけるようなこともすれば、かなり大きな成果が上がるのではないかという思いもありますので、どうぞこれからもよろしくお願いしたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長、河内協働・国際担当課長","answer":"区との関係ですが、あくまでも大会にかかわる大会ボランティアと都市ボランティアは、東京都も自信を持って８万人と１万人は組織できると言っておりますので、そういったところはお任せするとして。こちらにつきましては、都と区の連携事業といたしまして、他区に先行いたしまして、既に私どもの区のほうで、この講義を開始しているところであります。","voiceIndex":292,"id":"exchange-120"},{"speaker":"塚本委員","kind":"提案","question":"この報告書にも、視察を終えての一つの提案というところで、このボランティアをターゲットとした民泊・ホームステイのシステム構築といったものを検討しないといけないのではないかということを書かれているのです。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"今後の進め方ですが、先ほども申し上げましたとおり、区長をトップとした推進本部がありますので、そういったところで検討してまいりたいと考えています。","voiceIndex":295,"id":"exchange-121"},{"speaker":"塚本委員","kind":"意見","question":"ぜひ、ボランティアにかかわらず、品川区を訪れる外国人、東京オリンピックに向けてのということでの外国人のおもてなしといった部分で、本当に来た方がまた日本に来たくなるというような形で準備をお願いしたいと思います。都や大会組織委員会に申し入れるというようなことで提言されておりますけれども、これの見通しみたいなものを何か語れるところがあれば、最後にお願いいたします。","respondent":"柏原企画調整課長","answer":"シェアサイクルの部分です。近隣区でもいろいろな動きが出てありますので、そういったところの動きを見ながら、品川区としても取組みについて検討していきたいと思ってあります。","voiceIndex":297,"id":"exchange-122"},{"speaker":"大倉委員","kind":"質問・要望","question":"維持管理費ですが、議会棟前の３階の、先ほどは噴水という話でしたが、広場について、施設としての位置づけというのはどういうふうになっているのか教えていただきたいと思います。防災のほうは、災害時のドローンについて伺いたいと思います。そこで、災害時のドローンについてですが、災害時は飛行については改正航空法でも、規制区域内においても飛行が可能であるということを伺っています。","respondent":"立川経理課長、古巻防災課長","answer":"花壇が設置してあります。庁舎前の植え込みの管理、補修委託ということで、大体５０万円ぐらいの経費をかけているところです。ただ、さまざま法的な規制も、整理はされてきておりますけれども、２３区での飛行についてはまだ制限がある部分もありますし、災害時はまた別の扱いにはなってこようかとは思いますけれども、そのあたり、情報を今、収集していますので。","voiceIndex":300,"id":"exchange-123"},{"speaker":"大倉委員","kind":"質問・要望","question":"プラッツァで玄関だということで、ちょっと内訳で５０万円ということだったのですけれど、これは年間５０万円なのか、月５０万円なのか、ちょっとわからなかったので教えていただきたいのと、あと玄関ということで、人が品川区役所に入ってくる道なのかなというところで言うと、下神明の駅からだと、そのまま横断歩道を渡って、そちらから入って、大井町からだと２階のほうから入ってくるというところで。","respondent":"古巻防災課長、立川経理課長","answer":"その辺を含めまして、まだ研究が緒についたばかりというようなところもあります。その辺、改めて認識を深めまして、今後、研究を深めてまいりたいと考えております。いわゆる車の乗り入れですけれども、通常は乗り入れられないということで、工事などといったときに、経理課のほうにお話しいただければ車が入れる扱いにはしています。","voiceIndex":303,"id":"exchange-124"},{"speaker":"大倉委員","kind":"質問・要望","question":"通常は乗り入れができないということで、経理課の許可があればということだったので、許可をもらって入れるのだなというところで、例えばあそこは玄関というところで、ああいったところが、いろいろな方々から見てもらう区の正面玄関だ、顔だというところで言うと、にぎわいの創出とか、身近な行政や区役所というところにどうやって近づけていくかというところを考えたときに、あそこで例えばカフェみたいな。","respondent":"古巻防災課長、立川経理課長","answer":"職員が直接できることでもないかと思います。そういった民間の団体等も含めまして、情報収集をさらに続けて、安全性の確保を含めましてさらに研究・検討を進めていきたいと考えています。区役所は様々な方がおいでになりまして、困ってご相談に来られる方も多数いらっしゃいますので、常に区役所前が屋台だとかだったりしたらどうなのかなというようなところもありますので。","voiceIndex":306,"id":"exchange-125"},{"speaker":"大倉委員","kind":"質問・要望","question":"時間がなくなってしまったのですが、最後にペットの同行避難について少しだけ伺いたいと思います。同行避難の施設は９施設がありますが、同伴避難の可能な施設があるのかどうか、また同行避難が可能なところでの対応、マニュアルや連絡協議会での話し合いの状況、また配備の状況、例えばペットの備蓄についての状況を教えてください。","respondent":"古巻防災課長","answer":"避難所におきますペットの同行避難等の関連ですけれども、品川区は、さきの一般質問においてご質問が出ましてご答弁させていただきました、ペットに関する記載のある避難所９カ所に関しましてですけれども、こちらは基本的には。","voiceIndex":309,"id":"exchange-126"},{"speaker":"松澤委員","kind":"質問","question":"２款総務費１項総務管理費２目広報広聴費、１０９ページ、シティプロモーション経費に関連して、目黒のさんま祭りについてお伺いしたいと思います。そこでお伺いしますけれども、品川区のシティプロモーションの材料となると思われますけれども、このさんま祭りをどのようにシティプロモーションとして取り扱っていくのか、取り合っていくのかについてお聞きしたいと思います。","respondent":"中元広報広聴課長","answer":"そちらのほうの補助ということは難しいのですが、広報広聴課といたしましては、ケーブルテレビの番組『サヘル・ローズの天晴！","voiceIndex":312,"id":"exchange-127"},{"speaker":"松澤委員","kind":"質問","question":"商店街事業費」を活用しているんです。それと、大根を提供している那須塩原市、これは民間の農協か何か、そういうのが参加していたと思うのですけれども、今回はシティプロモーション課というのですか、課長と係長が訪れて、来年からは市として全面的に協力していきたいのだというようなお話がございました。このようなところから費用の援助できないのかと思っているのですが、その点はいかがでしょうか。","respondent":"柏原企画調整課長","answer":"全国連携プロジェクトを進める中で、品川区としてもそういったところは積極的にかかわっていきたいと思っているところです。","voiceIndex":314,"id":"exchange-128"},{"speaker":"松澤委員","kind":"質問・要望","question":"今、企画調整課からいろいろお話を伺いました。次に２点目の、地区防災訓練についてお伺いしたいのですが、昨年は何か３地区ができなかったと聞いているのですけれども、当然、雨かなという気もするのですが、これについて詳しくお知らせいただきたいと思います。","respondent":"古巻防災課長","answer":"昨年度の地区総合防災訓練の実績ですけれども、平成２７年度、１０地区で開催しています。品川第一地区、大崎第一地区については雨天のために中止です。それから、大井第一地区につきましては未実施ということで、１２月の区内一斉防災訓練で実施しているというような状況です。","voiceIndex":316,"id":"exchange-129"},{"speaker":"松澤委員","kind":"質問","question":"今の大井第一地区の話ですけれども、地区の防災訓練に参加できなかった。これは、話を聞くと、区内一斉防災訓練の日に合わせてということなので、やることはやったということなのでしょうか。もしやったとしたならば、規模にかかわらず、ここにやった、日にちを変えてやったというふうに書くべきだと思うのですが、その辺は何でこれを書いていないのか、その辺をお聞きしたいと思います。","respondent":"古巻防災課長","answer":"書かなかった理由ですけれども、総合防災訓練という位置づけでしている訓練の日程的な部分と、あと区内一斉防災訓練の日程でやった訓練ということで、日程で分けてやっておりますので、それは書き方の問題はあるのかと思いますけれども、実施は、訓練はしているというところで。","voiceIndex":318,"id":"exchange-130"},{"speaker":"松澤委員","kind":"質問","question":"今年の４月には熊本地震が発生したということで、私も６月の議会で質問したのですけれども、何というのですか、区民の防災意識の高揚を図るべきだというふうに質問したのですけれども、今年度の地域防災訓練の中で、これは地区の総合防災訓練の目的というか、それの中で行う、何というのですか、種目というのですか、それについてどのように区としては把握しているのか。","respondent":"古巻防災課長","answer":"特に何をというような中身については、区側で指定しているわけではございませんけれども、基本的には初期消火でありますとか応急救護、それから救出救護、それから場所によって地震体験車や物資の配布など。","voiceIndex":320,"id":"exchange-131"},{"speaker":"松澤委員","kind":"質問・要望","question":"実は、地区の防災訓練の中で、この防災訓練の内容を変えたところがあるのです。ところが、その内容というのは、今まで各町会が放水訓練をしていたのを半分にしてしまった。訓練しなくて、いざというときにどうしたらいいだろう。とっさに動けるというのは訓練しているからなのです。その点について一言お答えをいただきたいと思います。","respondent":"古巻防災課長","answer":"総合防災訓練につきましては、主体は地区の防災区民組織になりますので、主体的にやはり訓練をしていただくということが大事なことでもありますので、自助・共助という中で、区としてもかかわりを持ちながら、でこぼこはありますけれども。","voiceIndex":322,"id":"exchange-132"},{"speaker":"のだて委員","kind":"質問","question":"私からは、１１９ページの災害時要援護者支援経費、１２０ページの避難所管理費にかかわって、要援護者への支援と避難所運営について伺います。４月の熊本地震を受けて、防災対策について様々な問題が浮き彫りになりました。いろいろあると思いますが、熊本地震の経験を踏まえて、現在、区が考えている、防災に対する重要な課題は何か伺います。","respondent":"古巻防災課長","answer":"熊本地震を踏まえましての区としての防災の考え方ですけれども、熊本地震以降の一般質問等でもお答えしていますけれども、個別にいろいろ課題が浮き彫りになってきているということは認識しておりまして。","voiceIndex":325,"id":"exchange-133"},{"speaker":"のだて委員","kind":"質問","question":"私は今、区が考える重要な課題をお聞きしましたので、被害想定に沿ってやっていくということですけれども、そこでもやはり重要な課題、今、区が捉えていることをお聞きしたので、ご答弁願います。","respondent":"古巻防災課長","answer":"ですから、一つ一つ、それぞれ重要な課題であるというふうに捉えておりますので。そういう意味で言いますと、きちんと今まで考えてきた計画を充実させていくということが一番重要なことだと考えております。","voiceIndex":327,"id":"exchange-134"},{"speaker":"のだて委員","kind":"質問・要望","question":"それで、私は、まず重要なのは、しっかり支援を行き届かせるためにも、被害状況の把握とともに、誰がどれだけ何を求めているのか、これをつかまなければならないと思います。人口の差などあるとは思いますけれども、一概には当てはめることはできませんが、こういった一人一人や地域ごとへの被災状況や要望を把握すべきだと思いますが、いかがでしょうか。","respondent":"古巻防災課長","answer":"重要な課題ということで、状況をつかむということで、重要なことだというようなお話に関しましてですけれども、確かに状況をつかんで対応していくということは重要なことだと思います。","voiceIndex":329,"id":"exchange-135"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはりしっかり状況把握していくことが対策に当たっても始まりだと思いますので、しっかり把握していっていただきたいと思いますけれども、指定避難所はもちろんですけれども、自主避難所や車中泊といったところでも、同じ支援をしていっていただきたいと思いますが、そういった計画あるいは検討をどうしていくのか伺いたいと思います。","respondent":"古巻防災課長","answer":"ですから、そういったところの情報把握でありますとか、そこへの支援ということも十分考えていかなければいけない、それは課題であると認識しております。","voiceIndex":331,"id":"exchange-136"},{"speaker":"のだて委員","kind":"質問","question":"しっかりと把握して、今回の熊本地震でも、車中泊でやはり震災関連死された方もいらっしゃいますので、そういったところにでも支援が行き届くように、状況把握を区でも検討をお願いしたいと思います。そして、要援護者への支援はやはり災害時ほど必要になってくると思います。自宅で避難できない場合、直ちに福祉避難所に行くことはできないのでしょうか。できない理由は何か伺います。","respondent":"古巻防災課長","answer":"ただ、最初の発災直後に関しましては、なかなかマンパワーを十分に揃えることが難しい面があるかと思います。そういった中で、どこまで支援、準備ができるか、救助体制がとれるかといったことも含めまして、十分に検討していきたいと考えているところです。","voiceIndex":333,"id":"exchange-137"},{"speaker":"のだて委員","kind":"質問","question":"早目の避難所立ち上げを検討していくということですけれども、それは福祉避難所を立ち上げていくということでしょうか。私は、そのための人の確保と、やはり計画の作成、そして訓練が必要だと思いますが、いかがでしょうか。","respondent":"古巻防災課長","answer":"避難所の開設ですけれども、これは、なるべく早くということは必要なことであるとは認識しております。それは福祉避難所の話、二次避難所も同様ではありますけれども、福祉避難所についてはそのような形で考えております。","voiceIndex":335,"id":"exchange-138"},{"speaker":"のだて委員","kind":"質問","question":"福祉避難所については早期の立ち上げをやっていくということで、検討していくということで、すみません、ちょっと聞き取りできなかったのですけれど、それでいいのか伺いたいと思います。あわせて、障害者がいる世帯の耐震化も重要です。障害者がいる世帯の耐震化を進めていくべきではないかと思いますが、いかがでしょうか。障害者の方が気軽に相談などできる拠点を設けてはいかがでしょうか。","respondent":"古巻防災課長","answer":"障害者の相談センターといったようなところですけれども、具体的には今、計画の中では触れておりませんけれども、場合によっては、そういったところも今後、今までの事例を考えながら検討を進めてまいりたいと考えております。","voiceIndex":337,"id":"exchange-139"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、福祉避難所をすぐ開設して、たらい回しというか、転々とすることがないようにやっていっていただきたいと思います。区も、建設委員会では必要性を認めて、二次避難所、福祉避難所への誘導をしていくとしていますが、これは誘導のみなのか、避難所生活の中で出てきた問題についても支援する体制づくりはできているのか、伺います。","respondent":"古巻防災課長","answer":"個別計画のお話ですけれども、その中で避難誘導ということで、避難所までの様々な支援をということで、個別計画に盛り込んでいくことですけれども、また全体計画の中で、避難後のそういった生活の支援を含めまして考えているところです。","voiceIndex":339,"id":"exchange-140"},{"speaker":"若林委員","kind":"質問・要望","question":"地域振興経費ですが、町会・自治会になる要件は何かを教えていただきたいと思います。なった場合に行わなければならないことは何かを教えていただきたいと思います。あわせて、なったメリットについても教えていただきたいと思います。もう一つ関連して、区政協力委員と町会の関係はどういうものなのか、これもあわせて教えていただきたいと思います。","respondent":"伊崎地域活動課長","answer":"それと、１エリアに１団体というのが要件となっております。それから自治会につきましては、ある一定の集合住宅をエリアとしまして、そこの集合住宅に居住する方が、任意によって、誰でも入ることができる団体ということで、エリアが町会と異なるというところがあります。","voiceIndex":342,"id":"exchange-141"},{"speaker":"若林委員","kind":"質問","question":"「品川区町会および自治会の活動活性化の推進に関する条例」というのが今年の４月に施行されまして、この中で、町会加入と活動への参加を促進する仕組みをつくるということが条例の中でも条文に謳われました。もう一点、マンション住民の方たちが町会に加入する仕組みは今あるのでしょうか。その仕組みづくりは行われているのでしょうか、お聞きいたします。","respondent":"伊崎地域活動課長","answer":"加入促進の仕組みですけれども、従前から加入促進につきましては、各町会・自治会が努力してきていただいており、区としましても、リーフレットの作成など支援してまいりました。","voiceIndex":344,"id":"exchange-142"},{"speaker":"若林委員","kind":"質問・要望","question":"そうすると、今は、条例も含めて、マンションの方たちに町会に入っていただきたいという趣旨で、地域活動課も動かれていると思うのですが、先ほど要件等々、区政協力委員という質問もしましたが、マンション自体が町会・自治会になる、区政協力委員になるという反対のベクトルの考え方はないでしょうか。","respondent":"伊崎地域活動課長","answer":"それで、区政協力委員としてのお願い、役割がありますので、そういったことをきちっとやっていただくということが条件とはなってまいります。","voiceIndex":346,"id":"exchange-143"},{"speaker":"若林委員","kind":"意見","question":"ぜひ、いわゆる地元の今ある町会のエリアがある、これはあくまでも、いわゆる任意ですよね。品川区がここからここと決めているわけではなくて、町会の元々ある地縁団体として、たまたま規則をつくって、今、２０３町会・自治会があるということなので、そういう意味ではあまり拘束力はないのかなと。そこで、品川区の文化について特徴的なものは何かをお尋ねしたいと思います。","respondent":"鈴木文化観光課長","answer":"あとはいろいろな、茶道であったり華道、それから文芸関係の区民の自主活動もかなり活発というあたりが特徴だと考えております。","voiceIndex":348,"id":"exchange-144"},{"speaker":"若林委員","kind":"提案","question":"今回、芸術祭「まつりだわ！！ここで、品川区の区内の祭りが今どういう状況になっているかというのをちょっと見たら、荏原、品川、貴船神社等が６月の上旬にある。居木神社等が８月にある。ぜひ一つご提案というのでしょうか、７月・８月・９月のオリンピック・パラリンピックの期間中に、祭りの主体というのは、当然主体がありますけれども、神社等がありますが、やはり現場で動かしているのは町会です。","respondent":"鈴木文化観光課長","answer":"区といたしましても、オリンピック・パラリンピックの部門や文化部門だけではなくて、関連団体とも連携しまして、そういうようなしっかりとした取組みができないかということで、検討を進めているところです。","voiceIndex":350,"id":"exchange-145"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今度、その中で活用ということもお話がありましたけれども、研修をこれからやっていくのでしょうが、職員の方たちがその資料を見てすぐにどうやって活かしていけるのか、その辺がちょっと気になったので確認させていただきたい。この新会計制度が平成３０年４月からスタートしますけれども、実質的に資料が出てくるのは、そうすると、平成３１年の決算からになるのかどうか、それの確認。","respondent":"福島会計管理者","answer":"そのときの決算資料につきましても今、どういう形にするかさまざま検討していますが、やはり肝となるのは、行政評価をいかに自分たちで行っていくのか、それに基づいていかに変革していくのか、またそれとともに区民の皆様にどう説明責任を果たしていくか。","voiceIndex":353,"id":"exchange-146"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"時期等、わかりました。こういうものを、議会もそうですし、職員の方々がどこまで検討して、すっと理解できるか、それを非常に感じますので、よく職員と同時に、逆に言うと議会側も研修していただきたいという要望もちょっとありますので、その辺も改めて、これは議会の中の話かもしれませんけれども、その辺も対応をよろしくお願いしたいということで、これはその要望で終わります。","respondent":"河内協働・国際担当課長、竹田保育課長","answer":"採択される団体数と総額についてです。団体数につきましては、昨今、６件から８件の間で推移いたしております。これは最終的な採択という数です。総額の金額につきましては、概ね２００万円前後というような推移です。そういったお子さんの保育や教育に対して、保育者への対応について専門的な助言を受けて、児童の健全な発達を図ることを目的としまして、平成２７年度は区立保育園・区立幼稚園のほうに専門家の巡回をしたところです。","voiceIndex":355,"id":"exchange-147"},{"speaker":"鈴木（真）委員","kind":"提案","question":"それで、せっかく始まったばかりの状況なのですが、今お話があった課題として専門家の確保がなかなか難しいということはお聞きしましたけれど、やはりもう少し、幼稚園も数が多い中でご要望も出ておりますので、どなたか適任の方を探していただいて、回数を増やしていただけるようにご検討いただきたいと思うので、もう一度その辺はお答えいただきたいと思います。","respondent":"河内協働・国際担当課長、竹田保育課長","answer":"こういった事情に照らし合わせまして、効果的に区民の利益につながりますように、団体のニーズ、それから他区の動向も踏まえまして検討してまいりたいと考えております。専門家が少ない分野ですが、区としてもあらゆるチャンネルを使って人材の確保に努めてまいりたいと思います。","voiceIndex":358,"id":"exchange-148"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"幼稚園のほうよろしくお願いします。というのは、やはり調べていった中で、基本構想の３つの理念の中に、区民と区との協働で私たちのまち「しながわ」をつくる。この観点からすると、やはりこの協働事業、もちろん町会との協働もありますけれど、こういうＮＰＯ団体等の活動をなるべく支援できるような体制をとっていただきたいと思います。どうぞよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":361,"id":"exchange-149"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1422#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":124224,"voices":362}},{"id":"h28-20161011-4","meetingId":"h28-c-settlement","date":"2016年10月11日","dateIso":"2016-10-11","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時４９分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を190件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"おはようあります。私からは、成果報告書、１２５ページ、地域福祉計画推進費に関連して、おたがいさま運動について質問をします。初めに、おたがいさま運動の趣旨といいますか、活動状況をお知らせいただきたいと思います。","respondent":"大串福祉計画課長","answer":"こちらにつきましては、すべての人にやさしいまちづくり推進計画、あるいは品川区の地域福祉計画、こういったものに位置づけられておりまして、ユニバーサルデザインの普及啓発、また、こういったおたがいさま運動ということで。","voiceIndex":4,"id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"意見","question":"これ、おたがいさま運動は、年間を通してやっている運動だと思いますけれども、今月がおたがいさま運動の推進月間ということで、いろいろと活動されていると思うのですけれども、具体的にどのような活動をしているのかお知らせください。","respondent":"大串福祉計画課長","answer":"昨年ですと、職員の研修も１０月に行っております。ちなみに、今年は日程の関係で１１月に行うことになっておりますけれども、この１０月の推進月間を中心にして普及啓発の活動、さまざまな取り組みを行っているです。","voiceIndex":6,"id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問","question":"まさにこれがおたがいさま運動だと思っています。そこで、いろいろと区政協力委員の方、町会長とかにもお知らせはしているはずだと思うのですけれども、改めて町会とかにこういった啓発活動を、年間を通して運動していますという啓発活動は行っているのでしょうか。お知らせください。","respondent":"大串福祉計画課長","answer":"昨年から教育委員会と連携をいたしまして、区内の小学校にも出前講座という形で伺わせていただいて、この運動、おたがいさま運動の普及啓発を広く進めているところです。","voiceIndex":8,"id":"exchange-003","title":"町会・自治会支援"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"行方不明高齢者早期発見アイテムの配布ですが、見守りアイテムを９月１日から配布していると思うのですけれども、この配布の種類、３種類あると思うのですけれども、これはご家族が希望した種類のアイテムが配付されるものだと思うのですけれども、これ、いろいろご家族の方によって選ぶ種類が違うと思うのですけれども、大体どれぐらいの種類の配布数か、それを教えていただきたいのと、それとあと。","respondent":"永尾高齢者福祉課長","answer":"次のケアパスの関係ですけれども、アンケートを実施いたしまして、その回収状況になりますけれども、４０.５％になっております。現在、そのアンケートを分析しておりまして、内容をまとめたところで、またご報告をしたいというふうに考えております。","voiceIndex":12,"id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"よろしくお願いします。昨年の予算特別委員会でも質問させていただきましたけれども、年間の区内全体の相談件数と、心身障害者福祉会館に来館された高次脳機能障害者の相談の件数と人数を教えていただきたいのと、それと、高次脳機能障害専門相談員の予算が３５５万５,０００円、決算でも３５５万５,０００円です。この変動がないということの理由も教えていただきたいと思います。よろしくお願いします。","respondent":"中山障害者福祉課長","answer":"心身障害者福祉会館における相談件数と、特に高次脳機能障害に対する支援のお尋ねについてお答えいたします。会館のほうの相談支援センターの平成２７年度の年間の延べ相談件数ですが、６,１８１件あります。","voiceIndex":14,"id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"本当に繰り返しになりますけれども、この高次脳機能障害というのは非常に医療関係者でも、本当に見た目ではわからないことがあると思うのです。その判断基準が難しい中で、この予備軍がどれだけいるのかというのがわからない状態、この予備軍には当然お子さんを含めていると思うのですけれども、区としてはどの程度と把握しているのかお知らせいただきたいと思います。","respondent":"中山障害者福祉課長","answer":"ただ、やはりそういった中で、きちんと高次脳機能障害の方がこちらの相談につながるためには、医療機関との連携が重要になってくると思いますので、区内の医療機関をはじめ、この地域ですと、荏原病院が基幹の相談の病院ということになっておりますので。","voiceIndex":16,"id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"意見","question":"今、課長のご説明があったように、荏原病院との連携は、今後もやっていくと思うのですけれども、どういった場合に荏原病院へ相談に行ってくださいとか、その基準をご家族に対してどのようにお伝えしているのかお知らせをお願いいたします。","respondent":"中山障害者福祉課長","answer":"ですので、荏原病院に限らず、いろいろな医療機関で、特に脳血管系を扱う診療部門を持っている病院につきましては、パンフレット等をお渡しすることで、区内の連携、それから病院との連携というふうにしていきたいと考えています。","voiceIndex":18,"id":"exchange-007"},{"speaker":"つる委員","kind":"質問・要望","question":"１２４ページ、民生費、それから１３８ページ、児童センター運営費について伺っていきたいと思います。大きい括りで申しわけありませんが、まず、ダブルケアについて改めて伺いたいと思います。そうした意味で、こうした国の動向を踏まえた区の取り組みを先駆的に行ってもらいたいという思いで、幾つか改めて確認させていただきたいと思います。先日の質問でもさせていただきました。","respondent":"永尾高齢者福祉課長","answer":"区といたしましても、高齢者の部門でいけば、介護保険の情報を発信するとき、また、地域の方へのケアの話をするときなどの機会を捉え、その課題について周知をするとともに、区としても皆様の声を聞いて。","voiceIndex":22,"id":"exchange-008"},{"speaker":"つる委員","kind":"質問・要望","question":"いろいろな発信方法があるかと思います。あわせて人材育成、相談体制の整備についても具体的な取り組みをしていくということで、先日もご答弁いただきましたが、今後どのように具体的にその体制づくりを図っていくか、検討されているか、このあたりも教えてください。","respondent":"永尾高齢者福祉課長","answer":"ただ、どちらの部署に相談に行っても、一定程度のお答えができるような案内ができるよう、部はまたぎますけれども、担当者同士で今後検討会議等を開きながら、ワンストップまではいかないですけれども。","voiceIndex":24,"id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"次に行きたいと思います。１回目が３０名の定員に対して２２名、今回が同じく３０名の定員に対して２３名ということで利用されているというふうに伺っております。そうした中で、まず、この対象者ということで、区内在住か在勤で小学生以下のお子さんがいる母親となっておりますけれども、この参加されている方のお子さんの年齢は把握されていますでしょうか。","respondent":"高山子ども育成課長","answer":"今、ママのリフレッシュタイムのご質問をいただきました。参加される方々のお子さんの年齢については、特に集約を図っていないところではありますが、参加するお母様につきましては、そのきっかけ等につきまして、アンケート等において情報収集しています。","voiceIndex":26,"id":"exchange-010"},{"speaker":"つる委員","kind":"確認","question":"それをやることでリフレッシュのところへ行って、１時間半のリフレッシュタイムで、その労力に対するリフレッシュの内容を考えた時に、どうだろうなと。それで毎週金曜日の全７回。そうしたところを含めて、この辺の改善の余地、議事録を確認すると、そうしたお声を聞いていきながらという部分が、たしか始める前には課長から答弁があったようですけれども、改善の余地についてお考えをお聞かせください。","respondent":"高山子ども育成課長","answer":"時間設定そのものが、幼稚園や学校等がある時間ということで午前中の時間に設定したという経緯もありますので、今後いわゆる部屋の確保なども含めて、こういった事業の充実については検討してまいりたいと考えております。","voiceIndex":28,"id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"実際、私もそういうお声をお聞きして、それでどういうことなのだろうなと思って、この機会がありましたから、今改めてお聞きをしていますけれども、やはりそういうところまでしっかりとケアをしていくということが、お母さんたちのリフレッシュにつながるのだろうと、いろいろ保育園に預けられている方とのバランスがさまざまある中での施策展開は、非常にすばらしいことなのですが。","respondent":"中元広報広聴課長、中山障害者福祉課長","answer":"こちらといたしましては、区の施設はさまざまな目的、利用者の方もいらっしゃいますし、どこまで拡大していくというのは所管とも調整しながら進めてまいりたいです。同様に、今後の展開につきましては、広報広聴課と相談しながら進めてまいりたいと考えています。","voiceIndex":30,"id":"exchange-012"},{"speaker":"つる委員","kind":"質問・要望","question":"４０年代に建てられたものが１５館、新しくても昭和５８年で５０年代が１０館ということで、これはこれまでに耐震化ですとか、長寿命化を図られている中で、コンクリートの長寿命化をさせたときの寿命としては６５年まで引っ張るなど、さまざまな考え方が施設のあり方についてはあるかと思いますが、２点目に確認させていただいた多世代交流支援施設という視点での拡充という部分で。","respondent":"高山子ども育成課長","answer":"委員ご紹介のとおり、児童センターにつきましては、築年数がたっております。今後、保育園などの改修の機会を捉えまして、施設がより使いやすい形で整備できるよう検討してまいります。","voiceIndex":33,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"１３７ページのひろまち保育園開設経費について、区立認可保育園の業務委託問題について伺いたいと思います。私は、どうして防げなかったのか、防ぐには何が必要なのか、この点を中心に伺いたいと思います。保育方針について、今年５月ごろから法人が態度を変え、双方の認識にずれが生じたと説明がありました。伺いたいのは、わずか１カ月間で法人の態度が変わった原因は何なのか伺いたいと思います。","respondent":"竹田保育課長","answer":"ところが、法人は本年５月ごろより、ひろまち保育園を法人が全国展開する他の園と同様に考え、その１つに過ぎないというふうに態度を変えて、相互の認識にずれが生じたものです。","voiceIndex":36,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、態度を変えた原因は何かということです。改めて、わずか１カ月で法人の態度が変わった原因は何か伺いたいと思います。","respondent":"竹田保育課長","answer":"区の保育の方針である、「のびのび育つしながわっこ」等に基づきまして、適切な運営を依頼しているところでございましたが、それが先方の考え方と相違が出たです。","voiceIndex":38,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"区が態度を変えたことを認識したのは５月ということですけれども、結果的に夢工房ははじめからフランチャイズに固執していたのか、それとも４月までは夢工房は区の方針に従うと考えていたのか、現時点で品川区自身はどう考えているのか、この点を伺いたいと思います。なぜ態度が変わるなど実際にやってみないとわからないのか、原因を伺いたいと思います。","respondent":"竹田保育課長","answer":"保育の方針につきましては、さかのぼれば事業者の公募の際から系統的に明示し、契約に当たっても覚書、仕様書をもとに十分に確認させ、承諾をとっておるところです。十分話し合いを重ねてまいりましたが、実際に現場で起こることです。","voiceIndex":40,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、そもそも夢工房は初めからフランチャイズに固執していたのか、それとも４月までは区の方針に従うという考えだったのか、区はどちらと思うのかと聞いたのです。お答えください。そしてもう１つは、実際にやってみないとわからなかったのはなぜなのか、その原因を伺いたいと思います。","respondent":"竹田保育課長","answer":"開設までは十分ご理解いただいて、いい意見交換ができていたと考えております。","voiceIndex":42,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"保育方針の隔たりとは、区が言う理由の１つなのですね。それがわずか１カ月で変わったことの原因が特定されずに明確にならなければ、再発防止策は打てず、また同じことが起こるという、こういう深刻な問題だと私は思います。このあらゆるリスクとは、今回の夢工房の件で言うと、具体的に何を差しているのか伺いたいと思います。","respondent":"竹田保育課長","answer":"今回の事案で言えば、保育方針が異なったという、認識のずれが生じたです。私どもとしましては、たとえリスクがあったとしても、公設民営を通して区の描くビジョンを今後も確実に実現していきたいと考えております。","voiceIndex":44,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"そこで仕様書について伺いたいと思いますが、１つは、結局、業務委託とは、契約に従って区の保育方針に従わせることができないということなのか、これが１点目。２点目は、仕様書が守られていなくても、契約不履行にならないということなのか、これが２点目。３点目は、何とか改善しようと思っても、区は直接保育園の園長に改善の指示ができないということなのか、それぞれ伺いたいと思います。","respondent":"竹田保育課長","answer":"その軽重によりまして、内容も異なりますが、今回は仕様書が基本的には守られているというふうに考えております。それから、園長への指示ですが、時と場合によりましては、指示も可能だと考えております。","voiceIndex":46,"id":"exchange-019"},{"speaker":"中塚委員","kind":"確認","question":"仕様書が守られていると言ったのか、いないと言ったのか、そこがわからなかったので確認したいのですけれども、改めてこの業者が変わるという重大な事態が起きているのに、これを繰り返さないための抜本的な対策が見えてこないという問題なのです。３つ目は、何とか改善しようと思っても、区はひろまち保育園の園長に直接指示ができないということなのか、それぞれはっきりご説明ください。","respondent":"竹田保育課長","answer":"仕様書を守っていただくことは、業務委託においての大前提でございまして、今回の案件については、守られていると考えております。ただ、お互いの考え方の、保育の方針の違いが生じましたので、今回は合意解除というふうになったものです。","voiceIndex":48,"id":"exchange-020"},{"speaker":"中塚委員","kind":"確認","question":"結局これだけの事態が起きているということは、区の保育方針を縛ることができないということですか。常勤の看護師の配置を守らせることができないということですか。それは改めて確認させてください。","respondent":"竹田保育課長","answer":"看護師の配置につきましては、４月当初から人材の確保が難しいため、求人中であるということで報告を受けておりますので、不正とは考えておりません。今後も仕様書の励行を求めてまいります。","voiceIndex":50,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、仕様書では縛ることができないのかということです。","respondent":"竹田保育課長","answer":"看護師につきましては、仕様書に基づいて配置を求めているところです。","voiceIndex":52,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"注意してください。私が聞いているのは、仕様書では縛ることができないということかと聞いているのです。先ほどからの答弁は、そこに答えておりません。委員長からも注意いただくようお願いをしたいと思います。改めて仕様書で縛ることができないということなのか伺いたいと思います。","respondent":"齋藤子ども未来部長","answer":"仕様書は契約ですので、総体的な効果といたしまして、当該当事者間を拘束するもの、こういう効力を持っていると考えております。","voiceIndex":54,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"拘束をするけれども守られていないとはどういうことですか。","respondent":"齋藤子ども未来部長","answer":"お互いの信頼関係が破壊されて初めて、解除をするかどうか考える。そのために私どもは話し合いを繰り返してきたです。引き続き３月末まで、パートナーとして円滑な事業を継続いたしまして、お子様たちに安心な保育を提供したい、これが私どもの考えです。","voiceIndex":56,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"そして次に、もう１つ理由に挙げる姫路市の不正流用についても伺いますが、６月に不正流用の報道があったが、品川区では７月の選定時点では不正経費は想定できなかった、調査権もなかったなど、９月２７日の文教委員会で説明がありました。この件への説明不足が後の合意解除に至った理由だと区が言うにあたり、この信頼が崩れる事実を業者選定時に把握できなかった原因は何なのか伺いたいと思います。","respondent":"齋藤子ども未来部長","answer":"姫路市につきましては業務委託ではございません。私立保育園に対する補助金です。あわせて、横浜もそうなのですけれども、私どもは、他の自治体の補助金の支出の正当性を調べる、調査権というものはございませんので、それはわからない、これは予見はできないです。","voiceIndex":58,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"その仕様書には、区に運営方針に従うことと、常勤看護師を１名配置するとあるけれども、結果として守らせることができない。しかし、それが契約不履行にも当たらない、子どもにとって重大な業者変更という問題を解決する抜本的な手段を区は持っていないということだと私は思います。今回の件を教訓に、民間委託の方針は撤回すべきだと思いますけれども、いかがでしょうか。","respondent":"齋藤子ども未来部長","answer":"小さいことは見逃さずに細かく保育の方針についてチェックをし、そしてまた、合意解除にたどりつけたというふうに考えております。品川区の保育の質を守るということを第一に考えて、これからも保育事業に取り組んでまいります。","voiceIndex":62,"id":"exchange-026"},{"speaker":"松永委員","kind":"質問","question":"最初に、２１１ページの職員給与費ですが、職員数が１人増えております。一方で決算額は前年度に比べると約６５２万３,５５６円減少している理由について伺いたいと思います。人数は増えているのに、なぜ減少しているのかです。一般事務費の臨時職員経費では、前年度より２２万９,９０２円減少しているのは、先ほど伺いました職員数と関係性はあるのか、あわせて伺いたいと思います。","respondent":"高森国保医療年金課長","answer":"こちらは、担当職員が休職をしたということで、給与費が下がっているような状況です。","voiceIndex":65,"id":"exchange-027"},{"speaker":"松永委員","kind":"質問","question":"理解できました。次に、２１２ページの保養施設費について伺いたいと思います。昨年度と比較しますと、この保養施設、日帰り温泉施設、両方とも利用者数が大幅に減少しております。特に日帰り温泉施設は、８８８人の減少です。この大幅減少の理由について伺いたいと思います。今後、この温泉施設利用をどのように捉えて、品川区としては進めていく方針なのか、あわせて伺いたいと思います。","respondent":"高森国保医療年金課長","answer":"施設ですけれども、平成２７年度につきましては、お台場にあります大江戸温泉物語を対象施設としているものです。","voiceIndex":67,"id":"exchange-028"},{"speaker":"松永委員","kind":"質問","question":"施設はわかりました。今後はどのように考えているのか伺いたいと思います。","respondent":"高森国保医療年金課長","answer":"大江戸温泉物語のほうとも十分協議をしてまいりましたが、合意に至らないということで契約ができない状態になりまして、平成２８年４月からは、皆さんご存知だと思いますが、平和島のクアハウスに、対象施設を変更いたしまして実施をしています。","voiceIndex":69,"id":"exchange-029"},{"speaker":"松永委員","kind":"質問","question":"私もそういった施設も利用させていただいておりまして、とてもいいことだと思います。次に、病児保育と、関連して病後児保育について伺います。現在の箇所数、園数は、２園と４園と変わらないですが、利用人数が減少しております。一方で、昨年度の決算額と本年度の決算額が変わっていないのです。減少しているのに、決算額が変わらないという理由について伺いたいと思います。","respondent":"竹田保育課長","answer":"病児保育につきましては、各１施設当たり１日４名、２施設で計８名の定員をお願いしています。","voiceIndex":71,"id":"exchange-030"},{"speaker":"松永委員","kind":"質問・要望","question":"理由はわかりました。当日キャンセルがちょっと多いということなので、その対策もぜひとっていただきたいと思います。私は今後預けられる方の気持ちとすれば、やはりどういった場所で、どういったものなのかということで事前にインターネットで保育園を調べたいと思います。ぜひともそうした写真等を載せていただければと思いますが、区の見解をお願いします。","respondent":"竹田保育課長","answer":"病後児保育につきましては、各保育園で保護者会等を通じて、必要な場合の利用方法等についてご説明しています。ご指摘のありましたホームページ等につきましては、今後検討させていただきたいと考えております。","voiceIndex":73,"id":"exchange-031"},{"speaker":"松永委員","kind":"質問","question":"それにちょっと関連しまして、もう１つ、福ナビという、とうきょう福祉ナビゲーションというサイトには、この西大井保育園に関して、サービス内容の中に、病後児保育については「なし」と掲載されております。そういった他のサイトとの連携というか、修正をお願いしたいとか、そういったお願い等はできるのでしょうか。今後そういった他のサイトについて、どのように対応していくのか伺いたいと思います。","respondent":"竹田保育課長","answer":"他のサイトの件ですが、事前にこちらのほうに調査があるもの、それからないものがあります。調査があるものについては、できる限りの協力はさせていただいておるところです。実態と異なる記載等がありました場合は、こちらから連絡して訂正をお願いしたいと考えております。","voiceIndex":75,"id":"exchange-032"},{"speaker":"松永委員","kind":"質問","question":"ぜひ対応をお願いしたいと思います。次に、先ほど、病児保育について少しお話をさせていただきました。実際、病児保育については足りないのが現状です。病院、保育園、保育士、ＮＰＯ団体などが全国で事業を行っております。品川としては、そうした事業者はどのくらいいるのか伺いたいと思います。その事業者との連携について、どのようにとっていくのか伺いたいと思います。","respondent":"竹田保育課長","answer":"病児保育です。品川区の基本的な考えとしましては、お子さんは非常に病状が変化しやすいということで、委託医療機関に併設した形で病児保育を実施しています。今後も増設等に当たりましては、医師会と十分協議させていただいて、病児保育を検討してまいりたいと思います。","voiceIndex":77,"id":"exchange-033"},{"speaker":"松永委員","kind":"意見","question":"今、委託することはないということだったのですが、もしこうした病児保育、病後児保育の開園とか開設が難しければ、やはり訪問型を増やしていく必要があるのではないかと私は考えております。品川区として訪問型についてどのように考えているのか、お考えをお知らせください。","respondent":"竹田保育課長","answer":"品川区の病児保育は、医師の管理下にある施設でお預かりいただくというのが基本的な考え方です。ただ一方で、国からもさまざまな考え方が今示されているところですので、国の動き等を十分注視しながら、今後、検討してまいりたいと考えております。","voiceIndex":79,"id":"exchange-034"},{"speaker":"松永委員","kind":"質問","question":"厚生労働省では、病児保育施設の普及を進めていくと言われている中で、今後、政府が掲げている１億総活躍社会の実現に向けて、子育てと仕事の両立支援を図り、２０１４年度では、約５７万人だった利用者を、２０１９年度には、１５０万人に増やすという計画が立てられております。もしされていなければ、今後お願いしたいと思います。そうした医師会等との今後の連携を伺っていきたいと思います。","respondent":"竹田保育課長","answer":"過去にも増設については医療機関等と別途お話し合いの機会を持っておりますし、先日も医師会の幹部の方と、この件については議論したところです。今後もしっかりと、子育てと就労の両立という保護者のニーズを支援していきたいと考えております。","voiceIndex":81,"id":"exchange-035"},{"speaker":"松永委員","kind":"質問","question":"ぜひ今後、品川区に住んでいてよかったと思える将来性のあるまちづくりに取り組んでいただけたらと思います。最後に、１３２ページの児童虐待防止対策強化啓発について、関連して１２９ページの障害者虐待防止対策費について伺いたいと思います。この児童虐待防止対策強化啓発の内容について伺います。","respondent":"高山子ども育成課長","answer":"私のほうから、児童虐待防止対策強化啓発ということで、この事業の中身についてご説明いたします。","voiceIndex":83,"id":"exchange-036"},{"speaker":"松永委員","kind":"提案","question":"こうした中で、提案になるのですけれども、配偶者暴力対策や児童・障害者・高齢者虐待対策について、基本計画策定委員会の中には、法テラスの、法律の専門家の方がおられますが、他の法律の専門家である士業の方との連携もとっていくべきだと私は思います。ぜひ今後、そうした他士業の方に対しても連携の取り組みをしていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":85,"id":"exchange-037"},{"speaker":"筒井委員","kind":"質問","question":"生活保護費、自立支援事業についてですけれども、今現在、生活保護受給者世帯数が増加傾向と言われておりますけれども、品川区でのそうした受給者増に対する、これ以上増やさない、生活保護受給状況から脱していただくための自立支援事業、これは重要だと考えておりますけれども、今現在の、区の自立支援事業の成果についてお聞きしたいと思いますけれども、成果はいかがでしょうか。","respondent":"伊東生活福祉課長","answer":"主なところといいますと、就労自立支援ですとか、金銭管理支援ですとか、子ども家庭支援ですとか、就職力アップ支援、そういう形で、なるべく自立をしていただいて、通常の安定した生活を送っていただけるように、さまざまな各種支援をしているというような状況です。","voiceIndex":87,"id":"exchange-038"},{"speaker":"筒井委員","kind":"質問","question":"成果をお聞きしたのですけれども、具体的にいかがでしょうか。","respondent":"伊東生活福祉課長","answer":"ですので、自立していただいたという形になります。それと、自立までは至りませんけれども、就労を開始したというところで、３００世帯の方、人数的には４１８人ですけれども、そういう人数の方が一部就労ということで若干の収入を得ていただいたというような状況にあります。","voiceIndex":89,"id":"exchange-039"},{"speaker":"筒井委員","kind":"質問・要望","question":"引き続き、積極的に自立支援事業、この成果を上げていっていただきたいと考えております。次に、生活困窮者自立支援事業についてお聞きしますけれども、これは生活保護費が第三のセーフティネットと言われている中、この生活困窮者自立支援事業は第二のセーフティネットと言われておりますけれども、この事業の意義と重要性をお聞きします。","respondent":"伊東生活福祉課長","answer":"今言ったように、生活保護に至る前の段階でさまざま自立支援策を講じまして、何とか安定した生活を長く続けていただく、そのような目標、目的で施行されたというふうに認識しております。","voiceIndex":91,"id":"exchange-040"},{"speaker":"筒井委員","kind":"質問","question":"具体的にその就労支援の成果と、あと、金銭管理の支援を行っていると思うのですけれども、その成果についてお伺いいたします。","respondent":"伊東生活福祉課長","answer":"それで、その５件の方に関しては、前段階の支援ですので、現状では、５件全員が就労に結びついたということではなくて、継続的に今も支援している方と、あとは、一部就労した方がいると把握しています。","voiceIndex":93,"id":"exchange-041"},{"speaker":"筒井委員","kind":"質問","question":"第二のセーフティネットと言われており、これは非常に重要であり、また生活保護受給者に至らないための手法ということで非常に有効だと考えております。ですが、件数がまだ少ないのですけれども、潜在的にはこれは必要だと考えておられる方々、非常に多くいらっしゃると思いますので、そのあたりのＰＲについてはどうお考えでしょうか。","respondent":"伊東生活福祉課長","answer":"さまざまな形でリーフレットの配布ですとか、いろいろな会議体を使いまして、この制度の周知を図っているところです。末端まで、相談者のほうまで何とか行き届くような形での支援が必要かというふうに思っておるところです。","voiceIndex":97,"id":"exchange-042"},{"speaker":"筒井委員","kind":"質問","question":"ぜひとも引き続き積極的なＰＲをお願いしたいと考えております。例えば、今現在、品川区役所は火曜延長窓口、そして日曜開庁をやっておりますけれども、ぜひともそうしたことにあわせる形で、このセンターの開設時間と日数の幅を増やすべきだと考えておりますけれども、その点、いかがお考えでしょうか。","respondent":"伊東生活福祉課長","answer":"現状で、そういったお話は来ていないということと、体制的な理由もあり、開設時間と日数の幅については、現状のままとしつつも、今後の推移を見ながら考えていきたいと思います。","voiceIndex":99,"id":"exchange-043"},{"speaker":"筒井委員","kind":"質問","question":"ぜひとも、この暮らし・しごと応援センターを頼られる方が増えてきましたら、時間の幅、開設日の幅の拡充をお願いしたいと考えております。次に、高齢者外出習慣化事業と、外出同行支援事業についてお伺いいたします。この事業の概要と、その重要性についてお伺いをいたします。","respondent":"松山高齢者地域支援課長、永尾高齢者福祉課長","answer":"重要性につきましては、ご本人に栄養バランスのとれた食事を提供し、介護予防と地域における仲間づくりを推進するという重要な目的があります。もう一方で、支えるボランティアにつきましての担い手づくりという２つの側面があります。私からは、外出同行支援についてご説明いたします。内容といたしましては、品川区協働提案事業として、介護保険制度など公的サービスで対処できない支援を実施するということで、平成２４年度から実施をしております。","voiceIndex":101,"id":"exchange-044"},{"speaker":"筒井委員","kind":"質問・要望","question":"だからこそ、今、外出習慣化事業、現在、月１回になっているのですけれども、これを月２回に回数を増やしたり、また、外出同行支援、これも今、基本的には月１回ですけれども、月２回に回数を増やしたり、また、外出同行支援事業に限って言いますと、この費用、高齢者の方にとって、まだやはり高い、負担だというお声を頂戴しておりますので、これも費用を２割程度減額するなど、そうした回数の拡大と。","respondent":"松山高齢者地域支援課長、永尾高齢者福祉課長","answer":"回数増ということにつきましてですが、今現在、運営側が栄養士を含む専門職２名のほか、サポーターというのは同じ介護予防事業の中の料理教室の修了生であるシニアボランティアの方が実際に調理場のある施設を活用しながら。実施しておりますヘルパー事業所と人材確保の関係も含めて検討していきたいというふうに思っております。","voiceIndex":104,"id":"exchange-045"},{"speaker":"田中委員","kind":"確認","question":"１２８ページ、１項２目地域見守りネットワーク事業と、１３７ページ、２項３目給食食材放射性物質検査、そして１３９ページ、すまいるスクール運営費について、そして１２９ページ、１項３目移動支援事業（ガイドヘルプ）について伺います。「しながわの福祉」の冊子にも数が載っていますが、改めて２０１３年からの累計で結構です、町会、自治会の取り組み実数と配布総数を伺います。","respondent":"大串福祉計画課長","answer":"あわせて、さつきのほうにもこういった形での発注を行うことによって、一定の補助効果があるというふうに認識している事業です。","voiceIndex":108,"id":"exchange-046"},{"speaker":"田中委員","kind":"質問・要望","question":"本年５月ごろでしたが、生活者ネットワークにご相談がありました。このキットの存在を知った区民の方から、なぜ個人や有志の集まりで購入ができないのか、というものでした。生活者ネットワークとしては、町会の方を責めることもできないと判断しています。しかし、区民から情報キットが欲しいという要望は、区には届いていないのでしょうか。","respondent":"大串福祉計画課長","answer":"あくまでもやはりこれは、我々区といたしましては、町会、自治会による見守り活動に活用するツールというふうに認識をしています。","voiceIndex":110,"id":"exchange-047"},{"speaker":"田中委員","kind":"質問・要望","question":"要望があるかないかちょっとわからなかったのですけれども、２０１３年４月には、難病を抱えたひとり暮らしの方から救急医療情報キットを求める陳情がありました。生活者ネットワークにも要望する声が届いています。町会の高齢者の見守り事業は継続するにしても、このキットが必要だと思う方には届くような制度も再構築すべきだと考えますが、見解を伺います。","respondent":"大串福祉計画課長","answer":"今後も町会、自治会への周知あるいはご依頼を徹底させていただいて、この情報キットの活用を図っていきたいというふうに考えているところです。","voiceIndex":112,"id":"exchange-048"},{"speaker":"田中委員","kind":"質問・要望","question":"不安を抱えている方が少しでも安心して日々の生活ができるためにも、救急医療情報キットは有効に活用できると思いますので、検討を要望します。次の質問に移ります。すまいるスクール事業について伺います。予算書には、職員給与費が４１人ですが、決算書には４４人となっています。個々の差異を伺います。臨時職員雇用費が５３４人と計上されていますが、どういったときの臨時雇用の方たちなのでしょうか。","respondent":"高山子ども育成課長","answer":"臨時職員の雇用経費につきましては、一般的には、支援を要するお子様に関するケアということで、通常の配置に加えまして、プラスした人員配置ということで配置しているものです。","voiceIndex":114,"id":"exchange-049"},{"speaker":"田中委員","kind":"質問","question":"今年４月から時間延長と利用料金の変更がされました。変更前は１８時まですまいるスクールに通っていた子が、料金負担の増額から、１７時に切り上げ、低学年の児童が１人で家で保護者の帰りを待つという、私たち生活者ネットワークが危惧していた状況になった児童の情報が私たちのところへ届いています。そこで伺うのですが、４月の改定以降、１８時帰りを１７時までに切り上げた児童の数を教えてください。","respondent":"高山子ども育成課長","answer":"制度の見直しにかかわります利用児童の移行の変動といった部分についての調査等は特段かけておりませんので、数値等は持ち合わせておりません。","voiceIndex":116,"id":"exchange-050"},{"speaker":"田中委員","kind":"質問・要望","question":"私たちが危惧していたように、先ほども申しましたが、保護者の帰りを１人で待つ児童がいます。４月から１７時帰りに変更した全ての児童がこのような状況とは言いませんが、区はそのような児童の把握をし、今後の対応を検討していくべきと考えます。は数の把握をすることを求めますが、見解を伺います。","respondent":"高山子ども育成課長","answer":"すまいるスクールにつきましては、平成１３年の第二延山小学校を皮切りに、３７校全てにおいて実施している事業です。","voiceIndex":118,"id":"exchange-051"},{"speaker":"田中委員","kind":"質問・要望","question":"今後、きめ細やかな対応されるよう要望して、次の質問へ行きます。次に、低学年児童の所在確認についてです。すまいるスクールの出欠確認は、いつごろ、誰が行うのでしょうか。出席をする届けが出ていた児童がすまいるスクールに来ていなかった場合、保護者への連絡は、いつごろまでに、誰がするようになっているのか教えてください。","respondent":"高山子ども育成課長","answer":"１、２年生につきましては、希望する方に関しましては、いわゆる登校時といいますか、利用開始時に保護者の意向を踏まえまして、来ていないような場合につきましては、確認の電話を入れさせていただいているところです。","voiceIndex":120,"id":"exchange-052"},{"speaker":"田中委員","kind":"確認","question":"この件では、保護者が家にいたことや、児童の行き先が家だったことなどがたまたま運がよかった事例だと考えています。保護者が出かけていたり、仕事へ行っていたら、児童はどうなっていたのでしょうか。児童が家ではなくどこかへ行っていたらなどと考えると、低学年の児童には、希望する方に出欠の確認の連絡をするのではなくて、所在確認の連絡の徹底が必要だと考えますが、いかがでしょうか。","respondent":"高山子ども育成課長","answer":"さまざまな利用者の方々のご意見がありますので、そういったものを踏まえまして、意に沿うような形で、希望する方にのみ対応していくのが適当と考えております。","voiceIndex":122,"id":"exchange-053"},{"speaker":"田中委員","kind":"質問","question":"児童の安全をまず考えてほしいと思います。時間の関係で先へ行きます。そのような障害に対して、すまいるスクールの教員、非常勤やアルバイトも含む先生たちで学び、情報共有を図る機会などはあるのでしょうか。そして、発達障害を持った児童に対して、その児童に合った対応や接し方を学校の先生とどのように情報共有を図っているのか伺います。","respondent":"高山子ども育成課長","answer":"すまいるスクールの特別支援の考え方としましては、学校との緊密な連携をとるということで、学校等からお教え願える範囲で情報収集に努めているところです。","voiceIndex":124,"id":"exchange-054"},{"speaker":"田中委員","kind":"質問・要望","question":"障害を持つ児童にはきめ細やかな対応が求められますが、障害そのものへの理解はもちろん、対応の必要な児童に対しての情報共有を本当に細かく学校とすまいるスクールで行うべきだと考えていますので、よろしくお願いいたします。平成２８年予算特別委員会の、意見表明のときにも申しましたが、検査は、「検出せず」を確認をすることに意味があります。質問をします。","respondent":"竹田保育課長","answer":"保育園給食の放射性物質の測定ですが、近年は学校給食と同じ業者がやっておりますので、同じ基準値で運営しているものと把握しております。","voiceIndex":126,"id":"exchange-055"},{"speaker":"田中委員","kind":"質問・要望","question":"違います。調べて、ホームページで見てみたところ、違いました。そのため、保育園の給食検査の検出下限値も学校と同じ基準に下げてもらえるよう要望したいのですが、いかがでしょうか。放射能対策に力を入れている町田市では、保育園の給食検査の検出下限値も０.９から１.４ベクレルに設定しています。区の見解を伺います。","respondent":"竹田保育課長","answer":"ホームページの数値は確認いたしますが、学校給食と同じ基準で報告は受けております。","voiceIndex":128,"id":"exchange-056"},{"speaker":"田中委員","kind":"質問・要望","question":"検出下限値を下げることと、区立保育園に限らず、認可保育園など、区内の保育園、幼稚園の給食の検査もぜひ行われるよう検討の要望をし、次の質問へ行きます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-057"},{"speaker":"田中委員","kind":"質問・要望","question":"それは理解しております。区立保育園に限らずに、認可保育園など区内の保育園、幼稚園などの検査も行われるよう検討を要望します。次へ行きます。障害者福祉の移動支援事業について伺います。２０１５年は通学への移動支援が初めて事業化しました。予算額と決算額と５０％相違があるわけですが、予算立ての根拠と決算額に至った理由を伺います。","respondent":"中山障害者福祉課長","answer":"移動支援のうち、通学等支援にかかわる金額ですが、９３万５,８２２円というふうになっております。平成２７年度は、初めて対象を拡大しまして、高次脳機能障害ですとか、発達障害の方も支援の対象といたしました。","voiceIndex":133,"id":"exchange-058"},{"speaker":"沢田委員","kind":"質問","question":"順番は前後しますけれども、まず、ひろまち保育園のことからお伺いしたいと思います。これは今後、より優良な事業者しか、もう品川区ではやはり事業ができないということをしっかり示すことができたことは収穫だったと思うのですけれども、こういった考え方についてお考えをお聞かせください。","respondent":"竹田保育課長","answer":"１つは、品川区の保育の質を重視する姿勢を広く示すことができたこと。もう１点は、不正経理等、問題のある事業者には、変更もあり得るということで、区の強い姿勢を示すことができたことが大きな効果だと考えているところです。","voiceIndex":137,"id":"exchange-059"},{"speaker":"沢田委員","kind":"質問","question":"委員会でもそういった話がありました。実際、今、現場の子どもたちに何か不利益が生じているということはあるのでしょうか。","respondent":"竹田保育課長","answer":"今回の合意解除が決定した後すぐに、８月２３日に説明会を開催しまして、保護者の方、約１１０名の方にご参加いただいて、私どもの説明を冷静に聞いていただいております。お声の中には、今の保育士等にできるだけ残っていただきたいというお声もありました。","voiceIndex":139,"id":"exchange-060"},{"speaker":"沢田委員","kind":"質問・要望","question":"これは１つまた別のことですけれども、ひろまち保育園に関してなので、ＪＲ広町社宅の解体が始まります。特に子どもたちは、やはり大きな車が通ると危ないということもありますし、保護者の方も危険だということがあると思うので、しっかりと安全対策を徹底していただきたいと思うのですけれども、ここの解体に当たって、事業者との話し合いはどうなっているでしょうか。","respondent":"竹田保育課長","answer":"ＪＲ広町社宅の解体工事につきましては、取り壊しの工事、近隣説明会が９月１２日に行われて、ひろまち保育園の保護者など約６０名が参加されたところです。区はさらに詳しい説明をＪＲに求めまして、１０月６日にＪＲ職員が区に来て説明しております。","voiceIndex":141,"id":"exchange-061"},{"speaker":"沢田委員","kind":"質問","question":"１３０ページの社会福祉施設費に関連して、高齢者、障害者施設の安全対策につきましてお伺いします。先般の障害者施設において信じがたい凶悪事件が起きました。区としても、早速補正で９月に高齢者、障害者施設の安全対策ということで、しながわ１１０番通報システムを設置するということになりましたけれども、この件も含めて区の現状の認識を伺わせてください。","respondent":"中山障害者福祉課長","answer":"区のほうでは、１１０番通報システムということで補正も組ませていただいて、全面的に施設の安全管理の体制を応援していきたいと考えております。","voiceIndex":143,"id":"exchange-062"},{"speaker":"沢田委員","kind":"質問・要望","question":"今、１１０番通報システム以外にもということでしたけれども、やはり防犯カメラとか、不審者対策をしっかりとこれからやっていかなくてはいけないという、こういうことをすること自体、本当に残念なことですけれども、緊急時の職員の連絡体制などをしっかりあらためて確認していただいて、訓練を先ほども行っているということでしたけれども。","respondent":"中山障害者福祉課長","answer":"そうした動向も見ながら、区としても、民間、区立含めて対応してまいりたいと考えております。","voiceIndex":145,"id":"exchange-063"},{"speaker":"沢田委員","kind":"質問","question":"１３２ページのしながわネウボラネットワークの検討経費でお伺いしたいと思います。","respondent":"高山子ども育成課長","answer":"私のほうから、ネウボラネットワーク事業についてのご説明をいたします。相談事業としましては、５つの児童センターに、ネウボラ相談員ということで新たに配置いたしまして、子育て全般にかかわります相談を受けつけているところです。","voiceIndex":147,"id":"exchange-064"},{"speaker":"沢田委員","kind":"質問・要望","question":"本当に多くの相談が来ていますし、ただ、この家事・育児支援ヘルパー事業は、利用が１７名ということでしたけれども、しっかりと事業のアピールをしていっていただきたいと思いますし、まだまだ知られていない部分があるのかなと思います。先般の報道で、国がベビーシッター利用の半額助成ということを、来年度から行うということを発表しました。","respondent":"高山子ども育成課長","answer":"品川区で実施しております産後の家事・育児支援につきましては、直接的なベビーシッターサービスというものを眼中に置いているわけではなくて、いわゆる産後の母体のケアということで、寄り添う形で家事・育児を中心に、食事をつくったり、あるいは掃除をしたり。","voiceIndex":149,"id":"exchange-065"},{"speaker":"沢田委員","kind":"質問・要望","question":"在宅の子育てを支援していくというのは、いろいろな選択肢があっていいかと思います。オアシスルームもそうですけれども、こういった新しい制度に対してもしっかりと区としても注視していっていただいて、これからも支援を拡充していっていただきたいと思います。１２７ページの長寿お祝い事業のことでお伺いします。改めて確認をさせてください。この内容と、現状についてどう考えるかお聞かせください。","respondent":"大串福祉計画課長","answer":"高齢者お祝い事業です。こちらは、お祝い品を贈呈することによりまして、その方のご長寿を祝福し、敬老の意を表する。あわせてこのお祝い品につきましては、民生委員の皆様に配布をお願いしております。そうした中での安否確認といった意味合いも含めて行っている事業です。","voiceIndex":151,"id":"exchange-066"},{"speaker":"沢田委員","kind":"質問・要望","question":"今回、品川区も、平成２７年度でいよいよお祝い事業の対象者が５,０００人を超えたということで、２,１００万円という大変高額な予算もついていますし、そういったことも含めて、ほかの自治体での取り組み等を参考にしながら、しっかりと今後の先を見ていっていただきたいと思いますけれども、お考えをお聞かせください。","respondent":"大串福祉計画課長","answer":"こうしたところで、民生委員に配布をお願いしているといった経緯を踏まえて、さまざまな形で、増大する高齢者の安全安心を確保するような形、どのような形でそういったものが確保できるかということは改めて検討しながら。","voiceIndex":153,"id":"exchange-067"},{"speaker":"沢田委員","kind":"質問・要望","question":"そういったことで、しっかりとやっていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":155,"id":"exchange-068","title":"町会・自治会支援"},{"speaker":"新妻委員","kind":"質問・要望","question":"３点お伺いいたします。１２７ページ、認知症高齢者の支援とケアの充実、同じく仮称ふれあいステーション事業、１４０ページ、品川児童学園運営費、戸越ルーム運営費についてお伺いをいたします。９月から始まったばかりですので、これからもっと増えていくものと思われますが、この登録をされております１９名は、どういう経緯で登録に至ったのか、もしわかれば教えていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"今後としては、そういう方だけではなくて、まだ認定もしていない、そういうサービスにつながっていない方にも広がればというふうに期待しているところです。それで、アイテムの配布予定の件数ですけれども、ちょっと手元に今すぐに数字が出ないので、後ほどご答弁いたします。","voiceIndex":157,"id":"exchange-069"},{"speaker":"新妻委員","kind":"質問","question":"わかりました。後ほどお願いをいたします。それともう１つ、この支援者という情報提供先がいくつか挙げられている中で、しなメールの登録者が入っておりました。例えば区として情報提供者の人数がこれぐらいが必要なのだというふうに想定があるのか、また、そのうちしなメールの登録者がどれくらいなのかということを少し教えてください。","respondent":"永尾高齢者福祉課長","answer":"現在、情報提供先としては、東京都行方不明認知症高齢者の情報共有サイトというところで、福祉関係の方のみ閲覧できるようなサイトがございまして、そちらのほうに登録をするということと、あと、各在宅介護支援センター、また協力事業者等を予定しております。","voiceIndex":159,"id":"exchange-070"},{"speaker":"新妻委員","kind":"質問","question":"ただ、このメールというのは、区民の方が区からの情報を欲しいということで登録をするのが通常かなと思うのです。例えば、これをホームページのトップのところに出していく、あえて皆さんにご協力をお願いしたいという趣旨で、わかりやすいところにホームページ上に出したらどうかと思うのですが、いかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"今後さらに協力されている方が増えるように、いろいろな方法で周知に努めていきたいというふうに考えております。","voiceIndex":161,"id":"exchange-071"},{"speaker":"新妻委員","kind":"質問・要望","question":"仮称ふれあいステーション事業の中の支え愛・ほっとステーションについてお伺いをいたします。平成２８年度までに１３地域センターのうち８カ所オープンをいたしました。相談件数は６４８件、訪問件数が５７９件、支援件数も３１１件との成果が出ていると確認をさせていただきました。そして、今後、残りの５つの地域センターがどういうスケジュールでオープンできるのか教えていただきたいと思います。","respondent":"大串福祉計画課長、永尾高齢者福祉課長","answer":"そうした中で地域センターの、例えば改修工事等々、予定が入っている場合もありますし、そういった中で連携を図りながら、なるべく残りの地域についても早期に開設ができるように検討を進めているという状況です。というのは、認知症だけではなくて、外出に不安のある６５歳以上の方も含まれるため、数字的になかなか把握が難しいというのが現状ですので、より周知をして増やしていきたいというふうに考えているところです。","voiceIndex":163,"id":"exchange-072"},{"speaker":"新妻委員","kind":"質問・要望","question":"ありがとうございました。先ほど、チラシの中にＱＲコードをつけているということでしたが、それをホームページのトップに持ってくることも可能かと思いますので、そういうところもぜひまた進めていただきたいと思いますので、これは要望で終わらせていただきます。最後に、児童学園のところをお伺いをします。この八潮に移転をしたことでの多少なりの影響ですとか、今の現状を少しお伺いしたいと思います。","respondent":"中山障害者福祉課長","answer":"現在は、もう半年たちまして、少しずつ使い方も見えてきたところではありますので、できるだけ早く親御さんが安心できるような体制をとってまいりたいと考えているところです。","voiceIndex":166,"id":"exchange-073"},{"speaker":"新妻委員","kind":"質問・要望","question":"ただ、その上でもやはりサービスは低下をしてはいけないと思いますし、平成３１年までは、この数年間は八潮での運営になるわけですので、八潮での体制を確立していかないといけないかなと考えています。八潮にある間も、仮移転という意識ではなくて、しっかりとした体制を整えていただきたいと思います。拡充ができるような体制をとっていただきたいと思いますが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"どうしても、例えば３カ月待つ前に療育が必要なお子さんは、実は障害者福祉課のほうにご相談に来ております。その相談の中で適切な療育につなげられるように、児童学園だけではなく、障害者福祉課も一丸となって対応してまいりたいと考えております。","voiceIndex":168,"id":"exchange-074"},{"speaker":"新妻委員","kind":"質問・要望","question":"個々の相談にもご対応いただいているということです。これはありがたいことかと思います。そして、この戸越ルームなのですけれども、平成３１年に南品川に戻って以降の戸越ルームの方向性について、お伺いします。南品川と戸越とあることで、また、よりこれは安心につながっていくと思うのですけれども、今後、戸越が残るのかどうか方向性を教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"現在は戸越ルームのほうは、ｃｏｍｐａｓｓ（コンパス）ということで、発達障害をお持ちのお子さんの支援の場ということで活用していますが、平成３１年度に新施設ができた後も、相談の１つの拠点ということで、これから整備を進めていきたいと考えております。","voiceIndex":170,"id":"exchange-075"},{"speaker":"新妻委員","kind":"確認","question":"存続の方向ということが確認をされまして、安心をいたしました。八潮、そして戻ってからの南品川、そして戸越と発達に悩んでいらっしゃる方が増えておりますので、体制強化を今後ともよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":172,"id":"exchange-076"},{"speaker":"飯沼委員","kind":"質問","question":"介護保険の質問です。成果報告書２２４ページ、保険給付費、２２６ページ、地域支援事業費、あと１３２ページの特別養護老人ホーム整備費についてお伺いいたします。品川区は既に動き出しているわけですけれども、この点をお伺いします。件数もマイナス３万５０１件となっています。こちらに移行したと思っていますけれども、この増と減の理由を教えてください。","respondent":"松山高齢者地域支援課長","answer":"委員おっしゃられるとおり、平成２７年度の介護保険制度改正により、品川区総合事業を開始いたしました。したがいまして、給付の部分につきましては、予防訪問事業、予防通所事業のほうに円滑に移行しておるというのが要因です。","voiceIndex":174,"id":"exchange-077"},{"speaker":"飯沼委員","kind":"質問・要望","question":"円滑に移行ということなのですが、ちょっと中身もお伺いいたします。保険給付の介護予防サービスを受けていた方が、地域支援事業の総合事業に移ったということなのですけれども、総合事業の予防訪問事業、この内容、また、予防通所事業のこの内容、教えていただきたいのと、この前のページの要支援１・２の方が今まで受けていた介護予防サービスとの違いがあるのかないのか教えてください。","respondent":"松山高齢者地域支援課長、永尾高齢者福祉課長","answer":"１点目のご質問の予防訪問事業の内容ですが、予防訪問事業の中には、予防訪問事業、生活機能向上支援事業、あと、管理栄養士派遣栄養改善事業があります。今回、介護予防給付事業から総合事業のほうに移行したものは、介護予防訪問事業と介護予防通所事業のみでございまして、そのほかの通所リハビリだとか、訪問リハビリ、訪問入浴、福祉用具、住宅改修等につきましては。","voiceIndex":176,"id":"exchange-078"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ここで受けた方々が要介護認定を受けた人なのか、それとも簡易な基本チェックリストのみの人もいるのか、それぞれ１万３,４１９人と１万７,７０３人となっていますが、認定を受けられたのか、チェックリストのみなのか、中身も一緒に教えてください。","respondent":"松山高齢者地域支援課長","answer":"介護予防事業と総合事業の違いなのですけれども、まず対象者のほうです、総合事業につきましては、要支援１・２相当、あるいは要支援１・２の認定を受けなくとも、基本チェックリストとケアマネジメントを使った方ということになります。","voiceIndex":179,"id":"exchange-079"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つは、受けられるサービスの内容に違いがあるのかないのかというのを聞きたいのです。この辺の違いがどこにあるのかをぜひ教えていただきたいと思います。これが１点です。認知症の方など、判断が難しくなっている中、要支援や要介護に該当する方が見逃されてしまうような危険があるのではないかなと思っていますので、この点、いかがでしょうか。","respondent":"松山高齢者地域支援課長","answer":"基本チェックリストのみという方につきましては、ご本人が基本チェックリストを確認し、その上で基本チェックリストを活用してケアマネジメントを専門家であるケアマネジャーが行いますので、今までと何ら違いはございません。","voiceIndex":181,"id":"exchange-080"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今までと変わりがないという受けとめ方でよろしいのでしょうか。この点はとても私は危険であると思っていて、とても同じとは言えないと思います。この点についてのお考えと、私は希望する人の介護認定をしっかりと保障していく、このことを今日はお約束をしていただきたいと思いますが、いかがでしょうか。","respondent":"松山高齢者地域支援課長","answer":"これまでもかなり自立支援に対する研修を複数回行ってまいりましたので、サービスの低下をすることは一切ございません。認定を希望される方につきましては、これまで何度も答弁したとおり、希望される方は認定をしております。","voiceIndex":183,"id":"exchange-081"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ヘルパーから声が寄せられています。要支援の方々の機能低下を招く移行は絶対にやめていただきたい、これは要望しておきます。一刻も早く特別養護老人ホーム、上大崎の次の特別養護老人ホームの計画を求めます。特別養護老人ホームも保育園もつくってほしい、声が届いています。この点と、小山台住宅跡地などにぜひ福祉施設をつくっていただきたいと思いますが、いかがでしょうか。","respondent":"大串福祉計画課長","answer":"特別養護老人ホームの整備につきましてですけれども、こちらにつきましては、ご本人の状態像、あるいはご家族の考えですとか、あるいは介護保険料へのはね返りですとか、そういったものを総合的に判断しながら、施設の整備については、これまでもやってまいりましたし。","voiceIndex":185,"id":"exchange-082"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ここのところずっと同じご答弁ばかりなのですが、今の住民の方の現状を聞いてどうなのかと思うのが１点と、平成２６年第３回定例会で質問して以来ずっと適地を検討中と言いながら２年が経過しています。高齢者の方々が人間らしく生活できるように、現状不足している特別養護老人ホーム、計画を直ちに立てていただくことを、本当に切に強く強く要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":187,"id":"exchange-083"},{"speaker":"木村委員","kind":"質問","question":"ユニバーサルデザインとは、全ての人ができる限り利用可能な、形状そのものにゴールはないという前提のもとに、常に改善していくという継続的な取り組みが重要かつ不可欠であると言われています。そこでお聞きしますけれども、スパイラルアップ図で示されているように、確かにゴールは見られませんが、内容をわかりやすくご説明願いたいと思います。","respondent":"大串福祉計画課長","answer":"基本的には、障害者や高齢者、こういった方たちに対して、どのような形が一番住みやすいまちかといったところ、あるいは、そういった方への接し方といったところでのソフトの啓発普及ということで、午前中もご答弁しましたけれども、例えば、おたがいさま運動ですとか。","voiceIndex":189,"id":"exchange-084"},{"speaker":"木村委員","kind":"質問","question":"伺いますけれども、物理的なバリアだけではなく、心のバリアを取り除くことが大事と謳っていますけれども、ハードの部分は予算と時間をかければ解決することと思います。しかし、日常生活や社会生活と心のバリアの解消には、多くの時間やエネルギーが必要だと思いますけれども、お考えをお聞かせください。","respondent":"大串福祉計画課長","answer":"この部分につきましては、日々の中で我々一人一人がどういったふうに考えていくかというのが一番大きなポイントになってまいりますし、そのきっかけとして、何らか我々のほうで、研修であるとか、講演会、あるいはイベント。","voiceIndex":191,"id":"exchange-085"},{"speaker":"木村委員","kind":"質問・要望","question":"この絵図を見ますと、計画・設計、そして評価、反映と、そして実施、ということですけれども、これの繰り返しが続いていくわけですけれども、「概念への理解は広がりつつあるものの、明確な方法は確立されておらず、各地域での創意工夫が求められています」とあるように、ゴールはないけれども、どのようになれば行政が理想とするような形になるのか、もう一度ご説明を願いたいと思います。","respondent":"大串福祉計画課長","answer":"ハードおよびソフトを含めて、さまざまな施策を展開する中で、区民の皆様方の中にそういった機運、こういった気持ちが醸成され、その中で全ての人にやさしいまちができ上がってくると考えているところです。","voiceIndex":193,"id":"exchange-086"},{"speaker":"木村委員","kind":"意見","question":"品川区も例外ではなく、高齢化に突き進んでおりますけれども、完成はないけれども、ユニバーサルデザインが進むことで、全ての人にやさしいまちになることが、今の私には想像がなかなかできないのですけれども、区内全体が、また区民がユニバーサルデザイン的な考えになるのは、かなりの時間がかかると思いますけれども、この区民の皆さんに周知をする、理解をしていただくためには。","respondent":"大串福祉計画課長","answer":"区民の皆様への周知といったところですが、先ほどもやさしいまちづくりのところでお話をさせていただきましたけれども、今月がおたがいさま運動の強化月間といったところ、こういった形で啓発、周知のためのパンフレットですとかの配布をやらせていただいておりますし、あるいは。","voiceIndex":195,"id":"exchange-087"},{"speaker":"木村委員","kind":"質問","question":"１２５ページ、上から１３行目、社会福祉協議会助成金の中から、さわやかサービス、２,８０９万円余についてお伺いいたします。社協自体は昭和２７年１１月に任意団体として発足をし、昭和３８年に社会福祉法人として認可されています。その中の事業の１つに、さわやかサービスがありますけれども、この事業内容を簡単にお聞かせ願えればと思います。","respondent":"永尾高齢者福祉課長","answer":"日常生活にお困りの高齢者等につきまして、介護保険等で行えないような家事援助サービス等を行っているものです。","voiceIndex":197,"id":"exchange-088"},{"speaker":"木村委員","kind":"質問","question":"このさわやかサービスですけれども、有償にて高齢者や障害者の方々のお手伝いをする事業とのことで説明がありました。高齢者のシルバー人材センターの事業の中にある、一般家庭部門と重なる部分があるように思うのですけれども、いかがでしょうか。その点をご説明願いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"それとあと、シルバー人材センターでも行っておりますけれども、シルバー人材センターのほうは、請負という形をとっているところでございまして、さわやかサービスはどちらかというと福祉的な考えの中で助け合いをやっているというようなところで、金額。","voiceIndex":199,"id":"exchange-089"},{"speaker":"渡部委員","kind":"質問","question":"１２６ページの福祉人材確保・定着のところと、１３４ページの子ども・子育て会議、それと１３９ページ、すまいるスクールを簡単に聞いていきます。例えば、そのような場合、やはりこれ、区立の施設ですから、区も積極的な関与をさまざまな形でしていかなければならないのかな、などというふうに思ったのですが、その辺のお考えをお聞かせください。","respondent":"永尾高齢者福祉課長","answer":"介護職についても、やはりチームで介護をするという関係もございまして、本来、自分がやりたいと思って入職したにもかかわらず、そういう思いと違ったような方針だったり、理念だったり。","voiceIndex":202,"id":"exchange-090"},{"speaker":"渡部委員","kind":"質問","question":"簡単に述べさせていただきました。１点、品川区は品川区介護福祉専門学校があって、３年間ですか、区内でお仕事をいただくと、授業料等が免除になるということなのです。逆にこれもまた気になったのが、例えば、３年間は区内で頑張るけれども、３年区内で頑張ったから離れてしまうのだという方は、実際どれぐらいいるのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"３年後の動向については、きちんとした調査をしていませんので、数字としてはわからないのですけれども、ただ、３年間その職場で勤められると、職員同士である程度の信頼関係が築かれますので。","voiceIndex":204,"id":"exchange-091"},{"speaker":"渡部委員","kind":"質問","question":"ですから、そのような中で、例えば３年たった、４年、５年、６年とかという方々には、何らかのインセンティブが与えられるようなことがあってもいいのかなというふうに考えておりますので、何かそういう機会がありましたら、検討いただければと思います。１３９ページ、すまいるスクールを先に１件。今回、制度が変わりまして、７時まで預かれるようになったということでいいのでしょうか。","respondent":"高山子ども育成課長","answer":"委員のご認識どおりでございまして、制度改正前のすまいるスクールにつきましては、５時を基本とし、それ以降の利用につきましては、就労等の特別な要件のある場合というようなことでございまして、そのようなご認識で間違いないと考えております。","voiceIndex":206,"id":"exchange-092"},{"speaker":"渡部委員","kind":"質問・要望","question":"お願いで終わります。１３４ページの子ども・子育て会議です。平成２５年からでしょうか、２５、２６、２７年と、始まってから回を重ねられて、平成２７年４月に、品川区子ども・子育て計画が出ました。このような計画の中でしっかりとサイクルを回していただいていると思うのですけれども、平成２７年度の会議と、今年の平成２８年度の会議の中で、何か大きな違いや特徴があったら教えてください。","respondent":"佐藤保育施設調整担当課長","answer":"子ども・子育て会議にかかわるご質問です。平成２７年度に関しましては、３回会議を行いまして、人口推計の内容であったり、事業の実績の方向を議論しております。","voiceIndex":208,"id":"exchange-093"},{"speaker":"渡部委員","kind":"質問","question":"これはまた会議を毎回なさるに当たって、例えば次、平成２８年度はこういうことをやりましたというときには、またそのときの人口推計と数字が新たなものに変わってくれば、またそれに対して話をしていくというような仕組みなのでしょうか。","respondent":"佐藤保育施設調整担当課長","answer":"人口推計等の反映の考え方なのですが、この計画の趣旨としまして、大きく実際と乖離してはならないということもありますので、その都度、その都度、最新の情報等を勘案して計画を立てたいと考えております。","voiceIndex":210,"id":"exchange-094"},{"speaker":"渡部委員","kind":"確認","question":"本当に内容を確認させていただいて、比較的こういうものは新陳代謝がなかなか難しいのかなと思っていたら、数字がしっかりと入れかわっていて、その実態に合った検討を進められている。実際やったことも示されている。これから先の方針も出されているということで、またこれからも注目していきたいと思うのですけれども、この中で、東京都が平成２７年８月に、東京都子供・若者計画を策定しました。","respondent":"高山子ども育成課長","answer":"策定の時期につきましては、現段階では表明できませんが、都道府県計画と整合をとる形で品川区独自の子供・若者計画をつくっていければと、そのような考えでおります。","voiceIndex":212,"id":"exchange-095"},{"speaker":"渡部委員","kind":"質問・要望","question":"明確に都の役割、区市町村の役割となっていて、「区市町村は住民に身近な自治体としてその区域内における子供・若者の状況に応じて必要となる支援の仕組みを構築することが求められます」また、地域の実情に応じた「区市町村子供・若者計画の策定」と、「地域における子供・若者育成支援ネットワークの設置」と挙げられているわけですから、今、課長からのお話がありましたように。","respondent":"高山子ども育成課長","answer":"委員ご紹介のとおり、子ども・子育て計画でありますとか、あるいは次世代育成支援対策推進行動計画でありますとか、いわゆる子供・若者にかかわるさまざまな計画で、それごとに会議体が立ち上がっていると、大体同じような顔ぶれになってしまうというところもありますので、今般。","voiceIndex":214,"id":"exchange-096"},{"speaker":"渡部委員","kind":"質問・要望","question":"そうしましたら、今のお話を伺いまして、では、そのようにお願いしますというところなのですが、要望しますと、やはりいわゆる青少年、児童および、これはもう生徒というのも入ってくると思いますが、いわゆる子どもたちがどういうふうに一人立ちをしていくか、それを社会全体で支えようというこの計画だと思うのです。期待しています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":216,"id":"exchange-097"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは、１３０ページ、障害者週間・記念のつどい、同じく１３０ページ、障害者作品展、また同じページで、芸術活動支援事業、前後しますけれども、１２７ページ、認知症高齢者の支援とケアの充実についてお伺いをいたします。その点について、今年の開催においては何か工夫があるのかどうか、開催場所についてどのようなお考えかお伺いをいたします。","respondent":"中山障害者福祉課長","answer":"年々障害のある方もすごく力を入れて作品をつくってくださっているので、レベルがアップしているところです。もともとは第二庁舎の３階のロビーのところで開催し、より多くの方に見ていただこうということで主催をしてまいりました。","voiceIndex":218,"id":"exchange-098"},{"speaker":"あくつ委員","kind":"質問","question":"ＨＡＮＤＳＩＧＮというプロのダンスグループが会場と一体となって、私も汗だくになって一緒に踊りましたけれども、一般質問のご答弁の中で、今年から内容がちょっと変わって、障害者理解啓発事業に位置づけたというご答弁があったのと、実行委員会形式から区主催事業へ変わったという、このようなご答弁があったと思うのですけれども、今までと何が違うのか、この点を教えてください。","respondent":"中山障害者福祉課長","answer":"７団体として、社会参加の場を何かこういうつどいの形で実施するというよりは、やはり障害者差別解消法もでき、７団体の方たちが外に出るにつけても、やはり地域の理解が必要だということで、地域の理解を促進するような事業に転換していってはどうかということが。","voiceIndex":220,"id":"exchange-099"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そういう意味で、すごく今、日本の最先端を行っていると思うのですが、ちょっとこれはオリンピック・パラリンピックと絡んできてしまうのですけれども、ぜひそういう団体と絡んでいるのであれば、グローとか、愛成会とか、今回、障害児者総合支援施設の運営団体になるということですから、ぜひそういうところと協力をして、平成３１年度にそこが開設するのであれば。","respondent":"中山障害者福祉課長","answer":"ですので、平成３１年度に新施設開設、その次の年がオリンピック・パラリンピックということでもありますので、そういった全体のオリンピック・パラリンピックの事業とも絡み合いながら、品川区からこうした文化芸術の発信をしていきたいと考えております。","voiceIndex":222,"id":"exchange-100"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。これは全庁的に同じ理解で進んでいっていただきたいなというふうに思います。この件について、私はぜひ品川区もかかわってほしかったなと、実はほかの２３区のゆるキャラとかも出てきて、ほかの区の区長とかも来られて挨拶をしていたというところがあったものですから、そこについて、ぜひ今後かかわっていただきたいというところで、ご意見をお伺いいたします。","respondent":"中山障害者福祉課長","answer":"ただ、こちらの団体からは、区内の障害のある方をぜひご招待したいということで、私どものほうに２５０枚ほどチケットもいただいておりますし、その２３区長会の共催というところには、当然、品川区も入っているということでご理解いただければと思います。","voiceIndex":224,"id":"exchange-101"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１２７ページ、認知症高齢者の支援とケアの充実で、いつもお伺いしていますが、認知症カフェについて。全ての名称を教えていただきたいと思います。もう１つ、予算特別委員会のときに、品川区の８カ所について、認知症カフェ情報交換会を開催する予定になっていると聞きましたけれども、その現状と、こうしたネットワークづくりを今後さらに進めていただきたいと思うのですが、いかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"情報交換会ですけれども、３月１８日に認知症カフェの情報交換会を行いました。一堂に顔を合わせるのは初めてでしたので、それぞれの開催状況だとか、特徴だとか、運営上の工夫されている点などの発表を行ったところです。","voiceIndex":226,"id":"exchange-102"},{"speaker":"あくつ委員","kind":"質問・要望","question":"前に私は何度か申し上げましたけれども、回想法というのは、歴史館から懐かしグッズ、黒電話とか、洗濯板とか、そういうものを借りてきて、懐かしグッズを楽しむものではないのですよというお話をさせていただいて、心理療法なので、しっかり研修等もお願いしますというお話をしたのですけれども、その点、どのようになったのかということをお聞かせいただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"これらを参考にしながら、今、９月の中旬から八潮南グループホームで実施をしているところです。この実施状況も見ながら、例えば使用するキットの種類をどうするかだとか、職員の声かけの仕方などについても検討していきたいというふうに思っております。","voiceIndex":228,"id":"exchange-103"},{"speaker":"あくつ委員","kind":"質問・要望","question":"やはりそういうもの引き出すことによって脳を活性化するというのが、やはり事業の心理療法としての主の目的ですので、ぜひそこのところを力を入れていただきたいと思いますので、どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":230,"id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"成果報告書１３７ページのひろまち保育園で質問いたします。これまでにも何人かの委員のほうから質問がありました。それを今回、民営化をしたという、民営化の流れで今やってきたわけですけれども、その公設公営のとき、今もそうですけれども、今の品川区の保育を、保育の質のほうになりますけれども、その成果をどう考えているのでしょうかということを再度お聞きしたいと思います。","respondent":"竹田保育課長","answer":"それを今回、業務委託という形で私立の良さと融合させて、より質の高いものを実現させていきたいという思いで始めたものです。それから、区の元職員がどれくらいいるのかということですが、１３名ほどというふうに認識しております。","voiceIndex":232,"id":"exchange-105"},{"speaker":"西本委員","kind":"質問","question":"私立の良さ、公立の良さとおっしゃっていました。これ、具体的にはどういうところでしょうか。今回、ひろまち保育園において、品川区としては、保育の質という面から言うと、何を守っていただきたかったのか、私立の良さというのはどこにあって、それをどう選定理由という形で決めて、今回、委託業者に決めたのかということをお聞きしたいのです。","respondent":"竹田保育課長","answer":"そういった公立にはできない部分を参考に取り入れながら、より質の高いものというものを求めていきたいという考えです。","voiceIndex":234,"id":"exchange-106"},{"speaker":"西本委員","kind":"意見","question":"もろもろ、もろもろというのがちょっと多くて、よくわからないのですけれども、品川区は、保育の質は全国１位と言われているぐらい歴史があって、保育士たちの頑張りがすごかったのです。ということは、民間の事業所はなかなか品川区では事業展開できないということを意味しているのか、この辺が区としての見解がどういう方向性を持って、これからの民間活用という形で考えていくのかをお知らせください。","respondent":"竹田保育課長","answer":"１つは、不正経理等、問題のある事業所であれば、それは強い意志を持って事業者の変更をするという意志を持っていくということは今後も変わりません。それから、保育の質を重視するのだという、そういう姿勢も示すことができたというふうに先ほど答弁させていただきました。","voiceIndex":236,"id":"exchange-107"},{"speaker":"西本委員","kind":"質問","question":"結局、今回は、その質の担保ができないということで、契約解除という形になったと思うのですけれども、では、これからもそうでしょうけれども、次の委託業者を考えたときに、どういった部分についてその評価というか、検討をされるのでしょうか。ですので、この仕様書は何ですかということです。同じことを繰り返すつもりですかということを言いたいのですけれども、いかがですか。","respondent":"竹田保育課長","answer":"そういったものにつきましては、事業者が決まり次第、十分話し合いの機会を持ちながら、より理解を深めていただくようにお話し合いを続けていきたいと考えております。","voiceIndex":238,"id":"exchange-108"},{"speaker":"西本委員","kind":"質問","question":"理解とは何ですか。理解して、結局できなかったら何もならないではないですか。どこをどうやって理解をしていただいて、それで、これから３月までこの業者が運営されるのですけれども、１３人も区の前職員がいますから、この１３人の前職員の方々の頑張りがあるからやっていけているのではないですか。それが品川区の誇れる保育の質だと考えていますが、その辺はいかがでしょうか。","respondent":"齋藤子ども未来部長","answer":"それは何かと言えば、委員がおっしゃったとおり、１３人の保育士が区の、「のびのび育つしながわっこ」を頂点とした系統的な保育、熟練した保育の実施、こういったことを理解していたからです。","voiceIndex":240,"id":"exchange-109"},{"speaker":"西本委員","kind":"質問・要望","question":"それはおかしいと思います。結局、品川区の職員が一生懸命やっている。だから、今、守られているのではないですか。そこを私は守っていただきたい。それをどういうふうにこれから継承していくのか、民間のほうでもこれからいろいろな形態が出てくると思うのですが、理解を求め、そして選定のときにもうそれがしっかりと根づいた形での選定になっていけるのか、それはいかがですか。","respondent":"齋藤子ども未来部長","answer":"しっかりと引き継ぎ保育ができるように、新しい業者とは話し合いの場を持ってまいります。","voiceIndex":242,"id":"exchange-110"},{"speaker":"のだて委員","kind":"質問","question":"私からは、１２８ページの介護人派遣事業の同行援護について、１２９ページの共同生活援助事業と、施設給付費の就労移行支援等にかかわって、グループホームと就労継続支援Ｂ型についてそれぞれ伺います。他区では大体５０時間くらいです。これから察するに、実態としては３０時間が基本になっているのではないでしょうか、伺います。１カ月の平均支給時間も伺います。","respondent":"中山障害者福祉課長","answer":"品川区の中では、一応、上限としては６０時間ということを見ているところです。それで、今現在の平均的な支給時間ということですが、平成２７年度では、大体月３３.４時間ということになっております。","voiceIndex":245,"id":"exchange-111"},{"speaker":"のだて委員","kind":"確認","question":"済みません、今ちょっと確認ですけれども、必要な時間を給付しているということで、上限が６０時間ということかどうか、そこの確認です。","respondent":"中山障害者福祉課長","answer":"平均的に上限を６０時間というふうにはしているのですけれども、ただ、実際的には、その方の必要な時間数を勘案ということになっていますので、今現在、最長で月７５時間をご利用されている方がおります。","voiceIndex":247,"id":"exchange-112"},{"speaker":"のだて委員","kind":"質問・要望","question":"平均でいくと、３３.４時間というところで、ぜひ実態を、多分お話を聞きながら３３.４時間になっているということで言っていると思うのですが、やはり必要な分だけ支給されていれば、利用時間が拡大してほしいという声はないと思うのです。そして、利用者に６０時間使えることを伝えているのでしょうか。ここも伺います。そういったところも考慮していただきたいと思いますが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"それにつきましては、やはりどういった外出状況、社会参加をされているのかということをお伺いしながら、時間数の決定はさせていただければと考えています。","voiceIndex":249,"id":"exchange-113"},{"speaker":"のだて委員","kind":"質問・要望","question":"６０時間、上限で使えるということで、２３区調査でも基本時間が６０時間ということで言っているところで、利用者に伝えているのかということもお聞きしたので、そこもご答弁いただきたいと思います。心身障害者福祉会館の方とこの方は交渉をして、一定程度、時間を拡大されたそうですが、初めから必要時間の支給ができるようにしていただきたいと思いますが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"そういった一方で、供給側の状況もあるので、同行援護につきましては、一律に６０時間ということではなく、必要な時間数の勘案をさせていただいているところです。","voiceIndex":251,"id":"exchange-114"},{"speaker":"のだて委員","kind":"質問・要望","question":"６０時間のところで、要綱に記載され、ホームページで公開されているということですが、実際に利用されている方に直接伝えていただきたいと思いますが、それはやっていらっしゃるのか伺いたいと思います。そして、必要時間、最初から支給されるようにできない原因はあるのでしょうか。伺います。","respondent":"中山障害者福祉課長","answer":"それで、事業者が見つからなかったというところにつきましては、支給量、特に通院ですとかについては、必要な支援かと思いますので、そういったことにつきましては、ご相談いただいた心身障害者福祉会館もそうですし。","voiceIndex":253,"id":"exchange-115"},{"speaker":"のだて委員","kind":"質問・要望","question":"しっかりとやはり状況をつかんでいただいて、今後、打ち合わせというか、話し合いもしっかりして、その人の社会参加も含めて支給できるようにやっていっていただきたいと思います。現在は１１施設で６７人分ということで、平成２７年度と比較しても減少している状況です。現在、入所希望されている方の人数と、重度と軽度の割合を教えてください。","respondent":"中山障害者福祉課長","answer":"重度の方の割合ですが、障害者の程度区分は６までありますが、４以上を重度としたときに、区分４の方がお一人です。そのほかの区分ですと、非該当の方が１３人、区分１が２人、区分２が４人、区分３が７人というような内訳になっております。","voiceIndex":255,"id":"exchange-116"},{"speaker":"のだて委員","kind":"質問・要望","question":"今のお話ですと、希望が多いのは軽度の方になっていると思うのですけれども、今後、この軽度の方たち、どうしていかれるのか、この重度知的障害のグループホームにも入れるのか伺いたいと思います。そして、さらに厚生委員会でも新しいところを入れなくても、あと２５人分必要だと思っているということもおっしゃっていらっしゃいますので、ぜひ増設していただきたいと思いますが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"新しいグループホームについては、重度の方でも対応できるようにということで施設の整備を準備しようと考えているところです。ですので、申し込みの結果、重度の方ではなく、軽度の方が入られる可能性もあると考えています。","voiceIndex":257,"id":"exchange-117"},{"speaker":"のだて委員","kind":"質問・要望","question":"６月の厚生委員会では、グループホームの利用者は１２７名いて、区内定員が６７名というところで、区外利用者が６０人いるという説明でした。区外では家族が会いに行くのも大変です。区外では、例えば、どこに行っていらっしゃるのか教えていただきたいと思います。あわせて、一般質問で体験型グループホームの検討を行っていくということもおっしゃっていましたが、今の現状を教えていただければと思います。","respondent":"中山障害者福祉課長","answer":"昨年度の実績では、２名の方が体験型のご利用をされました。新しく平成３１年度に開設される新施設の中にも、グループホームではないのですけれども、ショートステイ１２床のうち２床については体験型というような形で利用を考えているところです。","voiceIndex":259,"id":"exchange-118"},{"speaker":"のだて委員","kind":"質問・要望","question":"区外は具体的におっしゃっていませんでしたが、結構遠いところもあるのでしょうか。わかれば少し教えていただければと思います。この状況を議会で尋ねると、区は利用率は１００％でないため、受けることはできると説明していました。しかし、今年度は就労継続支援Ｂ型の募集さえなかったと伺いました。募集がなかったのは事実でしょうか、伺います。ぜひ増やしていただきたいと思いますが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"きちんと適切に支援学校の卒業生への対応ということではやってまいりたいと考えております。","voiceIndex":261,"id":"exchange-119"},{"speaker":"渡辺委員","kind":"質問","question":"１３５ページ、保育士等キャリアアップ補助金と、そのほかの項目も保育人材の確保という観点で伺いたいと思います。ただ、この保育に関しては、当然ながら公共サービスとして提供すべきものということで考えていくというところです。それぞれこの項目がある中で、キャリアアップのところです。この人材確保の区内の状況をどういうふうに捉えているか教えてください。","respondent":"竹田保育課長","answer":"キャリアアップ補助金は、東京都が実施する保育事業者に対する支援でございまして、補助金の使途は、職員の賃金改善に限定されたものです。","voiceIndex":264,"id":"exchange-120"},{"speaker":"渡辺委員","kind":"質問","question":"大分話が先の未来が見えたぐらいな答弁をいただいて。それとあと、キャリアアップのところで、処遇改善で、何も賃金等にこだわっているよりは、これは私の印象ですが、非常にその先の質のところ、そこにこだわっている感じもありました。品川では今、どんなことを検討されているのか教えてください。そんな要因の主なものをどう把握されているか教えてください。","respondent":"竹田保育課長","answer":"しかし、区単独で行いますと、なかなかお集まりいただけない現状があるということがわかりましたので、今後は既存の大きなフェア等に参加するようなことも含めて検討していきたいと思っています。","voiceIndex":266,"id":"exchange-121"},{"speaker":"渡辺委員","kind":"質問・要望","question":"国であれ、都であれ、やはり現場の職員にとってみたら、自治体をはじめ、区が窓口であり、どうなっていくのかというところが内容のところだと思います。この辺の展開で、ニーズもすごくあるやに聞いています。直近の動きと、品川区のこれからの考え方を含めて、本人の、とにかく保育士の負担が軽減される、こんな制度の拡充は常々求めたいと思いますが、状況を教えてください。","respondent":"竹田保育課長","answer":"保育士の負担の軽減ということなのですが、国から示された幾つかの事業で、ＩＣＴ化による事務作業の軽減などが打ち出されていますので、そういったものも実際に有効性がどれぐらいあるのかということを検討しながら採用していきたいと考えております。","voiceIndex":268,"id":"exchange-122"},{"speaker":"渡辺委員","kind":"質問・要望","question":"最後に取りまとめて、今、一番項目でとにかく決算書に出ている中で有効だろうと、そうして多くの方が理解を得られる、まず家賃補助、この辺は拡充をしていったり、経済的にどうこうというと非常に難しいと思いますが、特に都市部では地方から出てくる方も多いやに聞いています。そして、最初の窓口は当然区となるので、その辺での見解、情報を教えてください。この辺でご答弁いただきたいと思います。","respondent":"竹田保育課長","answer":"保護者対応等ですが、私立保育園には研修の補助金を出しておりますので、そういったものも十分活用していただきながら、また、今週も私立保育園の保育士にお集まりいただいて、独自の研修を実施する予定ですので、さまざまな面で支援していきたいと考えております。","voiceIndex":270,"id":"exchange-123"},{"speaker":"塚本委員","kind":"質問","question":"私からは、１３５ページ、事業所内保育（区外）と、２２６ページ、介護保険特別会計の地域支援事業、主に総合事業につきまして伺いたいと思います。この少ないことについて、どのような要因によるものなのかということでのご説明をお願いしたいと思います。","respondent":"松山高齢者地域支援課長","answer":"１点目の大きなところとしましては、委員おっしゃられるとおり、一律の予防給付だったものが、予防訪問、予防通所事業ということで、品川区独自に進めてまいりました。今現在も事業者と連携しながら安定的に、サービスに利用者が満足して運営しています。","voiceIndex":273,"id":"exchange-124"},{"speaker":"塚本委員","kind":"質問","question":"８８.６％で執行率というか、支出率が低かったというのは、報酬改定で下がったからということなのですね。報酬改定で下がるということがそのまま支出率につながるというところでいいのでしょうか。","respondent":"松山高齢者地域支援課長","answer":"事業所数としては、区内の事業所、ご協力いただいていた事業所とは綿密に連絡をとっておりましたので、事業所数の拡大ということはございません。あくまでも今回は報酬改定によるものです。","voiceIndex":275,"id":"exchange-125"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、ちょっと予算が当初から多かったということだったのでしょうか。報酬改定されるのはわかっていたことだと思うので、その中で報酬改定を見込んだ上での予算ではなかったということなのか、なぜこだわるかというと、やはり予算として組んだものはしっかり執行してもらいたいという思いがあるので、その点についてもう一度だけお願いします。","respondent":"松山高齢者地域支援課長","answer":"そもそも総合事業の設定というのは、国の介護報酬が上限とされておりますので、区独自の予算の組み立てとしては、その上限をベースに考えたものです。","voiceIndex":277,"id":"exchange-126"},{"speaker":"塚本委員","kind":"確認","question":"そういうことであるということであれば、当初予定していたよりは少ない報酬改定をしたので、その差額が出たということだというふうにお伺いしましたけれども、この辺については、仮にそういうことであれば、報酬改定をもうちょっと上げてもよかったのではないかとか、そういう意見も出てきがちではあるかなとも思うので、いろいろとまたご検討をよろしくお願いしたいというふうにも思います。","respondent":"松山高齢者地域支援課長","answer":"今後はほっとステーションの開設時に合わせまして、順次、位置づけていく予定です。次に、生活支援コーディネーターの配置ですけれども、１３地区を統括する生活支援コーディネーターは、社会福祉協議会のほうに委託をして、４月に一人配置しております。","voiceIndex":279,"id":"exchange-127"},{"speaker":"塚本委員","kind":"質問","question":"最後に、この総合事業への移行につきましては、単に要支援１・２の方々の適正な地域に則した介護ということだけではなくて、より介護全体としての人材の再配置といいますか、より重度の方々にはより専門性の高い人についていただいて、やはりしっかりとした仕事をしていただくとともに、応分の報酬をというようなことも目的の１つの中に入っているのではないかというふうに、目的の１つというか。","respondent":"松山高齢者地域支援課長","answer":"やはり地域の活動の核となる地域住民の意識醸成ということで、協議体にかかわる方たちに全員いらしていただきまして、そちらのほうで品川区の生活支援体制整備事業のキックオフとするものです。","voiceIndex":281,"id":"exchange-128"},{"speaker":"塚本委員","kind":"質問","question":"１３５ページ、事業所内保育（区外）というところなのですけれども、これは、まず当初予算のほうを見ますと、事業所内保育というところで約２,８００万円ぐらい予算を組んでありましたが、今回成果報告書に記載されているのは、これの決算としての事業所内保育（区外）なのでしょうか。どういうものなのかご説明をお願いします。","respondent":"大澤待機児童対策担当課長","answer":"ただ、こちら、事業者から事業所内保育をやりたいということで相談は何件か受けているのですが、区としましては、事業所内保育をやるに当たっての要件として、地域枠、従業員のお子さんだけでなく、地域のお子さんも受け入れていただくということですとか。","voiceIndex":283,"id":"exchange-129"},{"speaker":"塚本委員","kind":"質問","question":"こういったさまざまな、いわゆる品川区の認可保育とはまた違う形なのかもしれませんけれども、こういったところも進めていくに当たっては、やはり保育課だけではなくて、他部署とのいろいろな連携が必要になってくるというふうに考えているのですけれども、そういった連携について、どのように進めているのか、また、進めようとするような今後の考えがあるのか、最後にお伺いしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"先月、一次の助成が決まりまして、１５０施設、国のほうで企業主導型で助成することが決まったですけれども、今回、品川区内に設置されるという企業はございませんでした。","voiceIndex":287,"id":"exchange-130"},{"speaker":"あべ委員","kind":"質問・要望","question":"私からは、１２８ページの障害福祉費にかかわるところから、日常生活用具、あるいは、項目にはないのですが、手話講習会、それから心身障害者福祉会館などについてお伺いしたいと思います。それから、１３４ページの保育園の関係で、入園に関して、それからひろまち保育園についても少し伺いたいと思います。現状での区の考え方と、他の類似施設とのすみ分け等々について教えてください。","respondent":"中山障害者福祉課長","answer":"老朽化の対応というところでは、ここしばらくは改修を加えながら利用していくというような方向で考えているところです。","voiceIndex":291,"id":"exchange-131"},{"speaker":"あべ委員","kind":"質問・要望","question":"やはり障害者独特の世界に閉じ込めるような道具にこだわるよりも、やはり同じ世界で同じコミュニケーションをとれるような道具にシフトしていく、私は八王子市のやり方はそのための１つの知恵だと思うのです。これ、ぜひ前向きにご検討いただきたいのですけれども、改めてご答弁をお願いいたします。これはぜひ時期を逃さずに、こちらは要望としておきたいと思います。前の２つ、よろしくお願いいたします。","respondent":"中山障害者福祉課長","answer":"その先、例えば手話がいいとか、筆談がいいとか、いろいろな中で次のステップとしては東京都のほうのご紹介もさせていただいているところですが、こちらは、中途障害のコミュニケーション講座のご利用者の声を踏まえながら検討していければと考えています。","voiceIndex":293,"id":"exchange-132"},{"speaker":"あべ委員","kind":"質問・要望","question":"保育園なのですけれども、入園の際に、あるいは、例えば学年が上がるときに、時短をとっていると退園をしなければいけないという声がお母さんたちから聞かれているのですけれども、そういった実態があるのかどうかというのを確認したいと思います。そういう実態が実際にあって、区としてそのような例があるのかどうかということをぜひ確認したいと思います。この場でいま一度ご答弁をいただければと思います。","respondent":"竹田保育課長","answer":"ひろまち保育園の選定の件ですが、選定方法に誤りはなかったと考えております。ただ、今後の選定につきましては、十分時間をかけて丁寧に、例えばプレゼンテーションの時間を長くする、それから質疑の時間を長くする等、丁寧に慎重に対応していきたいと考えています。","voiceIndex":295,"id":"exchange-133"},{"speaker":"あべ委員","kind":"質問","question":"多分、問題になってくるのは、認証から転園を申し込む部分だと思います。そこのお考えはいかがでしょうか。ひろまち保育園については、ここで含むと少し時間が足りなくなってしまうので、丁寧にというだけではない、わかりやすいご説明も必要ではないかと思います。ご答弁をお願いします。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"ひろまち保育園につきましては、十分事業者と話し合いの機会をもって、今はもう公募を締め切っておりますので、適切に個々の事業者について書類等、あるいはプレゼンテーション等で、十分調べて選定していきたいと考えております。それはプレゼンテーションの場ではそれを確認するということできめ細かい対応をして、事業者の方と、ひろまち保育園のさまざまな制約条件もありますけれども、ご理解いただいた中での運営事業者を選定したいと考えております。","voiceIndex":297,"id":"exchange-134"},{"speaker":"あべ委員","kind":"質問・要望","question":"私自身もこうすればすぐにそれが全て改善という策を今持っているわけではないですけれども、ただ、そこには１つの課題があるということはぜひ認識していただいて、時短であるとか、あるいはさまざまな休暇であるとか、そういった子育て支援のための方策が活かせるような全体としての仕組みを一緒に考えていきたいと考えていますので、ぜひ問題意識として持っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":300,"id":"exchange-135"},{"speaker":"高橋（し）委員","kind":"質問","question":"１３２ページの児童相談事業全般と、１３６ページ、保育園運営費についてお伺いします。今あった相談件数２３９件の中で、児童相談所に引き継いだ件数がどれぐらいで、その内容はどのようなものなのかを、お話ししていただける範囲で結構ですので、ご答弁をお願いいたします。","respondent":"高山子ども育成課長","answer":"やはり専門的な機能を活用することが必要と判断したケースということで、引き続き、区が主担当としてケースを抱えておるのですが、児童相談所に援助の要請という形で引き継いだものが４件といった数字になっております。","voiceIndex":302,"id":"exchange-136"},{"speaker":"高橋（し）委員","kind":"意見","question":"区が、専門的なところで都のほうに４件引き継いだということなのですが、今お話あったように、都のほうに引き継いだということなのですが、引き継ぐということ自体が連携しなければいけないというか、この仕組みの中でやっているわけなのですが、もしこの４件の中で、児童相談所の権限が区にあったとすれば、児童相談所に要請して、さまざまないろいろな支援を受ける。","respondent":"高山子ども育成課長","answer":"今後の話となりますが、児童相談所の移管等が生じた後には、一元化が図られるですので、そういった意味で、今以上にケース管理についてはきめ細やかな対応が図れるものと、そのように考えております。","voiceIndex":304,"id":"exchange-137"},{"speaker":"高橋（し）委員","kind":"質問","question":"一元化された場合には、今以上にしっかりとした体制がというお話を伺いました。今お話にありました特別区への設置問題については、もう過去に何人か、ほかの委員の方や、平成２８年第２回定例会でもご質問される方がいて、そこの答弁の中で、課題の具体的検討を行い、速やかな設置について取り組んでまいりますというふうにご答弁されています。","respondent":"高山子ども育成課長","answer":"主な点としましては、品川区が児童相談所を設置する、希望する理由でありますとか、移管後の組織の体制、それから一時保護や児童相談所の必要な人員等の各論の部分について検討を現在進めているところです。","voiceIndex":306,"id":"exchange-138"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"東京都は、今ある児童相談所を２３区に移管するかどうかは不明で、一部では移管をしないで２３区がそれぞれ手を挙げて設置できるところは設置するというような状況もあるやに伺っています。そのような中、今品川にある、児童相談所と新たに品川区が置こうとしている児童相談所との関係については、どのようにお考えですか。その各論の中で議論になっていたらお話ししていただければと思います。","respondent":"高山子ども育成課長","answer":"これまでの検討の経緯を見ますと、東京都は、人材と設備については期待をしてくれるなというような発言もあります関係で、現状、東京都との交渉のテーブルが設定できていない現下におきましては、区が独自にそういったものをまずは調達するという視点に立って、現在。","voiceIndex":308,"id":"exchange-139"},{"speaker":"高橋（し）委員","kind":"質問","question":"区が独自にというところで、先ほどもありました人材の確保というところが大変な課題になるのではないかと思います。児童相談所に派遣された区の職員の方がいらっしゃると思うのですが、そのような方々は、戻られて、現在の区のどのようなセクションでお仕事をされているのでしょうか。","respondent":"高山子ども育成課長","answer":"区では、これまで、複数名の福祉の職にある者を派遣しまして、派遣から戻った後は、例えば子ども育成課の児童相談係でありますとか、子ども家庭支援課の中における相談の部署のほうに配置をしておりまして、人材の有効活用を図っているところです。","voiceIndex":310,"id":"exchange-140"},{"speaker":"高橋（し）委員","kind":"意見","question":"今、お話があったように、人材の育成は非常に時間のかかるものでありますが、開設までの時間もありません。ぜひ人材の確保、そして虐待だけではなくて、警察との連携、あるいは障害を持たれた方の認定、措置権の問題、あるいは学校や教育総合支援センター、あるいは裁判所とのかかわり、あるいは不登校についても担当することになります。ぜひともよい方向で速やかに進めていっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":312,"id":"exchange-141"},{"speaker":"本多委員","kind":"質問","question":"成果報告書の１４０ページ、１４１ページの、生活保護費、１２７ページの高齢福祉費の高齢者クラブ等支援事業、または介護予防に関連して質問いたします。全世帯の所得は２.５％増と３年ぶりに上昇しました。質問は、扶助費の中の平成２６年度の成果報告書を見ると、国庫支出金返還金のみなのですが、平成２７年度の決算書では、国・都支出金返還金で、かなりの額で対前年増になっております。","respondent":"伊東生活福祉課長","answer":"金額に関しては、そういうことで、多少多めにもらっていたという部分があるということと、あとは、１つ大きな要素としましては、平成２６年度に関しましては、医療費の負担の部分、基金のほうに支払っているわけなのですけれども、そちらのほうの会計区分がちょっと変わりまして。","voiceIndex":314,"id":"exchange-142"},{"speaker":"本多委員","kind":"質問","question":"わかりました。１カ月分の相当額というのは、やはり大きいのだなと本当に思います。ただ、この医療費扶助費は、やはりウエイトが高いのでちょっと取り上げるのですけれども、例えば、後期高齢者医療制度などでも、バランスを合わせるためにジェネリックの使用を促しているという取り組みがありますけれども、この部分は、どういう取り組みなのか、その現状を教えてください。","respondent":"伊東生活福祉課長","answer":"そういう中で、我々としても、医療費の適正化ということで、さまざまな取り組みをしているです。ジェネリックの普及ですとか、レセプト点検ですとか、そういう形で取り組みを行って、適正化に向けて日々やっているところです。","voiceIndex":316,"id":"exchange-143"},{"speaker":"本多委員","kind":"質問","question":"１２７ページの高齢者クラブ等支援事業について伺いますが、平成２４年度から会員増強月間を高齢者クラブのほうで設けておりますけれども、今年も増加クラブ、３人以上、７人以上と、それぞれのクラブの表彰がされたというふうに聞いておりますけれども、そういった取り組みの現状、それと、輪投げも６月２３日に総合体育館で第１３回、品高連が主催として、盛大に行われたと聞いております。","respondent":"松山高齢者地域支援課長","answer":"１点目の高齢者クラブの会員増強の取り組みなのですけれども、確かに高齢者クラブは、全国的にクラブ数と会員数が年々減少傾向にあります。例えば平成２７年度につきましては、１１５クラブで、会員数は１万１,８６６人ということで、一昨年同期と比べて２１人の減でした。","voiceIndex":318,"id":"exchange-144"},{"speaker":"本多委員","kind":"意見","question":"これ、高齢者の方からヒアリングをしたのですが、すごく集中力も高まるし、運動機能も向上するし、爪先がポイントだというのですが、高齢者の皆さん、そういうことで、爪先が重要だけれども、日ごろの生活は介護予防では、爪先が転倒の原因になるから、歩くときはかかとで歩くように意識をしなければいけない、そういった部分で足の爪先やかかとについてすごく心得ている方がたくさんいらっしゃいますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":320,"id":"exchange-145"},{"speaker":"南委員","kind":"質問","question":"１３４ページの待機児解消対策等についてお尋ねしたいと思います。こういう実態、品川区はどういうふうに受けとめているのでしょうか。改めて区は、新しい制度ができましたけれども、自治体としての保育の実施責任、こういう状況で果たしていると考えているのでしょうか。伺いたいと思います。来年４月についての予測、これもどういうふうに予測しているのか、ここも教えてください。","respondent":"大澤待機児童対策担当課長","answer":"来年４月、平成２９年度の予測ですが、今のところ、乳幼児人口が増加しておりますので、それにあわせまして、４００人程度の申込者数の増加、去年から４００人増えますと、３,６８０人ぐらいの申し込みではないかというふうに予想しています。","voiceIndex":322,"id":"exchange-146"},{"speaker":"南委員","kind":"質問","question":"この来年度、３,６８０人という予測、この数字で見ると、待機児は生まれなくて済むのか、その辺について改めて伺います。保育の実施責任を果たしているのかどうかと聞いたのですが、努力をしている、こう言うだけで、果たしているのかという点については、明確な答弁がない、私はそういうふうに思っておりますので、この点について改めて伺いたいと思います。とりあえずそこまでお願いします。","respondent":"大澤待機児童対策担当課長","answer":"今のところの予測ですが、昨年の４月からの受入可能数から推測しまして、来年の待機児童数、今年の半数ぐらいになるのではないかというふうに思ってあります。区としての役割は、この間ずっと定員拡大をしてきておりますので、責任は果たしていると認識しています。","voiceIndex":324,"id":"exchange-147"},{"speaker":"南委員","kind":"質問・要望","question":"今の答弁は驚きました。そこから比べると、なぜ保育園は法律で決めてあるのに、全員希望者が入るような体制をとらないで済ませてきているのでしょうか。そういう状況を実施責任を果たしているというふうに答弁してしまっていいのでしょうか。それにもとるではないですか。認可保育園で、０歳から５歳までの受入れができる、そういう保育園でつくるべきだというふうに思いますけれども、いかがでしょうか。","respondent":"大澤待機児童対策担当課長、齋藤子ども未来部長","answer":"平成２９年の受入可能数ですが、今のところ、３,３００人というふうに見込んでおりますので、先ほどの申込数から受入可能数を考えまして、その中にはもちろん転園希望の方なども含まれますので、その分を差し引いて。子ども・子育て計画上の数値は、出生数をもとに算出をしておりまして、子ども・子育て計画上の出生数で見込めば、来年度でほぼ待機児童は０になる予定でございました。","voiceIndex":326,"id":"exchange-148"},{"speaker":"南委員","kind":"質問","question":"５００人ぐらいが、待機児、予想されるというお話ですよね。ですから、それではだめなのです。待機児は出さない。先ほど、ママたちの声を紹介したではありませんか。どういうふうに受けとめているのですか。区長、本当にそういう真摯に働き続けたい、働きながら子育てしたい、そういうママたちの願い、しっかり受けとめて改善させてください。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":329,"id":"exchange-149"},{"speaker":"若林委員","kind":"質問・要望","question":"１２６ページの、要介護度改善ケア奨励助成と、１３６ページの保育園運営費について伺います。次に、その自治体の中で、介護ロボットを導入している自治体はありますでしょうか。ありましたならば、改善など効果の報告は上がっていますでしょうか。最後５点目に、持続可能な介護保険制度の政策提言を国に対して予定しているですけれども、そのポイントについてお聞かせをいただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"政策提言につきましては、１０月２０日、２１日で、岡山で介護サミットを行いまして、そこで協議会をする中で、政策提言の内容を考えていきたいと考えています。内容としては、改善された場合での介護報酬の加算等について検討しようというふうに考えております。","voiceIndex":331,"id":"exchange-150"},{"speaker":"若林委員","kind":"質問・要望","question":"そのために、３０年度の介護報酬改定に盛り込む考えで、平成２９年度までの実施で実験をしてデータをしっかりとっていく、こういうお話がありました。そこで、国の方針、またこういう実験に対して、品川区またはそういった協議会等で今取り組みが進められていますけれども、国の方針、実験に対して、区のほうはどう捉えるのかということを１つお聞きしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"区でもそちらの利用の仕方などを検討しながら、国のまた報酬改定に備えていきたいというふうに考えております。","voiceIndex":333,"id":"exchange-151"},{"speaker":"若林委員","kind":"質問・要望","question":"保育園のほうです。３歳児の待機児童について、お考えをお聞きしたいと思います。来年度、平成２９年度、またそれ以降の３歳児、待機児童を出さないための取り組みについてお聞かせいただきたいと思います。例えば、小規模保育、また認証というふうにあると思いますけれども、取り組みをお聞かせいただきたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"小規模園につきましては、小規模園を卒園した後の受け皿としての公立認可、私立認可の連携園、こちらのほうは、今ちょうど各園と調整しておりまして、連携園として設定できるように、一部を除きまして。","voiceIndex":335,"id":"exchange-152"},{"speaker":"松澤委員","kind":"質問","question":"民生費で３点伺いたいと思います。１点目が、１２４ページの民生委員経費について。３点目が、１３５ページ、病児保育についてお伺いをしたいと思います。品川区民に対して民生委員、厚生労働省の委嘱なものですから、一生懸命仕事をしているわりには、どんなものかわからない部分がありますので、どのような役割を担っているのかについてもお伺いしたいと思います。","respondent":"大串福祉計画課長","answer":"３年に１回ということで、最初の頃はどうしてもこういった形になっておりまして、今後、その３年の間に少しでも欠員を埋めていくように努力をしていきたいと考えています。","voiceIndex":338,"id":"exchange-153"},{"speaker":"松澤委員","kind":"質問","question":"民生委員経費として４,３０２万６３８円、支出されておりますけれども、無給のボランティアという中で、これが決算で載っているのです。この内容についてお聞きしたいと思います。","respondent":"大串福祉計画課長","answer":"いわゆるこれの実費弁償分ということで、例えば通常の一般の民生委員であれば、月額８,６００円ということで活動費が支給されているです。決算上に出ております４,３００万円余という数字ですが、ほとんどが先ほど申し上げました民生委員の活動費に充てているというものです。","voiceIndex":340,"id":"exchange-154"},{"speaker":"松澤委員","kind":"確認","question":"今伺いましたけれども、４,３０２万円余が活動費実費弁償分ということで、東京都の負担金で品川区が払っているというのを初めて知りました。この費用全体ですけれども、これ、８,６００円というのは、月の費用ということなのでしょうか。その辺を確認しておきます。","respondent":"大串福祉計画課長","answer":"はい、ご指摘のとおりです。１カ月の活動費ということで、８,６００円を各民生委員にお支払いしているものです。","voiceIndex":342,"id":"exchange-155"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、年間で約１０万円ですよね。実は、人権擁護委員、保護司、これらも非常勤特別職なのですけれども、みんなボランティアなのですね。ある程度一定の身分保障を行うとか、制度そのもののあり方の再検討というのは言われておりますけれども、これ、品川区、当然品川区だけではなくて２３区共通なのでしょうけれども、この辺の考え方はどのように思っているのでしょうか。ひとつお願いいたします。","respondent":"伊崎地域活動課長","answer":"保護司の方の報酬ですけれども、保護司の方は、直接国のほうから委嘱を受けていらっしゃるということで、申しわけないのですが、区からの報酬という形ではお渡ししているものではございません。","voiceIndex":344,"id":"exchange-156"},{"speaker":"松澤委員","kind":"質問","question":"今、最初のときに、１２７ページの高齢者相談等事業として相談員２８２名、これは民生委員が務めているということで、私、先ほど、民生委員に対する手当が少ないのかなと言いましたけれども、高齢者を見てもらう、それの補完という言い方が正しいかどうかわからないのですけれども、そういうような一助になっているというふうに考えていいのでしょうか。この辺をお聞きしたいと思います。","respondent":"大串福祉計画課長","answer":"こうした形で民生委員、広く活動していただくことによって、品川区の高齢者の福祉が一定程度保たれているものというふうに我々は考えているところです。","voiceIndex":346,"id":"exchange-157"},{"speaker":"松澤委員","kind":"質問","question":"２点目にいきます。これは、助成割合が９割から１０割です、助成額がすごく高いわりには、なぜこれ、１年に４４件とか、５０件を切るような数字なのでしょうか。予算額の３分の１ぐらいしか使用されていないのですけれども、この点について、なぜこれが進まないのか、ひとつお願いします。","respondent":"松山高齢者地域支援課長","answer":"ただ、こちらとしては、必要性を訴えていくということが大事かなと考えております。","voiceIndex":348,"id":"exchange-158"},{"speaker":"松澤委員","kind":"質問・要望","question":"子どもの特性からキャンセルが多くて運営上は改善すべき課題がたくさんあるのですけれども、セーフティネットとして、ある程度、お金がかかるものという認識をもって取り組んでやるべき事業ではないですかという質問をしたのですけれども、今回、６月議会の中で、我が会派の鈴木博委員の質問の中で、区長答弁、現在の２カ所の病児保育施設の導入を検討していますというお答えがありました。","respondent":"竹田保育課長","answer":"まだ協議中ですので、具体的な数字等は今は申し上げられない段階ですが、協議を積極的に進めていきたいと考えております。","voiceIndex":350,"id":"exchange-159"},{"speaker":"松澤委員","kind":"質問","question":"この人数の拡大ということになりますと、病児保育実施施設の数を増やす、あと、預かり人数を増やすという、今は預かり人数を増やすということだったのですけれども、午前中の質疑の中でも、品川区は保育所の数は増やさないのだというような答弁だったように、よく聞こえなかったのですけれども、改めてお聞きをしたいと思います。","respondent":"竹田保育課長","answer":"増やさないというふうにお話ししたつもりはないのですけれども、確かに子どもが病気でも就労と両立のため預けたいという保護者のニーズは今後見込まれておりますので、地域バランス等を考え、両医師会と協議しながら、増設の検討もしていきたいと考えております。","voiceIndex":352,"id":"exchange-160"},{"speaker":"松澤委員","kind":"質問・要望","question":"今、地域バランスを考えるという話がありましたけれども、品川区内で２カ所では、遠くなる方もいるので、やはり何カ所か、本当に地域バランスをもって考えていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":354,"id":"exchange-161"},{"speaker":"藤原委員","kind":"確認","question":"この間もテレビで元弁護士が事故を起こして出ていましたけれども、品川区においては、こういう事故はあるのでしょうか、まず確認です。それと、品川区の実績が２９ページに載っていますが、申し立てが５０件ですね。事故がないのであるならば、事故が起きないような対策とか予防はどういうふうにとっているのかお伺いします。改めて友愛活動の目的、経過、成果、課題をお伺いします。","respondent":"大串福祉計画課長、松山高齢者地域支援課長","answer":"したがいまして、必ずその後見活動の中では社協が直接後見人に会うこともありますし、または、後見監督人ということで関与するという形をとっておりますので、そういう意味では、チェックの機構が働いている、こういったものが予防。課題なのですが、元気な高齢者が少し支援が必要な高齢者を見守る、あるいは話し相手になるということで、今現在、友愛活動部で友愛活動の手引きを使いまして、皆さんで勉強をし、いわゆるプライバシー保護のこと。","voiceIndex":356,"id":"exchange-162"},{"speaker":"藤原委員","kind":"質問・要望","question":"やはり、ここのシステムをしっかりしていただきたいと思います。現在の区としての評価は、まずいかがですか。それと、ひとり親家庭だけではなく、所得の低い層全体に広げるとか、あるいは学習以外の支援、子ども食堂なども話題になっていますが、そうした全体的な方向性について、これからどういうふうにしていくのか、具体的にお伺いします。","respondent":"廣田子ども家庭支援課長","answer":"子ども食堂等につきましては、子ども食堂をやっている、やりたい、手伝いたいというようなご意見をいただいているところで、そういう方々が情報共有できるような何か支援を区としてできないかというところも。","voiceIndex":359,"id":"exchange-163"},{"speaker":"藤原委員","kind":"質問・要望","question":"済みません、課長中心ではなくて区長中心だったのですね。心から期待しておりますので、貧困の連鎖を断ち切っていただきたいと思います。次に、１３４ページの待機児童解消対策なのですけれども、新しく担当課長になられて、待機児童なのですけれども、毎回いろいろなところで質問が出るのですけれども、しかし、待機児童解消ができない。なぜできないと思いますか。","respondent":"大澤待機児童対策担当課長","answer":"区としましては、ずっと定員拡大を実施していますけれども、なぜ待機児童が出るかというと、それがなかなか乳幼児人口の増加と希望される方の割合にどうしても追いついていかないという現状があって、待機児童が発生しているというふうに分析しております。","voiceIndex":363,"id":"exchange-164"},{"speaker":"藤原委員","kind":"確認","question":"今、説明を受けて、よくわかりました。待機児解消を一生懸命努力しても、それは解消できませんよね。やはりすべてよしということはないということを確認して次の質問をしますが、１２４ページ、国民年金ですけれども、年金の制度、いわゆる国としては１０年、今まで２５年でしたけれども、１０年納めていれば年金を支払いますよという制度に変わってきますよね。本当にこれで年金制度はもつのでしょうか。","respondent":"高森国保医療年金課長","answer":"確かに委員おっしゃったように、この秋の国会で、いわゆる受給資格を得るための納付期間を１０年に短縮した年金制度が今上程されている状況になっておりますけれども、本来、年金は、２０歳以上６０歳未満の自営業の方と、その家族の方、そして学生。","voiceIndex":365,"id":"exchange-165"},{"speaker":"藤原委員","kind":"質問","question":"課長、安心しました。私も５０を超えまして、年金のことを考える世代になりましたので、年金は破綻しないと、本当にありがとうあります。ただ、国民年金ですけれども、やはり年金で生活ができない方はストレートに生活保護に来るわけですね。年金で足りない分は生活保護費の支給がありますよね。だから、そこの財源を生活福祉課としてはどういうふうに考えているのか、ちゃんと押さえてあるのかお伺いします。","respondent":"伊東生活福祉課長","answer":"年金の部分の話ですけれども、生活保護の場合は、年金については収入充当ということで、その分を差し引いたもので最低生活費のレベルのところまで支給、足りない分の支給という形になりますので、今の１０年年金云々というところでは、受給資格を得て。","voiceIndex":367,"id":"exchange-166"},{"speaker":"藤原委員","kind":"質問","question":"最後に、もう高齢化しているわけですから、企画調整課にお伺いしますけれども、企画と生保と国保の課長と、そろそろ品川区の人口がこうなってということをお話し合いをして、財源とかを決めていくべきだと思うのですけれども、そういう話はもう始めているのでしょうか。","respondent":"柏原企画調整課長","answer":"全庁調整の立場で、そういった人口問題に関しても、各所管課と話し合いをしています。","voiceIndex":369,"id":"exchange-167"},{"speaker":"大倉委員","kind":"質問・要望","question":"小規模保育事業では、給食費についてですが、今現在、小規模保育施設でも、今、普通の１００人程度の認可保育園でも、同じような小規模保育施設でも、給食が求められていると思いますが、そうした献立の作成や、衛生管理、保育室内での弁当給食の提示など、いろいろ求められるものは多いのかなというところで、補助額としては、今、幾ら出ているのかお知らせください。","respondent":"高山子ども育成課長、竹田保育課長","answer":"私のほうからは、子育て支援情報発信アプリについてのご質問にお答えいたします。本年９月末のダウンロード件数ということで申しますと、３,０９０件という件数です。小規模保育事業のお問い合わせです。今、平成２７年度決算で、６億２,８００万円余を運営費として補助しています。給食費としては、特段補助はしておりません。","voiceIndex":372,"id":"exchange-168"},{"speaker":"大倉委員","kind":"質問・要望","question":"アプリですが、わかりました。給食費については、わかりました。運営費の中でということで。これ、給食も子どもにとっては健康の維持・増進のため、また、楽しくおいしく食べるという情緒的な働きがあるということで、ぜひ温かい食べ物、調理師がつくった手づくり給食提供というのは喜ばしいことだと思っていますが、今、現状、そういった手づくりでされているところがどのくらいあるかわかりますでしょうか。","respondent":"高山子ども育成課長、竹田保育課長","answer":"これまでのダウンロードの実績から見ますと、やはり当初の４月と比べますと、ダウンロードの件数は爆発的に増えているわけではないのですが、例月の推移で見ますと、順調にこの数値は伸びてきているというふうに考えております。今、小規模保育施設、区内に２１カ所ございまして、一部を除いて自園調理を行っているところです。今年度中に整備しまして、来年度からは全て自園調理で行う予定です。","voiceIndex":375,"id":"exchange-169"},{"speaker":"大倉委員","kind":"質問・要望","question":"はい、わかりました。いずれにしても、まだまだこれから数を伸ばしていって、情報発信というところでは、子育てで孤立化しないためにも、こういった周知をいろいろなところで図っていっていただきたいと思いますが、今、この周知については、どういった場所で、どういうふうにされているのでしょうか。教えてください。","respondent":"高山子ども育成課長、竹田保育課長","answer":"こちらは、当初は４月の子育て応援号に掲載いたしまして、その後は、各児童センターの掲示パネルでありますとか、あるいは、高齢者多世代交流支援施設、ゆうゆうプラザなどで行われております各種のいわゆるセミナーでありますとか。そういった利点を生かして運営されているところが数多くあります。運営費の給食の助成については、今のところ考えていないところです。","voiceIndex":378,"id":"exchange-170"},{"speaker":"大倉委員","kind":"質問・要望","question":"ぜひさらに利用してもらって、できるだけ情報発信を若い世代の人たちにしていくというところでも、工夫をしていっていただきたいと思います。アプリのほうですが、やはり一番私が聞く中で多いのは、こういったときにどうしたらいいかみたいなＱ＆Ａが、ほかのアプリでは非常に好評になっている部分なのかというところもありますので、ぜひその辺、研究していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":381,"id":"exchange-171"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１８９ページの国民健康保険事業会計と、２０７ページの後期高齢者医療について伺いたいと思います。私は何回か伺っていますけれども、明確な答弁をお願いしたいのですが、区としても国保の構造的な問題として、保険料が高い、こういう認識があるかということを確認をさせていただきたいと思います。","respondent":"高森国保医療年金課長","answer":"国保料が高いという認識はないのかというご質問ですけれども、国民健康保険は被用者保険に属さない全ての人が加入する制度でございまして、被保険者の方々の相互扶助で成り立っている社会保険制度です。","voiceIndex":383,"id":"exchange-172"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"高いかどうかということで私は伺ったのですけれども。保険料が高いという認識があるかということで伺ったのです。このことは、私は何回もこの間伺っているのですけれども、明解な答弁がないのです。１,７００億円です。平成２７年度決算で品川区に幾ら来たのか伺います。そして全額で幾らか。そして、その支援金はどう使われたのか伺います。そして、それをどうしようとしているのかについても伺います。","respondent":"高森国保医療年金課長","answer":"都からは８,７００万円ほど、同様に区からも８,７００万円ほどで、合計で３億６,０００万円ほどです。ただ、国からのお金もいろいろと実は計算が入り組んでいまして、細かい数字は申し上げることができないところはご容赦ください。","voiceIndex":385,"id":"exchange-173"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３億６,０００万円ということで、かなりの額になります。これをもしも保険料引き下げに使えば、１人当たり、約４,０００円引き下げることができるのではないでしょうか。３人世帯であれば、１万２,０００円引き下げることができる額だと思います。ぜひとも品川区でもこれを保険料引き下げに使っていただきたいと思うのですが、いかがでしょうかというのが１点です。","respondent":"高森国保医療年金課長","answer":"それぞれの自治体で保険料の計算をするときに、さまざまな形で対応しています。","voiceIndex":387,"id":"exchange-174"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"差し押さえの制限が国税徴収法で定められています。ところが、品川区は、これよりも少ない額、年金が４万円、内職の工賃が３万円、合計で７万円という方に対しても差し押さえを行いました。でも、これは私は法律の趣旨を損なうことになると思いますけれども、いかがでしょうか。このやり方は、まだこれからも続けていくつもりなのか、ぜひやめていただきたいと思いますけれども、いかがでしょうか。","respondent":"高森国保医療年金課長","answer":"私どもは、滞納している被保険者に対して、預金債権、給与を差し押さえした場合については、差し押さえ禁止額ということで、今、委員お話しありましたように、１４万５,０００円程度が差し押さえ禁止財産ということで除かれた額が差し押さえ金額になりますけれども。","voiceIndex":389,"id":"exchange-175"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"高過ぎる国保料が貧困世帯をより貧困におとしめていると思います。そして追い詰めることになっていると思います。食べるものも食べずに国保料を払うというのは、どう考えてもおかしいと思います。そういうことから考えると、この差し押さえ禁止額を超えた差し押さえというのは、やめるべきだと改めてお願いしたいと思いますけれども、いかがでしょうか。","respondent":"高森国保医療年金課長","answer":"私どもは、納付ができない方につきましては、窓口に相談に来ていただいて、ご相談いただくように、そのご相談をいただいた内容で、必要に応じて納付をいただく、分割納付をいただく、または一部、いわゆる請求をとめるなりの手続をとるというふうな形で進めています。","voiceIndex":391,"id":"exchange-176"},{"speaker":"浅野委員","kind":"質問","question":"２０３ページの特定健康診査事業費とデータヘルス計画策定等について、そして特定保健指導事業委託について質問します。かなりの費用でこのデータヘルス計画が策定をされているという状況ですが、主にどのような費用だったのか、数字だけを見ると、外部委託をされたのかなと思うわけでありますが、いかがでしょうか。","respondent":"高森国保医療年金課長","answer":"データヘルス計画策定に関しましては、策定の委員会を設けさせていただきまして、外部の有識者の方も含めまして、４回委員会を開催させていただいたのですけれども、委員の謝礼ということで、３７万８,０００円ほどという形になっておりまして。","voiceIndex":394,"id":"exchange-177"},{"speaker":"浅野委員","kind":"質問・要望","question":"状況はわかりました。今回のデータヘルス計画につきましては、肝入りでやられたかと思うのですけれども、平成２５年６月１４日、閣議決定で、全ての健康保険組合に対して、レセプト等のデータの分析、それに基づく加入者の健康保持増進のための事業計画として、データヘルス計画の作成、公表、また事業実施、評価などの取り組みを求められることが掲げられた。","respondent":"高森国保医療年金課長","answer":"ただ、そうは言っても、健診結果説明会とか、まち場に出まして、ＰＲ活動、国保の基本健診受診ＰＲ活動などを行い、地道に受診率向上に向けて努力をしています。","voiceIndex":396,"id":"exchange-178"},{"speaker":"浅野委員","kind":"質問","question":"今、ご答弁いただきましたとおり、かなり力を入れて受診率の向上も含めて検討されていることはこちらのほうでも存じております。その中で品川区は２３区の中で何番目ぐらいにデータヘルス計画を策定したのか。そしてまた、ほかの区のデータヘルス計画なども多分ご覧になられているかと思いますけれども、それと比較して、どのようなレベルにあるのか教えてください。","respondent":"高森国保医療年金課長","answer":"たしか私の記憶が正しければ、平成２７年３月に板橋区が内部でデータヘルス計画を策定したと聞いております。平成２７年度には４自治体ほどということで、状況を見ながら今年またそのほかの自治体が進めていくのだろうなという状況です。","voiceIndex":398,"id":"exchange-179"},{"speaker":"浅野委員","kind":"質問","question":"ちょっと裏話まで伺いまして、そういうこともあって、なかなか苦労しながら策定されたということかと思います。私がちょっと調べたところによりますと、東京都では国保データベースですか、ＫＤＢというのですか、こちらのほうはシステムとして構築をされて使える状況になっているのか、そこら辺まで私も調べ切らなかったのですけれども、既に供用されているのかどうか。","respondent":"高森国保医療年金課長","answer":"ただ、タイムラグがありまして、大体４カ月後ぐらいのデータになってしまうので、どうしても、例えば今、データヘルス計画の中で基本健診を受けた方を速やかにその次の保健指導とか、うまく回していくためには、あまりもタイムラグがあると。","voiceIndex":400,"id":"exchange-180"},{"speaker":"浅野委員","kind":"質問","question":"それとあと伺いたいのが、データヘルス計画を、今回、策定しましたけれども、大体どのぐらいのインターバルで改定をするのかということについて、お考えがあれば教えてください。特定保健指導事業委託ですけれども、この保健指導を受けられる施設は、品川区は３カ所というふうにも聞いておりますけれども、十分に受けられるのかどうか教えてください。","respondent":"高森国保医療年金課長","answer":"今年の１２月には、今年の部分について、評価分析ということで、来年度に向けた形での検討委員会を設ける予定になっています。それと、保健指導のほうは、地域センター、区内４カ所で現在対応ができる形になっております。","voiceIndex":402,"id":"exchange-181"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"民生費の第１項の社会福祉費、１２５ページの社会福祉協議会関連と、それから２項の児童福祉費で、１３２ページ、児童福祉費の中の児童相談事業に関連して質問させてもらいます。１点目が、社会福祉協議会関係なのですが、先日、私どもの部屋にパンフレットが届いて、それと同時に案内がありました。この辺のところで、なぜかなということで、そこからまず確認させていただきたいと思います。","respondent":"松山高齢者地域支援課長","answer":"ただ、このちいきの輪を広げるというキャンペーンは重要だと考えておりますので、あらゆる機会を捉えて、地域の方々とのつながりを深めて、ＰＲし、区としてもきちんと情報を共有し、バックアップしていきたいと考えております。","voiceIndex":405,"id":"exchange-182"},{"speaker":"鈴木（真）委員","kind":"確認","question":"各施設、いろいろなイベントを、プログラムをやっているのは十分承知しています。私もときどきお邪魔しておりますので。さっき言ったと思いますけれども、１２８も施設が出ていながら品川区は１つもないというのは、やはりこの中で品川区、私は「なぜ品川がやっていないの」と見られてしまうのが嫌だなというところがありますけれども、その点でもう１回確認を。","respondent":"松山高齢者地域支援課長","answer":"今後、各施設のほうにもきちんと情報共有しながら、区としてもこういったあらゆる機会にＰＲをきちんと掲載させていただきながら、東京都高齢者福祉施設協議会とも連携を深めていきたいと考えています。","voiceIndex":407,"id":"exchange-183"},{"speaker":"鈴木（真）委員","kind":"質問","question":"わかりました。答えは十分わかります。品川の中で支え愛を一生懸命やっている中、また１１月に講演会も開いて支え愛を進めていくことを目的にしていたのに、やはりこの辺は自分としては物足りなく感じていたので、ぜひこれからも進めてもらいたいという、支え愛を進めるためにも、何かいろいろなアピールする場をつくってもらいたいなということでの質問なので、その辺これからもよろしくお願いします。","respondent":"大串福祉計画課長","answer":"今回、東京都の補助協議が必要になってくるですので、区といたしましても、この法人と連携をしながら、最終的には国有地取得ができるような形でさまざまな支援をやっていきたいというふうに考えているところです。","voiceIndex":409,"id":"exchange-184"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今のお話で、補助協議というのは、これからどんな感じで流れていくのか、その日程的なものがわかれば教えてください。","respondent":"大串福祉計画課長","answer":"東京都の補助協議につきましては、今月末までには一定の計画書、また、最終的には１１月末までには提案書という形で流れていくものです。","voiceIndex":411,"id":"exchange-185"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今、聞き損ねたかもしれません。平成２９年度に土地を契約して、大体９０人規模とあったと思いますが、完成予定の時期がわかれば教えてください。","respondent":"大串福祉計画課長","answer":"そこから逆算いたしますと、法人といたしましても、平成３０年度に竣工ができればというふうに考えているところでございまして、予定といたしましては、平成３１年度中の開設を法人としては希望しているというふうに伺っているところです。","voiceIndex":413,"id":"exchange-186"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。ちょうど今、質問の中に入れたと思うのですが、これから区とのいろいろな関係も出てくると思いますので、区の希望に合わせた形で調整をしていただきたいと、これは繰り返しになりますので、要望で終わります。その中で、やはり今、政令市では横須賀市と金沢市がたしか実施したと思うのですが、この辺の状況は何かわかることがあれば教えていただけないでしょうか。","respondent":"高山子ども育成課長","answer":"一方で、神奈川県のほうからは、人的な支援をしていただいたということで、短期間での設置が可能であったというようなお話は伝え聞いているところです。","voiceIndex":415,"id":"exchange-187"},{"speaker":"鈴木（真）委員","kind":"質問","question":"区として、先ほど児童相談所移管推進委員会をつくっていらっしゃるという中で、これも聞き漏らしたかもしれませんけれども、区として設立の時期をどのぐらいを目途に検討していらっしゃるのか、その点も教えてください。","respondent":"高山子ども育成課長","answer":"国におきましても、平成２９年４月１日の児童福祉法改正法の施行後５年を目途に必要な支援の仕組みについてつくっていくというような発言もありますので、そういったものを注視しながら、設置の時期については、可能な限り早い段階のものということで考えております。","voiceIndex":417,"id":"exchange-188"},{"speaker":"鈴木（真）委員","kind":"質問","question":"児童相談業務の中で一時保護所の問題です。ごめんなさい、これは資料をもらった中の話で、正式なところは、もしかしたら細かく、まだ先方、担当の課長が出した資料ですから間違いない部分だと思うのですが、これが区に移管になると、相当大きな金額になってくる。これは品川として区長会に対してどのような形でお話を進めていらっしゃるのか、もしお答えがいただければ、ご見解をお聞きします。","respondent":"高山子ども育成課長","answer":"児童相談所の設置を希望する区については、それぞれの区のロードマップでありますとか、あるいは移管にかかる再検討といった検討の結果について、区長会事務局に提出する、そういった予定で進んでおります。","voiceIndex":419,"id":"exchange-189"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"２３区の総意、たしか１つ大変に反対している区があるとお聞きしているのですが、品川区としては、希望どおり、ぜひ児童相談所の設立に向けて手配をしていっていただきたいと思います。どうぞよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":421,"id":"exchange-190"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1424#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":122752,"voices":422}}]);
